window.DATA_CONTENT_LIBRARY = {"sections":[{"id":"bash-scripting","title":"Bash Scripting Deep Dive","icon":"terminal","category":"development","preview":"","source":"bash-scripting-deep-dive.md","words":1856,"parts":[{"id":"introduction","title":"Introduction","blocks":[{"t":"text","html":"<p>Functions, arrays, loops, and — the part most tutorials skip — how to write scripts that fail loudly instead of silently corrupting something three steps later.</p>"}]},{"id":"script-anatomy","title":"Script Anatomy","blocks":[{"t":"code","lang":"bash","code":"#!/usr/bin/env bash\n# ^ shebang — tells the OS which interpreter runs this file.\n# #!/usr/bin/env bash is more portable than #!/bin/bash (finds bash wherever it's installed)\n\necho \"Hello, SOLO\""},{"t":"code","lang":"bash","code":"chmod +x script.sh     # make it executable\n./script.sh              # run it\nbash script.sh            # or run it explicitly through bash without chmod"}]},{"id":"variables","title":"Variables","blocks":[{"t":"code","lang":"bash","code":"name=\"SOLO\"              # NO spaces around = — \"name = SOLO\" is a syntax error, not an assignment\necho \"$name\"              # always quote variables when reading them\nreadonly PI=3.14           # constant — reassigning it later throws an error\nunset name                 # delete a variable\n\nlocal x=5                  # only valid INSIDE a function — scopes the variable to that function"},{"t":"callout","kind":"tip","html":"<strong>Quoting rules that actually matter:</strong> "},{"t":"code","lang":"bash","code":"var=\"hello world\"\necho $var       # WRONG in most cases — unquoted, this splits on whitespace: prints as 2 args\necho \"$var\"      # RIGHT — preserves it as one string, including internal spaces\necho '$var'       # single quotes = literal, no expansion at all — prints the text $var"}]},{"id":"arrays","title":"Arrays","blocks":[{"t":"text","html":"<h6>Indexed arrays</h6>"},{"t":"code","lang":"bash","code":"fruits=(\"apple\" \"banana\" \"cherry\")\n\necho \"${fruits[0]}\"          # apple — array indices start at 0\necho \"${fruits[@]}\"           # apple banana cherry — all elements\necho \"${#fruits[@]}\"           # 3 — length of the array\n\nfruits+=(\"mango\")              # append an element\nfruits[1]=\"blueberry\"           # overwrite index 1\n\nfor f in \"${fruits[@]}\"; do     # correct way to iterate — quoted, with @\n    echo \"$f\"\ndone\n\nunset 'fruits[0]'                # remove one element (index 0), leaves a gap"},{"t":"text","html":"<h6>Associative arrays (key-value, bash 4+)</h6>"},{"t":"code","lang":"bash","code":"declare -A ages\nages[\"solo\"]=25\nages[\"ali\"]=30\n\necho \"${ages[solo]}\"           # 25\necho \"${!ages[@]}\"               # solo ali — all keys\necho \"${ages[@]}\"                # 25 30 — all values\n\nfor key in \"${!ages[@]}\"; do     # iterate keys, look up values\n    echo \"$key is ${ages[$key]}\"\ndone"},{"t":"text","html":"<h6>Common array pitfalls</h6>"},{"t":"code","lang":"bash","code":"echo \"${fruits[@]}\"    # correct — each element stays separate, even with spaces inside\necho \"${fruits[*]}\"     # joins ALL elements into ONE string — rarely what you want\necho $fruits             # WRONG — without an index, this only gives element 0"}]},{"id":"loops","title":"Loops","blocks":[{"t":"text","html":"<h6>`for` loop — three styles</h6>"},{"t":"code","lang":"bash","code":"# 1. Iterate a list\nfor fruit in apple banana cherry; do\n    echo \"$fruit\"\ndone\n\n# 2. C-style\nfor ((i=0; i<5; i++)); do\n    echo \"Number: $i\"\ndone\n\n# 3. Range\nfor i in {1..5}; do\n    echo \"$i\"\ndone\n\n# Iterate command output (careful — see \"reading files\" below for a safer pattern)\nfor file in *.txt; do\n    echo \"Found: $file\"\ndone"},{"t":"text","html":"<h6>`while` loop</h6>"},{"t":"code","lang":"bash","code":"count=0\nwhile [ \"$count\" -lt 5 ]; do\n    echo \"Count: $count\"\n    ((count++))\ndone"},{"t":"text","html":"<p><strong>The correct way to read a file line-by-line</strong> (avoids classic pitfalls with spaces/globbing):</p>"},{"t":"code","lang":"bash","code":"while IFS= read -r line; do\n    echo \"Line: $line\"\ndone < file.txt"},{"t":"text","html":"<h6>`until` loop (opposite of while — runs until the condition becomes true)</h6>"},{"t":"code","lang":"bash","code":"count=0\nuntil [ \"$count\" -ge 5 ]; do\n    echo \"$count\"\n    ((count++))\ndone"},{"t":"text","html":"<h6>`break` and `continue`</h6>"},{"t":"code","lang":"bash","code":"for i in {1..10}; do\n    [ \"$i\" -eq 5 ] && break        # exit the loop entirely\n    [ $((i % 2)) -eq 0 ] && continue    # skip to next iteration\n    echo \"$i\"\ndone"}]},{"id":"conditionals","title":"Conditionals","blocks":[{"t":"code","lang":"bash","code":"if [ \"$1\" == \"yes\" ]; then\n    echo \"Confirmed\"\nelif [ \"$1\" == \"no\" ]; then\n    echo \"Denied\"\nelse\n    echo \"Unclear\"\nfi"},{"t":"callout","kind":"tip","html":"<strong><code>[ ]</code> vs <code>[[ ]]</code>:</strong> always prefer <code>[[ ]]</code> in bash — it's safer (no word-splitting/glob surprises on unquoted variables) and supports <code>&amp;&amp;</code>, <code>||</code>, and pattern matching directly inside it."},{"t":"code","lang":"bash","code":"[[ \"$name\" == \"SOLO\" ]]         # string equality\n[[ \"$name\" == S* ]]               # pattern match — only works inside [[ ]]\n[[ -f \"$file\" && -r \"$file\" ]]     # file exists AND is readable"},{"t":"callout","kind":"tip","html":"<strong>Common test operators:</strong> "},{"t":"table","head":["Test","Meaning"],"rows":[["<code>-eq -ne -lt -le -gt -ge</code>","numeric comparisons"],["<code>== !=</code>","string equality/inequality"],["<code>-z \"$s\"</code>","string is empty"],["<code>-n \"$s\"</code>","string is non-empty"],["<code>-f file</code>","file exists and is a regular file"],["<code>-d dir</code>","directory exists"],["<code>-r -w -x file</code>","readable / writable / executable"],["<code>-e path</code>","path exists (any type)"]]},{"t":"text","html":"<h6>`case` statement — cleaner than a long if/elif chain</h6>"},{"t":"code","lang":"bash","code":"case \"$1\" in\n    start)\n        echo \"Starting...\"\n        ;;\n    stop)\n        echo \"Stopping...\"\n        ;;\n    restart|reload)\n        echo \"Restarting...\"\n        ;;\n    *)\n        echo \"Usage: $0 {start|stop|restart}\"\n        exit 1\n        ;;\nesac"}]},{"id":"functions","title":"Functions","blocks":[{"t":"code","lang":"bash","code":"greet() {\n    local name=\"$1\"        # $1 = first argument passed to the function — always 'local' it\n    echo \"Hello, $name\"\n}\n\ngreet \"SOLO\"                # call it like a command\n\n# All positional parameters inside a function:\nshow_args() {\n    echo \"First: $1\"\n    echo \"All: $@\"           # each argument as a separate word\n    echo \"Count: $#\"          # number of arguments passed\n}\nshow_args a b c"},{"t":"callout","kind":"tip","html":"<strong>Return values — the part that trips people up:</strong> bash functions don't \"return\" data the way most languages do. <code>return</code> only sets an <strong>exit code</strong> (0–255). To get actual data out, either <code>echo</code> it and capture with <code>$()</code>, or write into a variable."},{"t":"code","lang":"bash","code":"add() {\n    local result=$(( $1 + $2 ))\n    echo \"$result\"          # \"return\" data by printing it\n}\nsum=$(add 3 4)               # capture it via command substitution\necho \"$sum\"                    # 7\n\nis_even() {\n    (( $1 % 2 == 0 ))          # return TRUE/FALSE as an exit code, not printed text\n}\nif is_even 4; then\n    echo \"even\"\nfi"}]},{"id":"error-handling-the-part-most-scripts-skip","title":"Error Handling — The Part Most Scripts Skip","blocks":[{"t":"text","html":"<p>By default, bash <strong>keeps going after a failed command</strong> — this is the single biggest source of scripts that silently do the wrong thing.</p>"},{"t":"text","html":"<h6>The essential header for almost every script you write</h6>"},{"t":"code","lang":"bash","code":"set -euo pipefail"},{"t":"table","head":["Flag","Effect"],"rows":[["<code>set -e</code>","Exit immediately if any command fails (non-zero exit code)"],["<code>set -u</code>","Exit if you reference an unset variable (catches typos like <code>$FIL</code> instead of <code>$FILE</code>)"],["<code>set -o pipefail</code>","A pipeline (`a \\","b \\","c`) fails if <strong>any</strong> command in it fails, not just the last one"]]},{"t":"callout","kind":"tip","html":"<strong>Why <code>pipefail</code> matters specifically:</strong> without it, <code>bad_command | grep something</code> only checks <code>grep</code>'s exit code — if <code>bad_command</code> itself failed, the pipeline still reports success as long as <code>grep</code> didn't error. This hides real failures constantly."},{"t":"code","lang":"bash","code":"false | echo \"done\"          # WITHOUT pipefail: exit code 0 — looks successful!\nset -o pipefail\nfalse | echo \"done\"          # WITH pipefail: exit code reflects false's failure"},{"t":"text","html":"<h6>`set -e` gotchas — it doesn't catch everything</h6>"},{"t":"code","lang":"bash","code":"set -e\nif some_command; then     # commands inside an if CONDITION don't trigger set -e — this is intentional\n    echo \"ok\"\nfi\n\nsome_command || true        # explicitly suppresses set -e for that one line\nsome_command && echo \"ok\"    # also won't trigger set -e on failure of some_command"},{"t":"text","html":"<h6>Debug/trace mode</h6>"},{"t":"code","lang":"bash","code":"set -x     # print every command before running it — invaluable when a script does something unexpected\nset +x     # turn it back off"},{"t":"text","html":"<p>Run a whole script in trace mode without editing it:</p>"},{"t":"code","lang":"bash","code":"bash -x script.sh"},{"t":"text","html":"<h6>`trap` — running cleanup code no matter how the script exits</h6>"},{"t":"text","html":"<p><code>trap</code> catches signals or the script's own exit and runs a function — essential for cleaning up temp files, releasing locks, or logging what happened, even when the script crashes or gets killed.</p>"},{"t":"code","lang":"bash","code":"cleanup() {\n    echo \"Cleaning up...\"\n    rm -f \"$TMPFILE\"\n}\ntrap cleanup EXIT          # runs on ANY exit — success, error, or Ctrl+C\n\ntrap 'echo \"Interrupted!\"; exit 1' INT     # specifically catch Ctrl+C (SIGINT)\ntrap 'echo \"Error on line $LINENO\"' ERR      # runs whenever a command fails (with set -e active)"},{"t":"callout","kind":"tip","html":"<strong>Practical temp-file pattern:</strong> "},{"t":"code","lang":"bash","code":"TMPFILE=$(mktemp)\ntrap 'rm -f \"$TMPFILE\"' EXIT     # guarantees cleanup even if the script dies halfway through\necho \"some data\" > \"$TMPFILE\""},{"t":"text","html":"<h6>Checking exit codes explicitly</h6>"},{"t":"code","lang":"bash","code":"some_command\nif [ $? -ne 0 ]; then          # $? = exit code of the LAST command run\n    echo \"some_command failed\" >&2\n    exit 1\nfi\n\n# Cleaner, more idiomatic version of the same thing:\nif ! some_command; then\n    echo \"some_command failed\" >&2\n    exit 1\nfi"}]},{"id":"writing-scripts-that-don-t-silently-fail","title":"Writing Scripts That Don't Silently Fail","blocks":[{"t":"text","html":"<p>A checklist, not just theory:</p>"},{"t":"text","html":"<p>``<code>bash if [ $# -lt 1 ]; then echo \"Usage: $0 &lt;filename&gt;\" &gt;&amp;2 exit 1 fi FILE=\"$1\" if [ ! -f \"$FILE\" ]; then echo \"Error: $FILE does not exist\" &gt;&amp;2 exit 1 fi </code>``</p>"},{"t":"text","html":"<p>``<code>bash log() { echo \"[$(date '+%Y-%m-%d %H:%M:%S')] $*\"; } log \"Starting backup...\" </code>``</p>"},{"t":"text","html":"<p>``<code>bash sudo apt install shellcheck -y shellcheck script.sh </code>``</p>"},{"t":"list","items":["<strong>Start every script with <code>set -euo pipefail</code></strong> unless you have a specific reason not to.","<strong>Validate arguments before using them:</strong>","<strong>Send errors to stderr (<code>&gt;&amp;2</code>), not stdout</strong> — keeps error messages separate from real output, so anything piping your script's output doesn't accidentally consume an error message as data.","<strong>Use meaningful, distinct exit codes</strong> — <code>0</code> for success, and different non-zero codes for different failure types, so callers (or you, six months later) can tell what failed without re-reading the script.","<strong>Use <code>trap ... EXIT</code></strong> for any script that creates temp files, acquires locks, or opens connections — cleanup should be automatic, not something you remember to add at the bottom (which never runs if the script dies early anyway).","<strong>Quote every variable expansion</strong> (<code>\"$var\"</code>, <code>\"${array[@]}\"</code>) — the single most common source of scripts that \"work on my machine\" and break on filenames with spaces.","<strong>Never trust <code>$1</code>/<code>$2</code> blindly</strong> — a script called with the wrong number of arguments should fail with a clear usage message, not proceed with an empty/unset variable and do something wrong silently.","<strong>Log with timestamps</strong> for anything long-running or cron-scheduled — when it fails at 3 AM, you want to know when, not just that:","<strong>Run <code>shellcheck</code> on every script before trusting it.</strong> It's a static analyzer that catches quoting bugs, unreachable code, and dozens of other classic bash mistakes before you ever run the script:"]}]},{"id":"string-manipulation","title":"String Manipulation","blocks":[{"t":"code","lang":"bash","code":"str=\"Hello, World\"\n\necho \"${#str}\"              # 12 — length\necho \"${str:7}\"               # World — substring from index 7\necho \"${str:7:3}\"              # Wor — substring, 3 chars starting at index 7\necho \"${str/World/Bash}\"        # Hello, Bash — replace first match\necho \"${str//o/0}\"               # Hell0, W0rld — replace ALL matches\necho \"${str^^}\"                   # HELLO, WORLD — uppercase\necho \"${str,,}\"                    # hello, world — lowercase"}]},{"id":"input-output","title":"Input & Output","blocks":[{"t":"code","lang":"bash","code":"read -p \"Enter your name: \" name     # prompt + capture input\necho \"Hi, $name\"\n\nresult=$(ls -la)                       # command substitution — capture command output into a variable\n\ncat <<EOF                               # here-doc — multi-line text block\nThis is line 1\nThis is line 2, with a variable: $name\nEOF"}]},{"id":"a-hardened-script-template","title":"A Hardened Script Template","blocks":[{"t":"text","html":"<p>Putting it all together — this is a reasonable default skeleton for any real script:</p>"},{"t":"code","lang":"bash","code":"#!/usr/bin/env bash\nset -euo pipefail\n\nlog() { echo \"[$(date '+%Y-%m-%d %H:%M:%S')] $*\"; }\nerror() { echo \"[$(date '+%Y-%m-%d %H:%M:%S')] ERROR: $*\" >&2; }\n\ncleanup() {\n    log \"Cleaning up...\"\n    [ -n \"${TMPFILE:-}\" ] && rm -f \"$TMPFILE\"\n}\ntrap cleanup EXIT\ntrap 'error \"Failed on line $LINENO\"' ERR\n\nusage() {\n    echo \"Usage: $0 <input_file>\" >&2\n    exit 1\n}\n\n# --- Validate input ---\n[ $# -lt 1 ] && usage\nINPUT_FILE=\"$1\"\n[ ! -f \"$INPUT_FILE\" ] && { error \"$INPUT_FILE not found\"; exit 1; }\n\n# --- Main logic ---\nTMPFILE=$(mktemp)\nlog \"Processing $INPUT_FILE...\"\ngrep \"pattern\" \"$INPUT_FILE\" > \"$TMPFILE\"\nlog \"Found $(wc -l < \"$TMPFILE\") matches\"\n\nlog \"Done.\""},{"t":"text","html":"<p>This template: fails fast on any error, catches unset variables, catches pipeline failures, logs with timestamps, cleans up its temp file no matter how it exits, and validates its input before touching it — the combination that turns \"script that mostly works\" into \"script you can actually trust in a cron job.\"</p>"}]}]},{"id":"disk-storage","title":"Disk & Storage Management — Partitions, LVM, Mounting & fstab","icon":"database","category":"storage","preview":"","source":"disk-storage-management.md","words":1970,"parts":[{"id":"introduction","title":"Introduction","blocks":[{"t":"text","html":"<p>How storage actually fits together on Linux: disk → partition → filesystem → mount point — and the file that ties it all together at boot.</p>"}]},{"id":"the-storage-hierarchy","title":"The Storage Hierarchy","blocks":[{"t":"code","lang":"bash","code":"Physical disk (/dev/sda)\n   └─ Partition (/dev/sda1)\n        └─ Filesystem (ext4, xfs, etc. — formatted onto the partition)\n             └─ Mount point (/, /home, /mnt/data — where it becomes accessible in the tree)"},{"t":"text","html":"<p>A raw disk is useless until it's partitioned; a partition is useless until it has a filesystem; a filesystem is inaccessible until it's mounted somewhere in the directory tree. Every storage task on Linux is really just moving down (or up) this chain.</p>"}]},{"id":"viewing-disks-partitions","title":"Viewing Disks & Partitions","blocks":[{"t":"code","lang":"bash","code":"lsblk                     # tree view of all block devices and their partitions — start here, always\nlsblk -f                   # same, plus filesystem type and UUID\nsudo fdisk -l               # detailed partition table info, needs root\nsudo parted -l               # same idea, better for GPT disks\nblkid                         # list filesystem UUIDs and types for every device\ndf -h                          # disk usage of currently MOUNTED filesystems\ndu -sh /path/to/dir              # disk usage of a specific directory (sums recursively)"},{"t":"callout","kind":"tip","html":"<strong>Reading <code>lsblk</code> output:</strong> "},{"t":"code","lang":"bash","code":"NAME   SIZE  TYPE  MOUNTPOINT\nsda     500G  disk\n├─sda1   512M part  /boot/efi\n├─sda2    50G  part  /\n└─sda3  449.5G part  /home"},{"t":"text","html":"<p><code>disk</code> = the whole physical device; <code>part</code> = a partition on it. The indentation shows the parent-child relationship.</p>"}]},{"id":"partitioning","title":"Partitioning","blocks":[{"t":"text","html":"<h6>MBR vs GPT — know which you're working with</h6>"},{"t":"table","head":["","MBR (older)","GPT (modern)"],"rows":[["Max partitions","4 primary (or 3 + extended)","128"],["Max disk size","2TB","Effectively unlimited"],["Boot mode","BIOS legacy","UEFI (also supports legacy)"],["Use today","Only for compatibility with very old systems","Default choice for anything new"]]},{"t":"text","html":"<h6>Partitioning with `fdisk` (MBR-friendly, works on GPT too)</h6>"},{"t":"callout","kind":"tip","html":"<strong>Step 1 — Enter fdisk on the target disk (never a mounted/in-use one):</strong> "},{"t":"code","lang":"bash","code":"sudo fdisk /dev/sdb"},{"t":"callout","kind":"tip","html":"<strong>Step 2 — Inside the fdisk prompt, key commands:</strong> "},{"t":"code","lang":"bash","code":"n     → create a new partition\np     → print the current partition table\nd     → delete a partition\nt     → change a partition's type\nw     → write changes to disk and exit (nothing is applied until this)\nq     → quit WITHOUT saving — your escape hatch if you're unsure"},{"t":"callout","kind":"tip","html":"<strong>Step 3 — Creating a partition, walked through:</strong> "},{"t":"code","lang":"bash","code":"Command: n\nPartition type: p (primary) or e (extended)\nPartition number: (accept default, e.g. 1)\nFirst sector: (accept default — start right after the previous partition)\nLast sector: +50G   (or accept default to use all remaining space)\nCommand: w    → commits it"},{"t":"text","html":"<h6>Partitioning with `parted` (better for GPT, scriptable)</h6>"},{"t":"code","lang":"bash","code":"sudo parted /dev/sdb\n(parted) mklabel gpt              # initialize a GPT partition table — WARNING: wipes existing partition table\n(parted) mkpart primary ext4 0% 50%    # create a partition spanning the first half of the disk\n(parted) print                       # verify\n(parted) quit"},{"t":"callout","kind":"tip","html":"<strong>After creating any partition, the kernel needs to notice it:</strong> "},{"t":"code","lang":"bash","code":"sudo partprobe /dev/sdb     # re-reads the partition table without a reboot"}]},{"id":"creating-a-filesystem","title":"Creating a Filesystem","blocks":[{"t":"text","html":"<p>A fresh partition is just empty space until it's formatted:</p>"},{"t":"code","lang":"bash","code":"sudo mkfs.ext4 /dev/sdb1       # format as ext4 — the common general-purpose default\nsudo mkfs.xfs /dev/sdb1         # xfs — strong for large files, used a lot in server/DB contexts\nsudo mkfs.vfat -F 32 /dev/sdb1   # FAT32 — for cross-compatibility with Windows/embedded devices"},{"t":"table","head":["Filesystem","Good for"],"rows":[["<code>ext4</code>","General-purpose default on most Linux distros — mature, reliable"],["<code>xfs</code>","Large files, high-throughput workloads (common on RHEL-family servers)"],["<code>btrfs</code>","Snapshots, built-in RAID-like features, copy-on-write"],["<code>vfat</code>/<code>exfat</code>","Cross-OS compatibility (USB drives you'll also plug into Windows)"]]},{"t":"text","html":"<p><strong>This step is destructive</strong> — formatting erases whatever was previously on that partition. Always confirm the device name with <code>lsblk</code> immediately before running <code>mkfs.*</code>.</p>"}]},{"id":"mounting-temporary-manual","title":"Mounting — Temporary (Manual)","blocks":[{"t":"code","lang":"bash","code":"sudo mkdir -p /mnt/data          # the mount point must already exist as a directory\nsudo mount /dev/sdb1 /mnt/data     # attach the filesystem there\nmount | grep sdb1                    # confirm it's mounted, and see the options it mounted with\nsudo umount /mnt/data                 # detach it — always do this before physically removing the device"},{"t":"callout","kind":"tip","html":"<strong>If <code>umount</code> refuses (\"target is busy\"):</strong> "},{"t":"code","lang":"bash","code":"sudo lsof /mnt/data     # find which process still has a file open there\nsudo fuser -m /mnt/data   # alternative way to find the culprit process"},{"t":"text","html":"<p>Never force-unmount a device that's actively being written to — see the file-corruption guide for why.</p>"},{"t":"text","html":"<p><strong>Important: manual mounts like this vanish on reboot.</strong> For anything that needs to persist, it belongs in <code>/etc/fstab</code> — which is the rest of this guide.</p>"}]},{"id":"lvm-logical-volume-management","title":"LVM — Logical Volume Management","blocks":[{"t":"text","html":"<p>LVM adds a flexible layer between raw partitions and filesystems, letting you resize, combine, and snapshot storage without being locked into a partition's original fixed size.</p>"},{"t":"text","html":"<h6>Core concepts</h6>"},{"t":"code","lang":"bash","code":"Physical Volume (PV)  →  a raw disk or partition, initialized for LVM use\nVolume Group (VG)       →  a pool combining one or more PVs into one big space\nLogical Volume (LV)      →  a resizable \"virtual partition\" carved out of a VG"},{"t":"text","html":"<p>Think of the VG as a shared pool of storage, and LVs as flexible allocations from that pool — you can grow an LV later by just giving it more of the pool, without the rigid \"adjacent free space\" constraint raw partitions have.</p>"},{"t":"text","html":"<h6>Step-by-step LVM setup</h6>"},{"t":"callout","kind":"tip","html":"<strong>Step 1 — Turn a raw partition/disk into a Physical Volume:</strong> "},{"t":"code","lang":"bash","code":"sudo pvcreate /dev/sdb1\nsudo pvdisplay        # verify"},{"t":"callout","kind":"tip","html":"<strong>Step 2 — Create a Volume Group from one or more PVs:</strong> "},{"t":"code","lang":"bash","code":"sudo vgcreate data_vg /dev/sdb1\nsudo vgdisplay          # verify — shows total/free space in the group"},{"t":"callout","kind":"tip","html":"<strong>Step 3 — Carve out a Logical Volume from the group:</strong> "},{"t":"code","lang":"bash","code":"sudo lvcreate -L 20G -n data_lv data_vg     # 20GB LV named \"data_lv\" inside \"data_vg\"\nsudo lvdisplay                                  # verify"},{"t":"callout","kind":"tip","html":"<strong>Step 4 — Format and mount it like any normal partition:</strong> "},{"t":"code","lang":"bash","code":"sudo mkfs.ext4 /dev/data_vg/data_lv\nsudo mkdir -p /mnt/data\nsudo mount /dev/data_vg/data_lv /mnt/data"},{"t":"text","html":"<h6>Resizing — the actual payoff of using LVM</h6>"},{"t":"code","lang":"bash","code":"sudo lvextend -L +10G /dev/data_vg/data_lv     # grow the LV by 10GB (needs free space in the VG)\nsudo resize2fs /dev/data_vg/data_lv               # grow the ext4 filesystem to fill the new LV size\n# for xfs, the equivalent is:\nsudo xfs_growfs /mnt/data"},{"t":"callout","kind":"tip","html":"<strong>Note:</strong> shrinking is riskier and filesystem-dependent (ext4 supports it offline; xfs does not support shrinking at all) — always back up before attempting a shrink."},{"t":"text","html":"<h6>Snapshots — point-in-time copies for safe experimentation/backups</h6>"},{"t":"code","lang":"bash","code":"sudo lvcreate -L 5G -s -n data_snap /dev/data_vg/data_lv     # create a snapshot\n# ... do risky work on the original LV, or back up the snapshot ...\nsudo lvremove /dev/data_vg/data_snap                            # remove the snapshot when done"}]},{"id":"etc-fstab-the-real-deep-dive","title":"`/etc/fstab` — The Real Deep Dive","blocks":[{"t":"text","html":"<p>This is the file that tells the system what to mount automatically at every boot. Get it wrong and the machine can fail to boot entirely — so understanding every field matters.</p>"},{"t":"text","html":"<h6>Anatomy of a line</h6>"},{"t":"code","lang":"bash","code":"UUID=1234-5678  /mnt/data  ext4  defaults  0  2\n   │                │         │       │      │  │\n   │                │         │       │      │  └─ fsck order (pass)\n   │                │         │       │      └──── dump flag\n   │                │         │       └─────────── mount options\n   │                │         └─────────────────── filesystem type\n   │                └───────────────────────────── mount point\n   └────────────────────────────────────────────── device identifier"},{"t":"text","html":"<p>Six fields, always space/tab-separated, always in this order.</p>"},{"t":"text","html":"<h6>Field 1: Device identifier — and why UUID beats `/dev/sdX`</h6>"},{"t":"code","lang":"bash","code":"/dev/sdb1                                      # device path — WORKS but is unstable\nUUID=1234-5678-ABCD                             # stable identifier tied to the filesystem itself\nLABEL=mydata                                     # a human-assigned label, if you set one"},{"t":"callout","kind":"tip","html":"<strong>Why this matters:</strong> <code>/dev/sdb1</code> is assigned by detection order at boot — plug in a USB drive, add a new disk, or have a drive fail, and the same physical disk you meant might now be <code>/dev/sdc1</code> instead. <code>/etc/fstab</code> entries using raw device paths can silently mount the <strong>wrong disk</strong> at the <strong>right mount point</strong> after such a change. UUIDs are generated when the filesystem is created and never change, regardless of detection order."},{"t":"callout","kind":"tip","html":"<strong>Find your UUIDs:</strong> "},{"t":"code","lang":"bash","code":"sudo blkid\n# or\nlsblk -f"},{"t":"text","html":"<h6>Field 2: Mount point</h6>"},{"t":"text","html":"<p>The directory this filesystem attaches to — must already exist (<code>mkdir -p</code> it first if it doesn't).</p>"},{"t":"text","html":"<h6>Field 3: Filesystem type</h6>"},{"t":"text","html":"<p><code>ext4</code>, <code>xfs</code>, <code>vfat</code>, <code>ntfs</code>, <code>swap</code>, or <code>auto</code> (let the kernel detect it — fine for removable media, not recommended for critical system mounts).</p>"},{"t":"text","html":"<h6>Field 4: Mount options — the field most people leave at `defaults` and never learn</h6>"},{"t":"table","head":["Option","Effect"],"rows":[["<code>defaults</code>","Shorthand for: <code>rw, suid, dev, exec, auto, nouser, async</code>"],["<code>ro</code> / <code>rw</code>","Read-only / read-write"],["<code>noauto</code>","Don't mount automatically at boot — only mounts when you explicitly run <code>mount /mountpoint</code>"],["<code>nofail</code>","<strong>Critical for external/removable drives</strong> — if the device isn't present at boot, skip it instead of hanging or dropping into emergency mode"],["<code>user</code>","Allow non-root users to mount it"],["<code>nouser</code>","Only root can mount it"],["<code>exec</code> / <code>noexec</code>","Allow / block executing binaries from this filesystem"],["<code>suid</code> / <code>nosuid</code>","Honor / ignore setuid bits on this filesystem — <code>nosuid</code> is a real security hardening step for untrusted removable media"],["<code>async</code> / <code>sync</code>","Buffered (faster) vs immediate (safer, slower) writes"]]},{"t":"callout","kind":"tip","html":"<strong>A very common real mistake:</strong> adding a second internal or external drive to <code>/etc/fstab</code> without <code>nofail</code>. If that drive is ever disconnected, missing, or fails, the <strong>entire boot process hangs</strong> waiting for it — turning a \"drive I use sometimes\" into \"reason the whole server won't come up.\" Always pair external/optional drives with <code>nofail</code> (and usually <code>noauto</code> too, if you don't need it mounted every single boot)."},{"t":"code","lang":"bash","code":"UUID=1234-5678  /mnt/backup-drive  ext4  defaults,nofail  0  2"},{"t":"text","html":"<h6>Field 5: Dump flag</h6>"},{"t":"text","html":"<p>Legacy — controls whether the ancient <code>dump</code> backup utility includes this filesystem. Almost nobody uses <code>dump</code> anymore. Convention: <code>1</code> for the root filesystem, <code>0</code> for everything else. Safe to always set <code>0</code> on modern systems.</p>"},{"t":"text","html":"<h6>Field 6: fsck pass order</h6>"},{"t":"text","html":"<p>Controls filesystem-check order and whether it happens at all:</p>"},{"t":"list","items":["<code>0</code> — never fsck this filesystem (correct for swap, removable media, network mounts)","<code>1</code> — check first (reserved for the <strong>root filesystem only</strong>)","<code>2</code> — check after root, for everything else that should be checked"]},{"t":"text","html":"<h6>Testing fstab changes safely — never just reboot and hope</h6>"},{"t":"callout","kind":"tip","html":"<strong>Step 1 — Edit the file:</strong> "},{"t":"code","lang":"bash","code":"sudo nano /etc/fstab     # or vim"},{"t":"callout","kind":"tip","html":"<strong>Step 2 — Test it WITHOUT rebooting:</strong> "},{"t":"code","lang":"bash","code":"sudo mount -a     # attempts to mount everything in fstab that isn't already mounted"},{"t":"text","html":"<p>If there's a syntax error or a bad UUID, <code>mount -a</code> reports it immediately — on a live system, where you can still fix it. A reboot with a broken fstab, by contrast, can drop you into <strong>emergency mode</strong>, a minimal recovery shell, at boot.</p>"},{"t":"callout","kind":"tip","html":"<strong>Step 3 — Verify what actually got mounted:</strong> "},{"t":"code","lang":"bash","code":"df -h\nmount | grep /mnt/data"},{"t":"text","html":"<h6>Recovering from a broken fstab that already caused a boot failure</h6>"},{"t":"text","html":"<p>If you do end up in emergency mode after a bad edit:</p>"},{"t":"code","lang":"bash","code":"# emergency mode typically drops you to a root shell automatically\nmount -o remount,rw /               # root may be mounted read-only in this mode — fix that first\nnano /etc/fstab                       # fix or comment out the bad line with a leading #\nreboot"},{"t":"text","html":"<p>If it won't even reach emergency mode, boot from a live USB, mount the disk manually, and edit <code>/etc/fstab</code> from there.</p>"}]},{"id":"swap-in-fstab","title":"Swap in fstab","blocks":[{"t":"callout","kind":"tip","html":"<strong>Swap partition:</strong> "},{"t":"code","lang":"bash","code":"UUID=abcd-1234  none  swap  sw  0  0"},{"t":"callout","kind":"tip","html":"<strong>Swap file (common on cloud/VPS instances without a dedicated swap partition):</strong> "},{"t":"code","lang":"bash","code":"sudo fallocate -l 2G /swapfile\nsudo chmod 600 /swapfile\nsudo mkswap /swapfile\nsudo swapon /swapfile"},{"t":"text","html":"<p>Then in fstab:</p>"},{"t":"code","lang":"bash","code":"/swapfile  none  swap  sw  0  0"}]},{"id":"checking-repairing-filesystems","title":"Checking & Repairing Filesystems","blocks":[{"t":"code","lang":"bash","code":"sudo fsck /dev/sdb1        # NEVER run on a mounted filesystem — unmount first\nsudo fsck -f /dev/sdb1      # force a check even if the filesystem looks clean"},{"t":"text","html":"<p><code>fsck</code> on the root filesystem specifically requires booting into single-user/rescue mode, since root can't be unmounted while the system is running from it.</p>"}]},{"id":"ongoing-disk-usage-monitoring","title":"Ongoing Disk Usage Monitoring","blocks":[{"t":"code","lang":"bash","code":"df -h                     # free/used space per mounted filesystem\ndu -sh /var/log             # total size of a specific directory\ndu -h --max-depth=1 /home    # size of each immediate subdirectory — good for hunting what's eating space\nncdu /                        # interactive, navigable disk usage explorer (install: sudo apt install ncdu)"}]},{"id":"quick-reference-summary","title":"Quick Reference Summary","blocks":[{"t":"code","lang":"bash","code":"VIEW        lsblk   lsblk -f   df -h   blkid\nPARTITION   fdisk /dev/sdX   or   parted /dev/sdX\nFORMAT      mkfs.ext4 /dev/sdX1\nMOUNT (temp) mount /dev/sdX1 /mnt/point\nMOUNT (perm) edit /etc/fstab, then: mount -a to test\nLVM CHAIN   pvcreate → vgcreate → lvcreate → mkfs → mount\nFSTAB SAFETY ALWAYS use UUID, ALWAYS use nofail on optional drives, ALWAYS test with mount -a before reboot"}]}]},{"id":"firewall","title":"Firewall Deep Dive — ufw vs iptables vs nftables","icon":"shield","category":"networking","preview":"","source":"firewall-deep-dive.md","words":1755,"parts":[{"id":"introduction","title":"Introduction","blocks":[{"t":"text","html":"<p>Three tools, one underlying job: deciding what network traffic gets in, out, or forwarded. Here's how they relate, and how to actually write rules beyond <code>ufw allow 22</code>.</p>"}]},{"id":"how-these-three-actually-relate","title":"How These Three Actually Relate","blocks":[{"t":"code","lang":"bash","code":"nftables   →  the modern kernel packet-filtering framework (replaces the old netfilter/iptables backend)\niptables    →  legacy tool — on current systems, often just translates its commands into nftables rules underneath\nufw          →  a friendly frontend that generates iptables (or nftables, depending on distro version) rules for you"},{"t":"text","html":"<p>They're not three unrelated options — <code>ufw</code> is built on top of <code>iptables</code>/<code>nftables</code>, and modern <code>iptables</code> itself is frequently just a compatibility shim over the real nftables engine now running in the kernel. Which one you interact with directly is a tradeoff between simplicity (<code>ufw</code>) and raw control (<code>iptables</code>/<code>nftables</code>).</p>"},{"t":"table","head":["","ufw","iptables","nftables"],"rows":[["Learning curve","Lowest","Moderate","Moderate-high (but cleaner once learned)"],["Underlying engine","iptables or nftables (distro-dependent)","netfilter (legacy syntax)","netfilter (modern syntax)"],["Best for","Quick, common rules on a single host","Fine-grained control, huge existing knowledge base online","New setups, complex rule sets, performance at scale"],["Status","Actively used, wraps the others","Legacy but still everywhere","The actual current standard going forward"]]}]},{"id":"ufw-beyond-just-allow","title":"`ufw` — Beyond Just `allow`","blocks":[{"t":"text","html":"<h6>The basics, quickly</h6>"},{"t":"code","lang":"bash","code":"sudo ufw status verbose        # see current rules and default policies\nsudo ufw default deny incoming   # deny everything inbound by default — the correct starting posture\nsudo ufw default allow outgoing   # allow everything outbound by default (usually fine for a normal host)\nsudo ufw enable                    # turn it on"},{"t":"text","html":"<h6>Real rule-writing</h6>"},{"t":"callout","kind":"tip","html":"<strong>Allow/deny a specific port and protocol:</strong> "},{"t":"code","lang":"bash","code":"sudo ufw allow 22/tcp\nsudo ufw deny 23/tcp             # explicitly block, distinct from just not allowing"},{"t":"callout","kind":"tip","html":"<strong>Allow only from a specific IP or subnet:</strong> "},{"t":"code","lang":"bash","code":"sudo ufw allow from 203.0.113.5 to any port 22\nsudo ufw allow from 192.168.1.0/24 to any port 3306    # a whole subnet, e.g. DB access only from your LAN"},{"t":"callout","kind":"tip","html":"<strong>Restrict to a specific network interface:</strong> "},{"t":"code","lang":"bash","code":"sudo ufw allow in on eth0 to any port 80"},{"t":"callout","kind":"tip","html":"<strong>Port ranges:</strong> "},{"t":"code","lang":"bash","code":"sudo ufw allow 6000:6010/tcp"},{"t":"callout","kind":"tip","html":"<strong>Rate limiting — throttles repeated connection attempts from the same IP (built-in brute-force mitigation):</strong> "},{"t":"code","lang":"bash","code":"sudo ufw limit ssh\nsudo ufw limit 2222/tcp"},{"t":"text","html":"<p>This denies an IP if it attempts more than 6 connections within 30 seconds — genuinely useful on any internet-facing SSH port, and something <code>allow</code> alone doesn't give you.</p>"},{"t":"callout","kind":"tip","html":"<strong>Deny a specific IP outright (e.g. after spotting it in fail2ban/logs):</strong> "},{"t":"code","lang":"bash","code":"sudo ufw deny from 198.51.100.23"},{"t":"callout","kind":"tip","html":"<strong>Numbered rules — needed to delete precisely:</strong> "},{"t":"code","lang":"bash","code":"sudo ufw status numbered\nsudo ufw delete 3          # deletes rule #3 as shown in the numbered list"},{"t":"text","html":"<p><strong>Application profiles</strong> — some packages register a named profile instead of you remembering ports:</p>"},{"t":"code","lang":"bash","code":"sudo ufw app list\nsudo ufw allow 'Nginx Full'      # equivalent to allowing both 80/tcp and 443/tcp"},{"t":"callout","kind":"tip","html":"<strong>Logging:</strong> "},{"t":"code","lang":"bash","code":"sudo ufw logging on\nsudo tail -f /var/log/ufw.log"}]},{"id":"iptables-the-legacy-standard-in-real-depth","title":"`iptables` — The Legacy Standard, In Real Depth","blocks":[{"t":"text","html":"<h6>Core concepts</h6>"},{"t":"text","html":"<p><strong>Tables</strong> — different purposes:</p>"},{"t":"table","head":["Table","Purpose"],"rows":[["<code>filter</code>","the default — basic allow/deny decisions (what most rules use)"],["<code>nat</code>","network address translation — port forwarding, masquerading"],["<code>mangle</code>","packet modification (rare, advanced use)"]]},{"t":"callout","kind":"tip","html":"<strong>Chains within the <code>filter</code> table:</strong> "},{"t":"table","head":["Chain","Applies to"],"rows":[["<code>INPUT</code>","traffic destined FOR this machine"],["<code>OUTPUT</code>","traffic originating FROM this machine"],["<code>FORWARD</code>","traffic passing THROUGH this machine (routing/NAT scenarios)"]]},{"t":"text","html":"<p><strong>Targets</strong> — what to do with a matched packet:</p>"},{"t":"table","head":["Target","Effect"],"rows":[["<code>ACCEPT</code>","let it through"],["<code>DROP</code>","silently discard — sender gets no response at all"],["<code>REJECT</code>","discard, but send back an explicit rejection (e.g. connection refused)"]]},{"t":"text","html":"<h6>Rule syntax anatomy</h6>"},{"t":"code","lang":"bash","code":"iptables -A INPUT -p tcp --dport 22 -j ACCEPT\n#          │      │        │           │\n#          │      │        │           └─ target: what to do\n#          │      │        └───────────── match: destination port 22\n#          │      └────────────────────── match: protocol tcp\n#          └───────────────────────────── append this rule to the INPUT chain"},{"t":"text","html":"<h6>Real rule-writing</h6>"},{"t":"callout","kind":"tip","html":"<strong>Set default policies (do this FIRST, before adding allow rules, or you can lock yourself out):</strong> "},{"t":"code","lang":"bash","code":"sudo iptables -P INPUT DROP\nsudo iptables -P FORWARD DROP\nsudo iptables -P OUTPUT ACCEPT"},{"t":"callout","kind":"tip","html":"<strong>Always allow established/related connections — without this, replies to your own outbound traffic get blocked too:</strong> "},{"t":"code","lang":"bash","code":"sudo iptables -A INPUT -m state --state ESTABLISHED,RELATED -j ACCEPT"},{"t":"callout","kind":"tip","html":"<strong>Allow loopback (localhost) traffic — many services depend on this internally:</strong> "},{"t":"code","lang":"bash","code":"sudo iptables -A INPUT -i lo -j ACCEPT"},{"t":"callout","kind":"tip","html":"<strong>Allow SSH, but only from one IP:</strong> "},{"t":"code","lang":"bash","code":"sudo iptables -A INPUT -p tcp -s 203.0.113.5 --dport 22 -j ACCEPT"},{"t":"callout","kind":"tip","html":"<strong>Allow a port range:</strong> "},{"t":"code","lang":"bash","code":"sudo iptables -A INPUT -p tcp --dport 6000:6010 -j ACCEPT"},{"t":"callout","kind":"tip","html":"<strong>Rate-limit connections (basic brute-force mitigation):</strong> "},{"t":"code","lang":"bash","code":"sudo iptables -A INPUT -p tcp --dport 22 -m conntrack --ctstate NEW -m limit --limit 3/min --limit-burst 3 -j ACCEPT\nsudo iptables -A INPUT -p tcp --dport 22 -j DROP"},{"t":"text","html":"<p>This accepts up to 3 new SSH connection attempts per minute, then silently drops anything beyond that — a manual equivalent of what <code>ufw limit</code> does automatically.</p>"},{"t":"callout","kind":"tip","html":"<strong>Block a specific IP outright:</strong> "},{"t":"code","lang":"bash","code":"sudo iptables -A INPUT -s 198.51.100.23 -j DROP"},{"t":"callout","kind":"tip","html":"<strong>Port forwarding (NAT table) — forward external port 8080 to an internal service on port 3000:</strong> "},{"t":"code","lang":"bash","code":"sudo iptables -t nat -A PREROUTING -p tcp --dport 8080 -j REDIRECT --to-port 3000"},{"t":"callout","kind":"tip","html":"<strong>Logging before dropping — see what's being blocked:</strong> "},{"t":"code","lang":"bash","code":"sudo iptables -A INPUT -p tcp --dport 22 -j LOG --log-prefix \"SSH-DROP: \"\nsudo iptables -A INPUT -p tcp --dport 22 -j DROP"},{"t":"code","lang":"bash","code":"dmesg | grep SSH-DROP     # view the logged attempts"},{"t":"text","html":"<h6>Viewing &amp; deleting rules</h6>"},{"t":"code","lang":"bash","code":"sudo iptables -L -v -n --line-numbers    # list all rules, numbered, with packet counters\nsudo iptables -D INPUT 3                   # delete rule #3 from the INPUT chain\nsudo iptables -F                             # flush (delete) ALL rules — use with caution, this can open everything up"},{"t":"text","html":"<h6>Making rules persistent (they're wiped on reboot otherwise)</h6>"},{"t":"code","lang":"bash","code":"sudo apt install iptables-persistent -y\nsudo netfilter-persistent save"}]},{"id":"nftables-the-modern-replacement","title":"`nftables` — The Modern Replacement","blocks":[{"t":"text","html":"<p>nftables unifies what used to require separate tools (<code>iptables</code>, <code>ip6tables</code>, <code>arptables</code>, <code>ebtables</code>) into one framework with cleaner syntax and better performance for large rule sets.</p>"},{"t":"text","html":"<h6>Core concepts — similar shape, different words</h6>"},{"t":"code","lang":"bash","code":"table    →  a container for chains (you name it and pick a family: ip, ip6, inet, arp, bridge)\nchain     →  a hook point (input, output, forward — you define these yourself, unlike iptables' fixed chains)\nrule       →  the actual match + action"},{"t":"text","html":"<h6>Basic setup</h6>"},{"t":"code","lang":"bash","code":"sudo apt install nftables -y\nsudo systemctl enable nftables --now"},{"t":"text","html":"<h6>Writing rules — interactive vs. file-based</h6>"},{"t":"callout","kind":"tip","html":"<strong>Interactive (temporary, for testing):</strong> "},{"t":"code","lang":"bash","code":"sudo nft add table inet filter\nsudo nft add chain inet filter input { type filter hook input priority 0 \\; policy drop \\; }\nsudo nft add rule inet filter input tcp dport 22 accept\nsudo nft add rule inet filter input ct state established,related accept\nsudo nft add rule inet filter input iif lo accept"},{"t":"callout","kind":"tip","html":"<strong>File-based (the real, persistent way — this is how nftables is meant to be used):</strong> "},{"t":"code","lang":"bash","code":"sudo nano /etc/nftables.conf"},{"t":"code","lang":"bash","code":"#!/usr/sbin/nft -f\n\nflush ruleset\n\ntable inet filter {\n    chain input {\n        type filter hook input priority 0; policy drop;\n\n        ct state established,related accept\n        iif lo accept\n\n        tcp dport 22 accept\n        tcp dport 80 accept\n        tcp dport 443 accept\n\n        # rate-limited SSH, same idea as the iptables example above\n        tcp dport 2222 ct state new limit rate 3/minute accept\n\n        # explicit block of a known-bad IP\n        ip saddr 198.51.100.23 drop\n    }\n\n    chain forward {\n        type filter hook forward priority 0; policy drop;\n    }\n\n    chain output {\n        type filter hook output priority 0; policy accept;\n    }\n}"},{"t":"code","lang":"bash","code":"sudo nft -f /etc/nftables.conf     # load it\nsudo systemctl restart nftables       # or apply via service restart"},{"t":"text","html":"<h6>Sets — nftables' real advantage for larger rule sets</h6>"},{"t":"text","html":"<p>Instead of writing a separate rule per IP or port, group them into a named set:</p>"},{"t":"code","lang":"bash","code":"set allowed_ips {\n    type ipv4_addr\n    elements = { 203.0.113.5, 203.0.113.6, 198.51.100.10 }\n}\n\nchain input {\n    type filter hook input priority 0; policy drop;\n    ip saddr @allowed_ips tcp dport 22 accept\n}"},{"t":"text","html":"<p>This is dramatically more efficient (and readable) than 50 near-identical iptables lines when you're allow-listing many IPs or ports.</p>"},{"t":"text","html":"<h6>Viewing &amp; managing rules</h6>"},{"t":"code","lang":"bash","code":"sudo nft list ruleset              # show everything currently loaded\nsudo nft list table inet filter      # show just one table\nsudo nft flush ruleset                # clear everything — same caution as iptables -F\nsudo nft delete rule inet filter input handle <handle_number>   # delete one specific rule by its handle"},{"t":"text","html":"<p>Get handle numbers with:</p>"},{"t":"code","lang":"bash","code":"sudo nft -a list ruleset     # -a shows the handle for each rule, needed for targeted deletion"}]},{"id":"same-scenario-all-three-tools-direct-comparison","title":"Same Scenario, All Three Tools — Direct Comparison","blocks":[{"t":"text","html":"<p><strong>Goal: allow SSH only from <code>203.0.113.5</code>, rate-limited, deny everything else inbound.</strong></p>"},{"t":"callout","kind":"tip","html":"<strong>ufw:</strong> "},{"t":"code","lang":"bash","code":"sudo ufw default deny incoming\nsudo ufw allow from 203.0.113.5 to any port 22\nsudo ufw limit 22/tcp\nsudo ufw enable"},{"t":"callout","kind":"tip","html":"<strong>iptables:</strong> "},{"t":"code","lang":"bash","code":"sudo iptables -P INPUT DROP\nsudo iptables -A INPUT -i lo -j ACCEPT\nsudo iptables -A INPUT -m state --state ESTABLISHED,RELATED -j ACCEPT\nsudo iptables -A INPUT -p tcp -s 203.0.113.5 --dport 22 -m limit --limit 3/min -j ACCEPT\nsudo iptables -A INPUT -p tcp --dport 22 -j DROP"},{"t":"callout","kind":"tip","html":"<strong>nftables:</strong> "},{"t":"code","lang":"bash","code":"chain input {\n    type filter hook input priority 0; policy drop;\n    iif lo accept\n    ct state established,related accept\n    ip saddr 203.0.113.5 tcp dport 22 limit rate 3/minute accept\n}"},{"t":"text","html":"<p>Same outcome, three different vocabularies — this is the fastest way to see how the concepts map across tools.</p>"}]},{"id":"which-one-should-you-actually-use","title":"Which One Should You Actually Use?","blocks":[{"t":"table","head":["Situation","Use"],"rows":[["Single personal server, common rules (SSH, a web port, maybe a DB port)","<strong>ufw</strong> — fastest to get right, hardest to accidentally lock yourself out"],["You're following an existing guide/Stack Overflow answer, most of which are written for it","<strong>iptables</strong> — still the most commonly documented tool online"],["Setting up a new system today with no legacy constraints, or managing many IPs/ports via sets","<strong>nftables</strong> — the direction the ecosystem is actually moving"],["You need to understand what <code>ufw</code> generated under the hood","<code>sudo iptables -L -v -n</code> (or <code>nft list ruleset</code> on nftables-backed distros) shows you exactly what ufw actually wrote"]]},{"t":"callout","kind":"tip","html":"<strong>Practical note for your setup specifically:</strong> since you're already running <code>ufw</code> from the SSH guide, there's no need to switch tools just to get the deeper rules above — everything in section 1 (rate limiting, per-IP rules, per-interface rules) covers real-world hardening without ever touching raw iptables/nftables syntax. Reach for the lower-level tools when you hit something ufw genuinely can't express (complex NAT, sets of hundreds of IPs, multi-chain custom logic)."}]},{"id":"quick-reference","title":"Quick Reference","blocks":[{"t":"code","lang":"bash","code":"UFW           sudo ufw allow from <ip> to any port <port>\n                sudo ufw limit <port>/tcp\n                sudo ufw status numbered   →   sudo ufw delete <n>\n\nIPTABLES       sudo iptables -A INPUT -p tcp -s <ip> --dport <port> -j ACCEPT\n                sudo iptables -L -v -n --line-numbers\n                sudo iptables -D INPUT <n>\n\nNFTABLES        sudo nft add rule inet filter input tcp dport <port> accept\n                 sudo nft -a list ruleset\n                 sudo nft delete rule inet filter input handle <n>\n\nALWAYS DO FIRST   allow loopback + established/related BEFORE setting a deny-by-default policy,\n                    or you can lock yourself out of your own remote session immediately."}]}]},{"id":"important-files","title":"Important Files Worth Generating on a Linux / Dev System","icon":"file","category":"system","preview":"","source":"important-files-to-generate.md","words":754,"parts":[{"id":"introduction","title":"Introduction","blocks":[{"t":"text","html":"<p>A priority-ranked list of config files that are worth deliberately creating rather than leaving at system defaults — organized by what they control.</p>"},{"t":"callout","kind":"tip","html":"<strong>Priority key:</strong> 🔴 essential · 🟡 strongly recommended · ⚪ situational"}]},{"id":"shell-configuration","title":"Shell Configuration","blocks":[{"t":"table","head":["File","Priority","Purpose"],"rows":[["<code>~/.bashrc</code>","🔴","Aliases, functions, <code>$PATH</code> additions, prompt customization — loaded for every interactive non-login shell"],["<code>~/.bash_profile</code> or <code>~/.profile</code>","🟡","Loaded once at login — usually just sources <code>.bashrc</code> and sets login-only environment vars"],["<code>~/.bash_aliases</code>","⚪","Optional split-out file for aliases, sourced from <code>.bashrc</code> to keep it clean"],["<code>~/.zshrc</code>","⚪","Same role as <code>.bashrc</code>, if you're on zsh instead"]]},{"t":"code","lang":"bash","code":"# ~/.bashrc essentials\nexport PATH=\"$HOME/.local/bin:$PATH\"\nalias ll='ls -la'\nalias gs='git status'\nexport EDITOR=vim"}]},{"id":"editor-configuration","title":"Editor Configuration","blocks":[{"t":"table","head":["File","Priority","Purpose"],"rows":[["<code>~/.vimrc</code>","🔴","Vim defaults — line numbers, indentation, search behavior (full config in your vim-nano guide)"],["<code>~/.nanorc</code>","🟡","Nano defaults — syntax highlighting, tab behavior"]]}]},{"id":"git-configuration","title":"Git Configuration","blocks":[{"t":"table","head":["File","Priority","Purpose"],"rows":[["<code>~/.gitconfig</code>","🔴","Global identity, default editor, aliases — set once per machine"],["<code>.gitignore</code> (per project)","🔴","Prevents build artifacts, secrets, and local config from ever being committed"],["<code>.gitattributes</code> (per project)","🟡","Normalizes line endings across contributors, marks files as binary, controls diff behavior"],["<code>~/.gitignore_global</code>","⚪","OS/editor cruft (<code>.DS_Store</code>, <code>.vscode/</code>) ignored across all your repos, not just one"]]},{"t":"code","lang":"bash","code":"# ~/.gitconfig\n[user]\n    name = SOLO\n    email = your@email.com\n[core]\n    editor = vim\n[init]\n    defaultBranch = main"},{"t":"code","lang":"gitignore","code":"# .gitignore — Flutter project baseline\n.dart_tool/\n.packages\nbuild/\n.env\n*.log"}]},{"id":"ssh-configuration","title":"SSH Configuration","blocks":[{"t":"table","head":["File","Priority","Purpose"],"rows":[["<code>~/.ssh/config</code>","🔴","Per-host shortcuts (<code>ssh myserver</code> instead of a long flag string), key selection, connection reuse"],["<code>~/.ssh/authorized_keys</code>","🔴","On a server — which public keys are allowed to log in as that user"],["<code>~/.ssh/id_ed25519</code> (+ <code>.pub</code>)","🔴","Your actual keypair — generate with <code>ssh-keygen -t ed25519</code>, never share the private half"]]},{"t":"code","lang":"bash","code":"# ~/.ssh/config\nHost myserver\n    HostName 192.168.1.100\n    User solo\n    IdentityFile ~/.ssh/id_ed25519\n    Port 22"}]},{"id":"environment-secrets","title":"Environment & Secrets","blocks":[{"t":"table","head":["File","Priority","Purpose"],"rows":[["<code>.env</code> (per project)","🔴","API keys, DB URLs, local secrets — <strong>must</strong> be in <code>.gitignore**</code>, never committed"],["<code>.env.example</code>","🟡","Committed template showing which variables are needed, with placeholder values"],["<code>~/.netrc</code>","⚪","Auto-login credentials for tools like <code>curl</code>/<code>ftp</code> — keep permissions at <code>600</code>"]]}]},{"id":"system-level-config-root-owned-edit-with-care-se","title":"System-Level Config (root-owned — edit with care, see your failure-scenarios guide)","blocks":[{"t":"table","head":["File","Priority","Purpose"],"rows":[["<code>/etc/hosts</code>","🟡","Manual hostname → IP mappings, useful for local dev domains"],["<code>/etc/fstab</code>","🟡","Defines what gets mounted at boot — get this wrong and the system can fail to boot"],["<code>/etc/hostname</code>","⚪","The machine's hostname"],["<code>/etc/environment</code>","⚪","System-wide environment variables (not shell-specific, applies to all users)"],["<code>/etc/ssh/sshd_config</code>","🟡","Server-side SSH daemon config — disable password auth here once keys work"],["<code>/etc/sudoers</code>","🔴 (edit only via <code>visudo</code>)","Who can run what as root — a syntax error here can lock you out of <code>sudo</code> entirely"]]}]},{"id":"service-automation-files","title":"Service / Automation Files","blocks":[{"t":"table","head":["File","Priority","Purpose"],"rows":[["<code>/etc/systemd/system/myapp.service</code>","🟡","Defines a custom background service — start on boot, auto-restart on crash"],["Crontab (<code>crontab -e</code>)","🟡","Scheduled recurring jobs — not a manually-created file path, edited through the command"],["<code>~/.config/systemd/user/*.service</code>","⚪","User-level (no root needed) systemd services"]]},{"t":"code","lang":"ini","code":"# /etc/systemd/system/myapp.service\n[Unit]\nDescription=My App\nAfter=network.target\n\n[Service]\nExecStart=/usr/bin/python3 /opt/myapp/main.py\nRestart=on-failure\nUser=solo\n\n[Install]\nWantedBy=multi-user.target"}]},{"id":"project-level-dev-files","title":"Project-Level Dev Files","blocks":[{"t":"table","head":["File","Priority","Purpose"],"rows":[["<code>README.md</code>","🔴","What the project is, how to run it — the first thing anyone (including future you) reads"],["<code>.gitignore</code>","🔴","(see above)"],["<code>LICENSE</code>","🟡","Legal terms for reuse — matters the moment a repo goes public"],["<code>CHANGELOG.md</code>","⚪","Human-readable version history, especially valuable once you're shipping releases"],["<code>.editorconfig</code>","🟡","Enforces consistent indentation/line-endings across every editor/IDE a contributor might use"],["<code>Dockerfile</code>","🟡","Reproducible build/run environment for the project"],["<code>docker-compose.yml</code>","🟡","Multi-service local dev stack (app + DB + cache in one command)"],["<code>.dockerignore</code>","🟡","Keeps build context small — mirrors <code>.gitignore</code>'s role but for Docker builds"],["<code>pubspec.yaml</code>","🔴 (Flutter)","Dependencies, assets, and metadata for any Flutter project"],["<code>analysis_options.yaml</code>","🟡 (Flutter/Dart)","Lint rules — catches style/bug issues before they ship"]]}]},{"id":"aiops-automation-specific","title":"AIOps / Automation-Specific","blocks":[{"t":"text","html":"<p>Relevant given your current track:</p>"},{"t":"table","head":["File","Priority","Purpose"],"rows":[["<code>prometheus.yml</code>","🟡","Defines what Prometheus scrapes and how often — the backbone of most monitoring setups"],["Grafana provisioning YAML (<code>dashboards.yml</code>, <code>datasources.yml</code>)","⚪","Version-controls your dashboards instead of clicking them into existence by hand"],["Ansible inventory (<code>inventory.ini</code>) + playbooks (<code>*.yml</code>)","⚪","Declarative server config — the \"generate once, apply everywhere\" pattern AIOps leans on heavily"],["n8n workflow export (<code>workflow.json</code>)","⚪","Lets you version-control and re-import your automation flows instead of them living only in the n8n UI"]]}]},{"id":"quick-priority-summary","title":"Quick Priority Summary","blocks":[{"t":"callout","kind":"tip","html":"<strong>Set these up on day one of any new machine:</strong> <code>.bashrc</code>, <code>.vimrc</code>, <code>.gitconfig</code>, <code>~/.ssh/config</code> + keypair, <code>/etc/sudoers</code> awareness (don't need to edit it, just know it exists)."},{"t":"callout","kind":"tip","html":"<strong>Set these up on day one of any new project:</strong> <code>README.md</code>, <code>.gitignore</code>, <code>.env</code> + <code>.env.example</code>."},{"t":"callout","kind":"tip","html":"<strong>Set these up the moment you deploy something that should survive a reboot or crash:</strong> a systemd unit file, and if it needs monitoring, <code>prometheus.yml</code>."}]}]},{"id":"linux-boot","title":"The Linux Boot Process — BIOS/UEFI → GRUB → systemd","icon":"zap","category":"system","preview":"","source":"linux-boot-process.md","words":1915,"parts":[{"id":"introduction","title":"Introduction","blocks":[{"t":"text","html":"<p>Every stage a machine passes through between \"power button pressed\" and \"login prompt,\" and — the actual point of this guide — how to tell which stage failed when a machine won't boot.</p>"}]},{"id":"the-full-chain-at-a-glance","title":"The Full Chain, At a Glance","blocks":[{"t":"code","lang":"bash","code":"Power on\n   │\n   ▼\n1. BIOS/UEFI Firmware  →  hardware self-test, pick a boot device\n   │\n   ▼\n2. Bootloader (GRUB)     →  find and load a kernel\n   │\n   ▼\n3. Kernel + initramfs      →  kernel initializes hardware, mounts a temporary root\n   │\n   ▼\n4. systemd (PID 1)           →  mounts the real root filesystem, starts all services in dependency order\n   │\n   ▼\n5. Target reached (login screen / shell prompt)"},{"t":"text","html":"<p>Every boot failure lives in exactly one of these stages — the entire diagnostic skill is recognizing which one from what you see on screen.</p>"}]},{"id":"stage-1-bios-uefi-firmware","title":"Stage 1: BIOS / UEFI Firmware","blocks":[{"t":"text","html":"<p>The firmware is code baked into the motherboard, running before any OS exists. It has one job: run hardware checks, then hand control to a bootable device.</p>"},{"t":"text","html":"<h6>BIOS vs UEFI</h6>"},{"t":"table","head":["","Legacy BIOS","UEFI (modern standard)"],"rows":[["Age","Original, decades-old standard","Modern replacement, standard on hardware since ~2012+"],["Disk requirement","MBR partition table","GPT partition table (with an EFI System Partition)"],["Boot process","Reads the first 512 bytes (MBR) of the boot disk directly","Reads an actual <code>.efi</code> executable file from the ESP"],["Secure Boot","Not supported","Supported — cryptographically verifies the bootloader before running it"],["Max disk size for boot drive","2TB","Effectively unlimited"]]},{"t":"text","html":"<h6>What happens in this stage</h6>"},{"t":"list","items":["<strong>POST</strong> (Power-On Self-Test) — checks RAM, CPU, attached devices are present and functional.","Firmware consults its <strong>boot order</strong> — an ordered list of devices to try (disk, USB, network/PXE, etc).","For UEFI: it looks for a bootloader <code>.efi</code> file on the <strong>EFI System Partition (ESP)</strong> — commonly mounted at <code>/boot/efi</code> on a running Linux system — typically <code>/EFI/&lt;distro&gt;/grubx64.efi</code> or similar.","For legacy BIOS: it loads the first 512 bytes (the Master Boot Record) of the selected disk, which contains a tiny bit of bootloader code (GRUB Stage 1)."]},{"t":"text","html":"<h6>Symptoms that mean the failure is HERE</h6>"},{"t":"list","items":["No display output at all, no beep codes, fans spin but nothing happens → hardware/POST failure, not a Linux problem","<code>No bootable device found</code> / <code>Boot device not found</code> → firmware can't find anything to boot at all — wrong boot order, disk not detected, or the ESP/MBR itself is missing or corrupted","Machine goes straight into the firmware setup screen instead of booting → boot order is misconfigured, or it's failing every device in the list and falling through to setup"]},{"t":"text","html":"<h6>What to check</h6>"},{"t":"list","items":["Enter the firmware setup (usually <code>Del</code>, <code>F2</code>, <code>F10</code>, or <code>Esc</code> at power-on, varies by motherboard) and confirm:","The boot drive is actually detected/listed","Boot order has the correct drive first","Secure Boot isn't blocking an unsigned bootloader (a real issue if you've installed a custom kernel or third-party GRUB build)"]}]},{"id":"stage-2-grub-bootloader","title":"Stage 2: GRUB (Bootloader)","blocks":[{"t":"text","html":"<p>GRUB's job: find the actual Linux kernel and initramfs, load them into memory, and hand off control.</p>"},{"t":"text","html":"<h6>GRUB's own stages (relevant mainly for legacy BIOS)</h6>"},{"t":"code","lang":"bash","code":"Stage 1  → tiny code in the MBR, just enough to load Stage 1.5/2\nStage 1.5 → filesystem drivers, lets GRUB read the actual /boot partition\nStage 2   → the full GRUB environment — reads grub.cfg, shows the boot menu"},{"t":"text","html":"<p>On UEFI systems this is simplified — the <code>.efi</code> file loaded directly from the ESP largely is the equivalent of Stage 2.</p>"},{"t":"text","html":"<h6>Key files</h6>"},{"t":"code","lang":"bash","code":"/boot/grub/grub.cfg          # the ACTUAL config GRUB reads at boot — auto-generated, don't hand-edit\n/etc/default/grub               # the file you SHOULD edit — human-readable settings\n/etc/grub.d/                     # scripts that generate grub.cfg's contents"},{"t":"callout","kind":"tip","html":"<strong>Critical rule:</strong> never hand-edit <code>/boot/grub/grub.cfg</code> directly — it's regenerated automatically and your changes will be silently lost. Edit <code>/etc/default/grub</code>, then regenerate:"},{"t":"code","lang":"bash","code":"sudo update-grub                          # Debian/Ubuntu\nsudo grub2-mkconfig -o /boot/grub2/grub.cfg   # RHEL/Fedora"},{"t":"text","html":"<h6>Common settings in `/etc/default/grub`</h6>"},{"t":"code","lang":"bash","code":"GRUB_DEFAULT=0                    # which menu entry boots by default (0 = first)\nGRUB_TIMEOUT=5                      # seconds the menu is shown before auto-booting\nGRUB_CMDLINE_LINUX_DEFAULT=\"quiet splash\"    # kernel boot parameters"},{"t":"text","html":"<h6>Interacting with GRUB live at boot</h6>"},{"t":"list","items":["Hold <code>Shift</code> (BIOS) or repeatedly tap <code>Esc</code> (UEFI) during boot to force the GRUB menu to appear if it's hidden/too fast to catch.","At the GRUB menu, press <code>e</code> to <strong>edit</strong> a boot entry's parameters for this boot only (doesn't persist) — useful for adding <code>single</code> or removing <code>quiet splash</code> to see what's actually happening.","Press <code>c</code> to drop into the <strong>GRUB command line</strong> — a minimal shell for manually specifying a kernel to boot when the configured entries are broken."]},{"t":"text","html":"<h6>Symptoms that mean the failure is HERE</h6>"},{"t":"list","items":["<code>error: no such partition</code> / <code>error: file not found</code> at a GRUB prompt → grub.cfg is pointing at a partition/UUID that's changed or doesn't exist (very common after resizing partitions, or a UUID mismatch — same root cause as the fstab issues from your storage guide)","Dropped into a bare <code>grub rescue&gt;</code> prompt → GRUB's own core files can't be found — the ESP/boot partition itself may be damaged or GRUB's install is broken","GRUB menu shows, but every entry fails the same way → likely a kernel/initramfs problem (next stage), not GRUB itself"]},{"t":"text","html":"<h6>Manually booting from a `grub rescue&gt;` prompt (get in, then fix it properly)</h6>"},{"t":"code","lang":"bash","code":"grub rescue> ls                       # list available drives/partitions\ngrub rescue> ls (hd0,gpt2)/            # inspect a partition's contents to find the right one\ngrub rescue> set root=(hd0,gpt2)\ngrub rescue> set prefix=(hd0,gpt2)/boot/grub\ngrub rescue> insmod normal\ngrub rescue> normal                    # attempts to load the full GRUB environment from here"}]},{"id":"stage-3-kernel-initramfs","title":"Stage 3: Kernel & initramfs","blocks":[{"t":"text","html":"<p>Once GRUB hands off, the actual Linux kernel loads into memory and starts running.</p>"},{"t":"text","html":"<h6>What initramfs is for</h6>"},{"t":"text","html":"<p>The kernel alone often can't mount the real root filesystem yet — it might need drivers for RAID, LVM, encrypted disks, or unusual storage controllers, which aren't compiled directly into the kernel. <strong>initramfs</strong> (initial RAM filesystem) is a small temporary root filesystem, loaded into memory alongside the kernel, that has just enough tools/drivers to find and mount the real root filesystem — after which the kernel switches over (<code>pivot_root</code>) and initramfs's job is done.</p>"},{"t":"code","lang":"bash","code":"/boot/vmlinuz-<version>     # the kernel image itself\n/boot/initrd.img-<version>    # the initramfs"},{"t":"text","html":"<p><strong>Regenerating initramfs</strong> (needed after certain driver/LVM/encryption config changes):</p>"},{"t":"code","lang":"bash","code":"sudo update-initramfs -u                      # Debian/Ubuntu\nsudo dracut --force                              # RHEL/Fedora"},{"t":"text","html":"<h6>Symptoms that mean the failure is HERE</h6>"},{"t":"list","items":["<strong>Kernel panic</strong> — the screen fills with a wall of technical output ending in <code>Kernel panic - not syncing: ...</code> → often a missing/corrupt initramfs, an incompatible kernel module, or (on real hardware) a driver issue for the boot storage controller","<code>Gave up waiting for root device</code> → initramfs can't find/mount the real root filesystem — frequently a UUID mismatch in the kernel command line or initramfs not having the right storage driver","Boot hangs indefinitely with no error, just a blinking cursor after the kernel starts loading → often a graphics driver issue; try removing <code>quiet splash</code> from the GRUB kernel parameters (press <code>e</code> at the GRUB menu) to see actual boot messages instead of a blank splash screen"]},{"t":"text","html":"<h6>What to check</h6>"},{"t":"code","lang":"bash","code":"# once booted (or from a live USB, chrooted into the broken system):\nls -la /boot/                      # confirm vmlinuz and initrd.img actually exist and aren't zero-byte\ncat /etc/default/grub | grep CMDLINE   # check kernel parameters for anything obviously wrong"}]},{"id":"stage-4-systemd-pid-1","title":"Stage 4: systemd (PID 1)","blocks":[{"t":"text","html":"<p>Once the real root filesystem is mounted, the kernel starts the very first userspace process — on virtually every modern distro, that's <code>systemd</code>, always PID 1. From here, systemd's job is to bring the system up to a target state by starting units (services, mounts, sockets, etc.) in dependency order.</p>"},{"t":"text","html":"<h6>Targets — the systemd replacement for old-style \"runlevels\"</h6>"},{"t":"table","head":["Target","Roughly equivalent to","Purpose"],"rows":[["<code>poweroff.target</code>","runlevel 0","shutdown"],["<code>rescue.target</code>","runlevel 1","single-user mode — minimal, root shell, most services not started"],["<code>multi-user.target</code>","runlevel 3","full multi-user system, no GUI"],["<code>graphical.target</code>","runlevel 5","multi-user + display manager/GUI"],["<code>emergency.target</code>","(no old equivalent)","absolute minimum — even less than rescue, drops you to a root shell with almost nothing mounted, used when something as fundamental as fstab is broken"]]},{"t":"code","lang":"bash","code":"systemctl get-default            # what target boots by default\nsudo systemctl set-default multi-user.target    # e.g. disable booting to a GUI"},{"t":"text","html":"<h6>Symptoms that mean the failure is HERE</h6>"},{"t":"list","items":["Machine boots, kernel loads fine, but <strong>drops into emergency mode</strong> with a message like <code>You are in emergency mode</code> → almost always a bad <code>/etc/fstab</code> entry (see your fstab deep-dive guide) or a critical mount failing","Boots to a login prompt eventually, but takes a very long time → a specific unit is hanging waiting on a dependency (commonly network-related units waiting for a network that never comes up, especially on machines with unreliable NICs or missing <code>nofail</code>/<code>noauto</code> on fstab entries)","One specific service fails repeatedly but the rest of the system is fine → that's a service-level problem, not a boot-chain problem — see your process/journalctl guide for that investigation"]},{"t":"text","html":"<h6>Diagnosing systemd-stage boot problems</h6>"},{"t":"code","lang":"bash","code":"systemd-analyze                     # total boot time breakdown, by stage (firmware/loader/kernel/userspace)\nsystemd-analyze blame                 # every unit, sorted by how long it took to start — find the slow one fast\nsystemd-analyze critical-chain         # shows the actual dependency chain that determined total boot time\njournalctl -b                          # full log of the current boot\njournalctl -b -1                        # full log of the PREVIOUS boot — essential after an unexpected reboot/crash"},{"t":"text","html":"<h6>Recovering from emergency/rescue mode</h6>"},{"t":"code","lang":"bash","code":"# you're typically dropped into a root shell automatically here\nmount -o remount,rw /              # root is often mounted read-only in this mode — fix that first\nnano /etc/fstab                      # find and fix (or comment out with #) the offending line\nsystemctl daemon-reload               # if you changed a unit file instead\nreboot"}]},{"id":"full-diagnostic-flowchart","title":"Full Diagnostic Flowchart","blocks":[{"t":"code","lang":"bash","code":"No display, no beeps at all\n   → hardware/PSU/RAM issue, not a boot-chain problem — check physical hardware first\n\nFirmware setup screen, or \"No bootable device\"\n   → Stage 1 (BIOS/UEFI) — check boot order, disk detection, Secure Boot setting\n\n\"grub rescue>\" prompt, or \"error: no such partition\"\n   → Stage 2 (GRUB) — grub.cfg pointing at a wrong/missing partition, reinstall GRUB (below)\n\nKernel panic wall of text\n   → Stage 3 (kernel/initramfs) — corrupt initramfs, bad kernel param, missing driver\n\nBoots into \"emergency mode\"\n   → Stage 4 (systemd) — almost always fstab; check /etc/fstab first, always\n\nBoots but a specific service is broken/slow\n   → not a boot-chain issue at all — this is a service-level investigation\n     (journalctl -u <service>, systemd-analyze blame)"}]},{"id":"reinstalling-grub-when-it-s-genuinely-broken","title":"Reinstalling GRUB (When It's Genuinely Broken)","blocks":[{"t":"text","html":"<p>If GRUB itself is damaged (common after a Windows reinstall overwrites the MBR/ESP, or a failed update), you need to boot from a live USB and repair it from there.</p>"},{"t":"text","html":"<p><strong>Step 1 — Boot a live USB (Ubuntu/Debian live environment works fine for this even on other distros' broken installs).</strong></p>"},{"t":"callout","kind":"tip","html":"<strong>Step 2 — Identify and mount your actual root partition:</strong> "},{"t":"code","lang":"bash","code":"lsblk                              # find your real root partition, e.g. /dev/sda2\nsudo mount /dev/sda2 /mnt\nsudo mount /dev/sda1 /mnt/boot/efi   # only if UEFI — mount the ESP too"},{"t":"callout","kind":"tip","html":"<strong>Step 3 — Bind the necessary system directories and chroot in:</strong> "},{"t":"code","lang":"bash","code":"for dir in /dev /dev/pts /proc /sys /run; do sudo mount --bind $dir /mnt$dir; done\nsudo chroot /mnt"},{"t":"callout","kind":"tip","html":"<strong>Step 4 — Reinstall GRUB from inside the chroot:</strong> "},{"t":"code","lang":"bash","code":"grub-install /dev/sda                 # legacy BIOS — target the whole disk, not a partition\n# or, for UEFI:\ngrub-install --target=x86_64-efi --efi-directory=/boot/efi --bootloader-id=GRUB\nupdate-grub"},{"t":"callout","kind":"tip","html":"<strong>Step 5 — Exit and reboot:</strong> "},{"t":"code","lang":"bash","code":"exit\nsudo reboot"}]},{"id":"quick-reference","title":"Quick Reference","blocks":[{"t":"code","lang":"bash","code":"STAGE 1 (firmware)   No display / \"no bootable device\"   → check boot order, disk detection\nSTAGE 2 (GRUB)         \"grub rescue>\" prompt                → grub.cfg broken, reinstall GRUB\nSTAGE 3 (kernel)        Kernel panic wall of text              → bad initramfs/kernel param\nSTAGE 4 (systemd)        \"emergency mode\"                        → check /etc/fstab FIRST\n\nDIAGNOSTIC COMMANDS\n  systemd-analyze              → total boot time, by stage\n  systemd-analyze blame          → slowest units, sorted\n  journalctl -b -1                → previous boot's full log\n  journalctl -k                    → kernel messages only"}]}]},{"id":"failure-scenarios","title":"Linux Failure Scenarios — What Actually Causes Errors & File Corruption","icon":"alert","category":"troubleshooting","preview":"","source":"linux-failure-scenarios.md","words":1746,"parts":[{"id":"introduction","title":"Introduction","blocks":[{"t":"text","html":"<p>A catalog of the specific wrong moves that break files, systems, or data on Linux — why each one happens, and how to avoid or recover from it.</p>"}]},{"id":"shell-redirection-traps","title":"Shell Redirection Traps","blocks":[{"t":"text","html":"<h6>Reading and writing the same file in one command</h6>"},{"t":"code","lang":"bash","code":"sort file.txt > file.txt      # WRONG — truncates file.txt to empty BEFORE sort ever reads it"},{"t":"callout","kind":"tip","html":"<strong>Why it corrupts:</strong> the shell opens <code>file.txt</code> for writing (truncating it to 0 bytes) before the command on the left even runs. By the time <code>sort</code> tries to read it, there's nothing left to read."},{"t":"callout","kind":"tip","html":"<strong>Fix:</strong> "},{"t":"code","lang":"bash","code":"sort file.txt -o file.txt     # many tools support in-place output flags\n# or\nsort file.txt > tmp && mv tmp file.txt"},{"t":"text","html":"<h6>`&gt;` vs `&gt;&gt;` confusion</h6>"},{"t":"code","lang":"bash","code":"echo \"new log line\" > app.log     # WRONG if you meant to append — wipes the entire log file first"},{"t":"text","html":"<p><code>&gt;</code> always truncates first. <code>&gt;&gt;</code> appends. This single character mistake is one of the most common ways people accidentally delete logs or config history.</p>"},{"t":"text","html":"<h6>Piping into `sudo` incorrectly</h6>"},{"t":"code","lang":"bash","code":"sudo echo \"text\" > /etc/somefile     # FAILS silently or with permission denied"},{"t":"callout","kind":"tip","html":"<strong>Why:</strong> <code>sudo</code> only elevates the <code>echo</code> — the <code>&gt;</code> redirection is still performed by your unprivileged shell, which can't write to a root-owned file."},{"t":"callout","kind":"tip","html":"<strong>Fix:</strong> "},{"t":"code","lang":"bash","code":"echo \"text\" | sudo tee /etc/somefile\necho \"text\" | sudo tee -a /etc/somefile   # append version"}]},{"id":"killing-a-process-mid-write","title":"Killing a Process Mid-Write","blocks":[{"t":"text","html":"<p>If you <code>kill -9</code> (SIGKILL) a process — or the process crashes, or the power dies — while it's in the middle of writing a file, the write can be left <strong>partially applied</strong>. SIGKILL cannot be caught or handled, so the process gets zero chance to close the file cleanly or finish its write.</p>"},{"t":"callout","kind":"tip","html":"<strong>High-risk moments:</strong> "},{"t":"list","items":["Editors saving a file (<code>Ctrl+O</code> in nano, <code>:w</code> in vim) — interrupted mid-save","Database writes, especially without journaling/WAL enabled","<code>dd</code>, <code>cp</code>, <code>rsync</code> of large files interrupted partway","Package manager mid-install (<code>apt</code>/<code>dpkg</code> writing package metadata)"]},{"t":"callout","kind":"tip","html":"<strong>Result:</strong> truncated files, half-written binaries that won't execute, or — for structured files like <code>/etc/passwd</code>-style configs — a corrupted line that breaks every tool that parses it afterward."},{"t":"callout","kind":"tip","html":"<strong>Mitigation:</strong> "},{"t":"list","items":["Prefer <code>SIGTERM</code> (<code>kill -15</code>, or plain <code>kill</code>) — gives the process a chance to finish and exit cleanly. Only escalate to <code>-9</code> if it's truly hung.","For critical files, write to a temp file and <code>mv</code> it into place atomically (a <code>mv</code> on the same filesystem is atomic — readers never see a partial file)."]}]},{"id":"editor-swap-files-crash-recovery","title":"Editor Swap Files & Crash Recovery","blocks":[{"t":"text","html":"<h6>Vim `.swp` conflict</h6>"},{"t":"text","html":"<p>Opening a file that's already open in another Vim session (or one that crashed) triggers:</p>"},{"t":"code","lang":"bash","code":"E325: ATTENTION\nFound a swap file by the name \".file.txt.swp\""},{"t":"callout","kind":"tip","html":"<strong>If you ignore this and choose \"Edit anyway\" while the original session is still active:</strong> you now have two Vim instances able to save over each other — whichever saves last wins, silently discarding the other session's edits."},{"t":"callout","kind":"tip","html":"<strong>Correct response to that prompt:</strong> "},{"t":"list","items":["<code>(O)pen Read-Only</code> if you just want to look","<code>(Q)uit</code> if another session is genuinely still editing it","<code>(D)elete</code> the swap file only if you're sure no other session is active (e.g. after a crash) — then reopen normally","<code>(R)ecover</code> to recover unsaved changes from a crash, via <code>vim -r file.txt</code>"]},{"t":"text","html":"<h6>Nano's lack of swap-file locking</h6>"},{"t":"text","html":"<p>Nano (by default) does <strong>not</strong> warn you if the same file is open in two nano sessions — both can save independently, and the second save simply overwrites the first, with no merge and no warning. If you're editing the same file from two terminals, this is a silent data-loss trap Vim would have caught and Nano won't.</p>"}]},{"id":"destructive-command-mistakes","title":"Destructive Command Mistakes","blocks":[{"t":"text","html":"<h6>`rm -rf` with a wrong or expanded path</h6>"},{"t":"code","lang":"bash","code":"rm -rf $DIR/*     # if $DIR is unset/empty, this becomes: rm -rf /*"},{"t":"callout","kind":"tip","html":"<strong>Why it's catastrophic:</strong> an unset variable expands to nothing, silently turning <code>$DIR/*</code> into <code>/*</code> — deleting from root. This is one of the most infamous Linux disaster patterns."},{"t":"callout","kind":"tip","html":"<strong>Mitigation:</strong> "},{"t":"code","lang":"bash","code":"set -u                       # in scripts: error out on unset variables instead of silently expanding empty\nrm -rf \"${DIR:?DIR not set}/\"*   # fails loudly instead of running against /"},{"t":"text","html":"<h6>Wildcard expansion including files you didn't intend</h6>"},{"t":"code","lang":"bash","code":"rm -- -rf     # a file literally named \"-rf\" needs -- to avoid being parsed as flags\nchmod 644 *   # if a filename starts with a dash, it can be misread as an option"},{"t":"text","html":"<h6>`dd` with the wrong `of=` target</h6>"},{"t":"code","lang":"bash","code":"dd if=image.iso of=/dev/sda    # WRONG target — wipes an entire disk, not a partition"},{"t":"callout","kind":"tip","html":"<strong>Why it's dangerous:</strong> <code>dd</code> has no \"are you sure\" prompt and no undo. Getting <code>/dev/sda</code> (whole disk) vs <code>/dev/sdb1</code> (a specific partition) wrong destroys everything on that device, silently and immediately."},{"t":"callout","kind":"tip","html":"<strong>Mitigation:</strong> always run <code>lsblk</code> immediately before a <code>dd</code> command to confirm the exact device name, and double/triple check <code>of=</code> before hitting Enter."}]},{"id":"permission-ownership-mistakes","title":"Permission & Ownership Mistakes","blocks":[{"t":"text","html":"<h6>Recursive chmod on the wrong directory</h6>"},{"t":"code","lang":"bash","code":"chmod -R 777 /     # catastrophic — breaks permission-dependent security across the entire OS"},{"t":"text","html":"<p>This breaks SSH (which refuses to work if key/config permissions are too open), sudo (which requires specific binary permissions), and most system services that check permission bits before trusting a file.</p>"},{"t":"text","html":"<h6>Recursive chown breaking service accounts</h6>"},{"t":"code","lang":"bash","code":"chown -R $USER:$USER /var/www    # if a webserver process expects www-data ownership, it can no longer read its own files"},{"t":"callout","kind":"tip","html":"<strong>General rule:</strong> never run <code>-R</code> permission/ownership changes against a directory you haven't fully scoped in your head first — target the narrowest path that actually needs the change."}]},{"id":"filesystem-level-corruption","title":"Filesystem-Level Corruption","blocks":[{"t":"text","html":"<h6>Unsafe shutdown / power loss during a write</h6>"},{"t":"text","html":"<p>If the system loses power (or is force-powered-off) while the filesystem has pending writes in its cache, files can end up with:</p>"},{"t":"list","items":["Zero-length or truncated content","Metadata pointing to data that was never actually written","In severe cases, filesystem structure damage requiring <code>fsck</code> to repair"]},{"t":"callout","kind":"tip","html":"<strong>Mitigation:</strong> always <code>sudo shutdown -h now</code> or <code>sync &amp;&amp; sudo shutdown -h now</code> rather than cutting power directly. <code>sync</code> flushes pending writes from memory to disk before shutdown."},{"t":"text","html":"<h6>Unmounting a drive while it's still in use</h6>"},{"t":"code","lang":"bash","code":"umount /mnt/usb     # fails or corrupts data if a process still has open file handles on it"},{"t":"text","html":"<p>If a file is still being written when the device is yanked or force-unmounted, the write is left incomplete. Use <code>lsof /mnt/usb</code> first to check nothing's still using it, or <code>umount -l</code> (lazy unmount) only as a last resort — it detaches the mount point immediately but lets in-flight I/O finish in the background, which is safer than yanking hardware outright.</p>"},{"t":"text","html":"<h6>Disk full during a write</h6>"},{"t":"text","html":"<p>Writing to a filesystem that fills up mid-write leaves a truncated file with no error surfaced to some tools (depends on how the writing program checks return codes). Always check <code>df -h</code> before large writes/copies, especially into <code>/</code>, <code>/var</code>, or <code>/tmp</code>, which fill up fastest from logs and package caches.</p>"}]},{"id":"text-encoding-line-ending-corruption","title":"Text Encoding & Line-Ending Corruption","blocks":[{"t":"text","html":"<h6>Windows line endings breaking a script</h6>"},{"t":"code","lang":"bash","code":"./script.sh\n# bash: ./script.sh: /bin/bash^M: bad interpreter: No such file or directory"},{"t":"callout","kind":"tip","html":"<strong>Why:</strong> the file has Windows-style <code>\\r\\n</code> line endings instead of Unix <code>\\n</code>. The shebang line (<code>#!/bin/bash</code>) ends up with an invisible <code>\\r</code> (<code>^M</code>) appended, and the kernel can't find an interpreter called <code>bash\\r</code>."},{"t":"callout","kind":"tip","html":"<strong>Fix:</strong> "},{"t":"code","lang":"bash","code":"dos2unix script.sh\n# or\nsed -i 's/\\r$//' script.sh"},{"t":"text","html":"<h6>Mixing character encodings</h6>"},{"t":"text","html":"<p>Editing a UTF-8 file with a tool/locale expecting Latin-1 (or vice versa) can silently mangle non-ASCII characters (accents, non-Latin scripts) into garbled bytes — often visible as <code>�</code> or seemingly random characters. Check with <code>file filename</code> (reports detected encoding) and set your editor/locale (<code>echo $LANG</code>) to match the file's actual encoding.</p>"},{"t":"text","html":"<h6>Editing a binary file as if it were text</h6>"},{"t":"text","html":"<p>Opening a binary (executable, image, compiled object) in Vim/Nano and saving it can corrupt it — text editors may \"normalize\" line endings or encoding on save, which mangles binary data that was never meant to be interpreted as text. If you must inspect binary content, use <code>xxd file</code> or <code>hexdump -C file</code>, not a text editor's save function.</p>"}]},{"id":"symlink-hardlink-pitfalls","title":"Symlink & Hardlink Pitfalls","blocks":[{"t":"text","html":"<h6>Deleting through a symlink with a trailing slash</h6>"},{"t":"code","lang":"bash","code":"rm -rf symlink_to_dir/    # the trailing slash makes some tools follow the link and delete the TARGET's contents, not just the link"},{"t":"text","html":"<p>Behavior here varies by tool and trailing-slash handling — the safe habit is to <code>rm</code> the link itself (no trailing slash) unless you specifically intend to touch the target's contents.</p>"},{"t":"text","html":"<h6>Broken symlinks after moving the target</h6>"},{"t":"text","html":"<p>Moving or renaming the file/directory a symlink points to leaves the symlink dangling — it still exists, but any read through it fails. <code>ls -la</code> shows dangling links in a distinct color in most terminals; <code>find -xtype l</code> finds all broken symlinks under a path.</p>"}]},{"id":"package-manager-corruption","title":"Package Manager Corruption","blocks":[{"t":"text","html":"<h6>Interrupting `apt`/`dnf` mid-install</h6>"},{"t":"text","html":"<p>Killing the terminal, losing power, or force-closing during a package install can leave the package database in a <code>dpkg was interrupted</code> state — subsequent <code>apt</code> commands refuse to run until it's repaired:</p>"},{"t":"code","lang":"bash","code":"sudo dpkg --configure -a     # resume/repair an interrupted dpkg state\nsudo apt --fix-broken install"},{"t":"text","html":"<h6>Running two package managers at once</h6>"},{"t":"text","html":"<p>Running <code>apt install</code> in two terminals simultaneously causes a lock contention error (<code>Could not get lock /var/lib/dpkg/lock</code>) — and if the lock itself is stale from a crashed process, forcibly deleting the lock file without confirming no process actually holds it can let two installs interleave and corrupt the package database.</p>"}]},{"id":"concurrent-access-race-conditions","title":"Concurrent Access Race Conditions","blocks":[{"t":"text","html":"<p>Two processes (or two terminal sessions, or a script and a human) writing to the same file at the same time — without any locking — will have the <strong>last write win</strong>, discarding whatever the other one wrote. This isn't Linux-specific but is extremely common in:</p>"},{"t":"list","items":["Editing the same config file from two SSH sessions","A cron job and a manual edit touching the same file simultaneously","A script appending to a log file while log rotation is renaming/truncating it"]},{"t":"callout","kind":"tip","html":"<strong>Mitigation:</strong> for anything script-driven, use <code>flock</code> to take an exclusive lock before writing:"},{"t":"code","lang":"bash","code":"flock /tmp/mylock.lock -c \"echo 'safe write' >> shared_file.txt\""}]},{"id":"quick-prevention-checklist","title":"Quick Prevention Checklist","blocks":[{"t":"list","items":["Never redirect (<code>&gt;</code>) output back into a file you're still reading as input in the same command.","Use <code>SIGTERM</code> before <code>SIGKILL</code> when stopping a process that might be mid-write.","Write critical files to a temp path, then atomically <code>mv</code> them into place.","Check <code>lsof</code> before force-unmounting or removing a device.","Always confirm <code>dd</code>'s <code>of=</code> target with <code>lsblk</code> immediately before running it.","Quote variables and use <code>set -u</code> in scripts to catch unset-variable disasters before they run.","Scope <code>-R</code> permission/ownership changes to the narrowest directory that needs it — never run them against <code>/</code> or a guess.","Run <code>dos2unix</code> on any script that came from a Windows machine or editor before executing it.","Use <code>flock</code> for any script that might run concurrently with itself or another writer."]}]}]},{"id":"linux-rules","title":"Linux System & Command Rules — Reference Guide","icon":"book","category":"reference","preview":"","source":"linux-rules-reference.md","words":2385,"parts":[{"id":"introduction","title":"Introduction","blocks":[{"t":"text","html":"<p>A reference for how the Linux system is built and how commands are structured — not a command dump, but the underlying rules that make the rest predictable.</p>"}]},{"id":"core-mental-model","title":"Core Mental Model","blocks":[{"t":"list","items":["<strong>Everything is a file.</strong> Devices, processes, sockets, even kernel interfaces (<code>/proc</code>, <code>/sys</code>) are represented as files.","<strong>Single unified tree.</strong> There's one root (<code>/</code>) — no drive letters. Everything, including other disks/partitions, gets mounted into this tree.","<strong>Case-sensitive.</strong> <code>File.txt</code> ≠ <code>file.txt</code> ≠ <code>FILE.txt</code>.","<strong>Extensions are cosmetic.</strong> <code>.sh</code>, <code>.txt</code>, <code>.py</code> are conventions for humans — the OS determines file type by content/permissions, not name.","<strong>Multi-user by design.</strong> Every process runs as a user; every file is owned by a user and group.","<strong>Configuration is text.</strong> Almost every system setting lives in a plain-text file (usually under <code>/etc</code>), not a binary registry."]}]},{"id":"filesystem-hierarchy-rules-fhs","title":"Filesystem Hierarchy Rules (FHS)","blocks":[{"t":"table","head":["Path","Purpose"],"rows":[["<code>/</code>","Root of everything"],["<code>/bin</code>, <code>/usr/bin</code>","Essential user command binaries"],["<code>/sbin</code>, <code>/usr/sbin</code>","System admin binaries (often need root)"],["<code>/etc</code>","System-wide configuration files"],["<code>/home</code>","Personal user directories"],["<code>/root</code>","Root user's home (separate from <code>/home</code>)"],["<code>/var</code>","Variable data: logs, caches, spool files"],["<code>/tmp</code>","Temporary files, usually cleared on reboot"],["<code>/opt</code>","Optional/third-party software"],["<code>/lib</code>, <code>/usr/lib</code>","Shared libraries"],["<code>/dev</code>","Device files (disks, terminals, etc.)"],["<code>/proc</code>","Virtual filesystem exposing kernel/process info live"],["<code>/sys</code>","Virtual filesystem exposing kernel/device info live"],["<code>/mnt</code>, <code>/media</code>","Mount points for filesystems/removable media"],["<code>/boot</code>","Kernel, bootloader files"]]},{"t":"callout","kind":"tip","html":"<strong>Rule of thumb:</strong> if it's a log → <code>/var/log</code>; if it's a config → <code>/etc</code>; if it's a live kernel stat → <code>/proc</code> or <code>/sys</code>."}]},{"id":"path-rules","title":"Path Rules","blocks":[{"t":"list","items":["<strong>Absolute path</strong>: starts with <code>/</code> — always resolved from root (<code>/home/solo/project</code>).","<strong>Relative path</strong>: resolved from your current directory (<code>../project</code>, <code>./script.sh</code>).","<code>.</code> = current directory, <code>..</code> = parent directory, <code>~</code> = current user's home directory.","Spaces and special characters (<code>$</code>, <code>*</code>, <code>&amp;</code>, <code>!</code>) must be escaped (<code>\\ </code>) or the whole path quoted (<code>\"my file.txt\"</code>).","Hidden files/directories start with <code>.</code> (e.g. <code>.bashrc</code>) — invisible to plain <code>ls</code>, shown with <code>ls -a</code>."]}]},{"id":"command-syntax-rules","title":"Command Syntax Rules","blocks":[{"t":"text","html":"<p>General anatomy:</p>"},{"t":"code","lang":"bash","code":"command [options] [arguments]"},{"t":"list","items":["<strong>Short options</strong>: single dash, single letter — <code>-a</code>, <code>-l</code>. Can often be combined: <code>-la</code> = <code>-l -a</code>.","<strong>Long options</strong>: double dash, full word — <code>--all</code>, <code>--verbose</code>.","<strong><code>--</code></strong> signals \"end of options\" — everything after is treated as a literal argument, even if it looks like a flag. Useful for filenames starting with <code>-</code>.","<strong>Case matters</strong> in flags too: <code>-R</code> (recursive, e.g. <code>chmod</code>) is not the same as <code>-r</code>.","Every standard command supports <code>--help</code>; every installed command has a manual: <code>man &lt;command&gt;</code>.","Exit codes: <code>0</code> = success, non-zero = failure. Check with <code>echo $?</code> right after a command."]}]},{"id":"permissions-rules","title":"Permissions Rules","blocks":[{"t":"text","html":"<p>Every file/directory has three permission sets: <strong>owner (u)</strong>, <strong>group (g)</strong>, <strong>others (o)</strong> — each with <strong>read (r)</strong>, <strong>write (w)</strong>, <strong>execute (x)</strong>.</p>"},{"t":"code","lang":"bash","code":"-rwxr-xr--  1 solo devs  4096 Aug 21 file.sh\n │└┬┘└┬┘└┬┘\n │ u  g  o\n └ file type (- file, d directory, l symlink)"},{"t":"callout","kind":"tip","html":"<strong>Numeric (octal) values:</strong> "},{"t":"table","head":["Permission","Value"],"rows":[["read","4"],["write","2"],["execute","1"]]},{"t":"text","html":"<p>Sum them per group: <code>rwx</code> = 7, <code>rw-</code> = 6, <code>r-x</code> = 5, <code>r--</code> = 4.</p>"},{"t":"code","lang":"bash","code":"chmod 755 script.sh     # rwxr-xr-x\nchmod u+x script.sh     # symbolic: add execute for owner\nchown solo:devs file    # change owner:group\nchgrp devs file         # change group only"},{"t":"callout","kind":"tip","html":"<strong>Special bits:</strong> "},{"t":"list","items":["<strong>setuid</strong> (<code>4000</code>) — run binary as the file's owner, not the caller.","<strong>setgid</strong> (<code>2000</code>) — run as file's group; on a directory, new files inherit that group.","<strong>sticky bit</strong> (<code>1000</code>) — in a shared directory (e.g. <code>/tmp</code>), only the file's owner can delete/rename it."]},{"t":"text","html":"<p><strong>Default permissions</strong>: governed by <code>umask</code> — the value subtracted from the system default (666 for files, 777 for dirs).</p>"}]},{"id":"users-groups-rules","title":"Users & Groups Rules","blocks":[{"t":"list","items":["<strong>root (UID 0)</strong> — unrestricted; every other user is UID ≥ 1000 (varies by distro).","Identity lives in <code>/etc/passwd</code> (users), <code>/etc/shadow</code> (password hashes), <code>/etc/group</code> (groups).","<strong><code>sudo</code></strong> runs a single command as root (or another user), logged and password-gated.","<strong><code>su</code></strong> switches your entire shell session to another user.","Every user has one <strong>primary group</strong> and can belong to multiple <strong>secondary groups</strong> — this is what group-based permission checks use."]},{"t":"text","html":"<h6>6.1 Checking who you currently are</h6>"},{"t":"text","html":"<p>Before switching anything, know where you stand:</p>"},{"t":"code","lang":"bash","code":"whoami          # prints your current username\nid              # prints your UID, GID, and every group you belong to\necho $UID        # 0 = root, anything else = regular user"},{"t":"text","html":"<p>Your shell prompt is also a live indicator: it typically ends in <code>$</code> for a regular user and <code>#</code> for root.</p>"},{"t":"text","html":"<h6>6.2 Step-by-Step: Becoming Root — Method 1 (`su`)</h6>"},{"t":"text","html":"<p><code>su</code> (\"switch user\") drops you into a full new shell session as another user — you stay in that session until you explicitly exit it.</p>"},{"t":"callout","kind":"tip","html":"<strong>Step 1 — Run the command:</strong> "},{"t":"code","lang":"bash","code":"su -"},{"t":"text","html":"<p>The trailing <code>-</code> matters: it loads root's own environment (its <code>$PATH</code>, its home directory <code>/root</code>, its shell config) instead of keeping your current user's environment. Without the <code>-</code>, you become root but keep your old user's environment, which can cause confusing <code>$PATH</code>/permission mismatches.</p>"},{"t":"text","html":"<p><strong>Step 2 — Enter root's password</strong> (not your own password — <code>su</code> asks for the target account's password):</p>"},{"t":"code","lang":"bash","code":"Password: ********"},{"t":"callout","kind":"tip","html":"<strong>Step 3 — Confirm you're root:</strong> "},{"t":"code","lang":"bash","code":"whoami    # should now print: root"},{"t":"callout","kind":"tip","html":"<strong>Step 4 — Exit back to your normal user when done:</strong> "},{"t":"code","lang":"bash","code":"exit\n# or press Ctrl+D"},{"t":"callout","kind":"tip","html":"<strong>Downside:</strong> <code>su</code> requires knowing root's actual password, which many modern distros (Ubuntu included) disable by default — root has no password set at all out of the box, so plain <code>su -</code> will fail until you explicitly set one with <code>sudo passwd root</code>."},{"t":"text","html":"<h6>6.3 Step-by-Step: Becoming Root — Method 2 (`sudo`)</h6>"},{"t":"text","html":"<p><code>sudo</code> is the modern, more common approach — it uses your own password (not root's) and only works if your user is listed in <code>/etc/sudoers</code> or belongs to the <code>sudo</code>/<code>wheel</code> group.</p>"},{"t":"callout","kind":"tip","html":"<strong>Step 1 — Confirm you have sudo rights:</strong> "},{"t":"code","lang":"bash","code":"groups    # look for \"sudo\" (Debian/Ubuntu) or \"wheel\" (RHEL/Fedora) in the output"},{"t":"callout","kind":"tip","html":"<strong>Step 2a — Run a single command as root (most common day-to-day use):</strong> "},{"t":"code","lang":"bash","code":"sudo apt update"},{"t":"text","html":"<p>You'll be prompted for <strong>your own</strong> password, not root's. <code>sudo</code> caches that authorization for a few minutes, so repeated <code>sudo</code> commands in a row won't keep re-prompting.</p>"},{"t":"callout","kind":"tip","html":"<strong>Step 2b — Get a full root shell instead of one command at a time:</strong> "},{"t":"code","lang":"bash","code":"sudo -i\n# or equivalently:\nsudo su -"},{"t":"text","html":"<p><code>sudo -i</code> behaves like <code>su -</code> — full root environment, root's home directory — but authenticated with your own password instead of root's.</p>"},{"t":"callout","kind":"tip","html":"<strong>Step 3 — Confirm:</strong> "},{"t":"code","lang":"bash","code":"whoami    # root"},{"t":"callout","kind":"tip","html":"<strong>Step 4 — Exit back to your normal user:</strong> "},{"t":"code","lang":"bash","code":"exit"},{"t":"text","html":"<h6>6.4 Which Method Should You Actually Use?</h6>"},{"t":"table","head":["Situation","Use"],"rows":[["One-off admin command (install a package, edit a config)","<code>sudo &lt;command&gt;</code>"],["Need several root commands in a row","<code>sudo -i</code> (or <code>sudo su -</code>)"],["Root has a set password and you specifically want classic <code>su</code> behavior","<code>su -</code>"],["Best practice on any modern personal/server system","<strong><code>sudo</code></strong> — it's logged (check <code>/var/log/auth.log</code>), tied to your own identity, and doesn't require a separate root password to exist at all"]]},{"t":"callout","kind":"tip","html":"<strong>Golden rule:</strong> don't stay logged in as root longer than you need to. Run what you need, then <code>exit</code> back to your normal user — staying in a root shell out of convenience is how a typo turns into a system-wide disaster (see the <code>chmod -R 777 /</code> and <code>rm -rf</code> scenarios in the failure-scenarios guide)."}]},{"id":"process-rules","title":"Process Rules","blocks":[{"t":"list","items":["Every process has a <strong>PID</strong> (process ID) and a <strong>PPID</strong> (parent process ID) — Linux processes form a tree, rooted at PID 1 (<code>systemd</code> on modern distros).","<strong>States</strong>: running, sleeping, stopped, zombie (finished but not yet reaped by its parent).","<strong>Foreground vs background</strong>: <code>&amp;</code> at the end backgrounds a job; <code>jobs</code> lists them; <code>fg</code>/<code>bg</code> bring them forward/resume them; <code>Ctrl+Z</code> suspends the current one.","<strong>Signals</strong> are how processes are told to do something — not killed by force by default:"]},{"t":"table","head":["Signal","Meaning"],"rows":[["<code>SIGHUP</code> (1)","Hangup / reload config"],["<code>SIGINT</code> (2)","Interrupt (Ctrl+C)"],["<code>SIGTERM</code> (15)","Polite \"please exit\" (default for <code>kill</code>)"],["<code>SIGKILL</code> (9)","Force-kill, cannot be caught or ignored"]]},{"t":"code","lang":"bash","code":"kill -15 1234      # ask nicely\nkill -9 1234        # force it, last resort\npkill -f \"process_name\""}]},{"id":"i-o-redirection-pipe-rules","title":"I/O Redirection & Pipe Rules","blocks":[{"t":"text","html":"<p>Every process starts with three open streams:</p>"},{"t":"table","head":["FD","Stream","Symbol"],"rows":[["0","stdin","<code>&lt;</code>"],["1","stdout","<code>&gt;</code>, <code>&gt;&gt;</code>"],["2","stderr","<code>2&gt;</code>"]]},{"t":"code","lang":"bash","code":"command > out.txt        # overwrite stdout to file\ncommand >> out.txt       # append stdout to file\ncommand 2> err.txt       # redirect only errors\ncommand &> all.txt       # redirect stdout AND stderr\ncommand < input.txt      # feed a file in as stdin"},{"t":"text","html":"<p><strong>Pipes (<code>|</code>)</strong> chain commands — stdout of the left becomes stdin of the right:</p>"},{"t":"code","lang":"bash","code":"ps aux | grep python | awk '{print $2}'"},{"t":"text","html":"<p><code>xargs</code> bridges commands that expect arguments, not stdin:</p>"},{"t":"code","lang":"bash","code":"find . -name \"*.log\" | xargs rm"}]},{"id":"wildcards-globbing-rules","title":"Wildcards & Globbing Rules","blocks":[{"t":"table","head":["Pattern","Matches"],"rows":[["<code>*</code>","Any number of characters (not hidden files unless combined with <code>.</code>)"],["<code>?</code>","Exactly one character"],["<code>[abc]</code>","Any one of a, b, or c"],["<code>[0-9]</code>","Any digit"],["<code>{a,b,c}</code>","Brace expansion — literal set: <code>file{1,2,3}.txt</code> → <code>file1.txt file2.txt file3.txt</code>"]]},{"t":"text","html":"<p>Globbing is expanded <strong>by the shell</strong>, before the command ever sees it — not by the command itself.</p>"}]},{"id":"environment-shell-rules","title":"Environment & Shell Rules","blocks":[{"t":"list","items":["<strong>Environment variables</strong> are key=value pairs available to a process and its children: <code>export VAR=value</code>.","<strong><code>$PATH</code></strong> is an ordered, colon-separated list of directories the shell searches for executables — first match wins. <code>which &lt;cmd&gt;</code> shows which one gets used.","<strong>Shell startup file load order</strong> (bash, login shell): <code>/etc/profile</code> → <code>~/.bash_profile</code> (or <code>~/.profile</code>) → for interactive non-login shells: <code>~/.bashrc</code>.","<strong>Aliases</strong> are shell-only shortcuts (<code>alias ll='ls -la'</code>) — they don't exist for scripts run by other programs.","Quoting matters: <code>\"$VAR\"</code> expands the variable; <code>'$VAR'</code> treats it as a literal string."]}]},{"id":"package-management-rules","title":"Package Management Rules","blocks":[{"t":"table","head":["Family","Distros","Low-level","High-level"],"rows":[["Debian","Ubuntu, Debian","<code>dpkg</code>","<code>apt</code>, <code>apt-get</code>"],["Red Hat","RHEL, Fedora, CentOS","<code>rpm</code>","<code>dnf</code>, <code>yum</code>"]]},{"t":"list","items":["High-level tools (<code>apt</code>, <code>dnf</code>) resolve <strong>dependencies</strong> automatically; low-level tools (<code>dpkg</code>, <code>rpm</code>) install a single package file and expect dependencies to already be present.","Always <code>apt update</code> (refresh package index) before <code>apt install</code> (actually install) — these are two different, sequential steps."]}]},{"id":"service-management-rules-systemd","title":"Service Management Rules (systemd)","blocks":[{"t":"list","items":["Modern distros use <strong>systemd</strong> (PID 1) to manage services via <strong>unit files</strong>, typically in <code>/etc/systemd/system/</code> or <code>/lib/systemd/system/</code>."]},{"t":"code","lang":"bash","code":"systemctl start nginx      # start now\nsystemctl stop nginx       # stop now\nsystemctl enable nginx     # start automatically on boot\nsystemctl status nginx     # current state\njournalctl -u nginx -f     # live-tail that service's logs"},{"t":"list","items":["<code>enable</code> and <code>start</code> are independent — enabling doesn't start it now, starting doesn't survive a reboot. Do both if you want \"on now, and on every boot.\""]}]},{"id":"networking-rules","title":"Networking Rules","blocks":[{"t":"list","items":["Ports below <strong>1024</strong> are \"privileged\" — binding to them requires root (or a capability grant).","<code>ss -tulnp</code> — show listening ports and the process using them (modern replacement for <code>netstat</code>).","<code>ssh user@host</code> — remote shell; key-based auth (<code>~/.ssh/id_ed25519</code>) is the standard over passwords.","<code>curl</code> / <code>wget</code> — fetch over HTTP(S); <code>curl</code> is better for APIs (headers, methods), <code>wget</code> for straight downloads."]},{"t":"text","html":"<h6>13.1 Viewing &amp; Configuring Network Interfaces — Two Ways</h6>"},{"t":"text","html":"<p>There are two tool families for this: the legacy <code>net-tools</code> package (<code>ifconfig</code>, <code>route</code>) and the modern <code>iproute2</code> package (<code>ip</code>). Modern distros ship <code>ip</code> by default; <code>ifconfig</code> often needs manual install now. Both are shown here since you'll run into either depending on the machine.</p>"},{"t":"callout","kind":"tip","html":"<strong>Check which you have installed:</strong> "},{"t":"code","lang":"bash","code":"which ifconfig    # empty output = not installed\nwhich ip           # this one is almost always present\nsudo apt install net-tools -y     # installs ifconfig if it's missing"},{"t":"text","html":"<p>#### Method 1 — <code>ifconfig</code> (legacy, still common on older systems)</p>"},{"t":"callout","kind":"tip","html":"<strong>Step 1 — View all active interfaces:</strong> "},{"t":"code","lang":"bash","code":"ifconfig"},{"t":"callout","kind":"tip","html":"<strong>Step 2 — View all interfaces, including inactive ones:</strong> "},{"t":"code","lang":"bash","code":"ifconfig -a"},{"t":"callout","kind":"tip","html":"<strong>Step 3 — View just one interface:</strong> "},{"t":"code","lang":"bash","code":"ifconfig eth0"},{"t":"callout","kind":"tip","html":"<strong>Step 4 — Bring an interface up or down:</strong> "},{"t":"code","lang":"bash","code":"sudo ifconfig eth0 up\nsudo ifconfig eth0 down"},{"t":"callout","kind":"tip","html":"<strong>Step 5 — Manually assign an IP address:</strong> "},{"t":"code","lang":"bash","code":"sudo ifconfig eth0 192.168.1.50 netmask 255.255.255.0"},{"t":"callout","kind":"tip","html":"<strong>Step 6 — Check the routing table (companion command):</strong> "},{"t":"code","lang":"bash","code":"route -n"},{"t":"text","html":"<p>#### Method 2 — <code>ip</code> (modern, the current standard)</p>"},{"t":"callout","kind":"tip","html":"<strong>Step 1 — View all interfaces and addresses:</strong> "},{"t":"code","lang":"bash","code":"ip a\n# or the more explicit form:\nip addr show"},{"t":"callout","kind":"tip","html":"<strong>Step 2 — View just one interface:</strong> "},{"t":"code","lang":"bash","code":"ip addr show eth0"},{"t":"callout","kind":"tip","html":"<strong>Step 3 — Bring an interface up or down:</strong> "},{"t":"code","lang":"bash","code":"sudo ip link set eth0 up\nsudo ip link set eth0 down"},{"t":"callout","kind":"tip","html":"<strong>Step 4 — Manually assign an IP address (note: CIDR notation, not a separate netmask):</strong> "},{"t":"code","lang":"bash","code":"sudo ip addr add 192.168.1.50/24 dev eth0"},{"t":"callout","kind":"tip","html":"<strong>Step 5 — Remove an assigned IP:</strong> "},{"t":"code","lang":"bash","code":"sudo ip addr del 192.168.1.50/24 dev eth0"},{"t":"callout","kind":"tip","html":"<strong>Step 6 — Check the routing table:</strong> "},{"t":"code","lang":"bash","code":"ip route"},{"t":"callout","kind":"tip","html":"<strong>Important distinction for both methods:</strong> changes made this way are <strong>temporary</strong> — they're wiped on reboot or interface restart. For a permanent change, edit your distro's network config instead (Netplan's YAML files on modern Ubuntu, <code>/etc/network/interfaces</code> on older Debian-based systems, or <code>nmcli</code>/<code>nmtui</code> if NetworkManager is running the show)."},{"t":"text","html":"<h6>13.2 Command Equivalence Table</h6>"},{"t":"table","head":["Task","`ifconfig` (legacy)","`ip` (modern)"],"rows":[["Show all interfaces","<code>ifconfig</code>","<code>ip a</code>"],["Show one interface","<code>ifconfig eth0</code>","<code>ip addr show eth0</code>"],["Bring interface up","<code>ifconfig eth0 up</code>","<code>ip link set eth0 up</code>"],["Bring interface down","<code>ifconfig eth0 down</code>","<code>ip link set eth0 down</code>"],["Assign an IP","<code>ifconfig eth0 &lt;ip&gt; netmask &lt;mask&gt;</code>","<code>ip addr add &lt;ip&gt;/&lt;cidr&gt; dev eth0</code>"],["View routing table","<code>route -n</code>","<code>ip route</code>"]]},{"t":"callout","kind":"tip","html":"<strong>Which to actually learn:</strong> default to <code>ip</code> — it's the maintained tool and what you'll find on nearly every current server. Recognize <code>ifconfig</code> syntax for when you land on an older box that still has it, but don't build new habits around it."}]},{"id":"golden-rules-common-gotchas","title":"Golden Rules & Common Gotchas","blocks":[{"t":"list","items":["<strong><code>rm -rf</code> has no undo.</strong> Double-check <code>pwd</code> and the target path before running anything destructive with <code>-rf</code>, especially as root.","<strong>Never run untrusted scripts with <code>sudo</code></strong> without reading them first.","<strong>Quote your variables</strong> in scripts (<code>\"$var\"</code>) — unquoted variables break on spaces/globs.","<strong>Symlinks vs hardlinks</strong>: a symlink (<code>ln -s</code>) is a pointer to a path and breaks if the target moves; a hardlink (<code>ln</code>) points to the same inode and survives the original being deleted.","<strong>A command that \"isn't found\"</strong> is almost always a <code>$PATH</code> issue, not a missing install — check with <code>which</code> or <code>type</code>.","<strong>Trailing slashes matter</strong> for some commands (notably <code>rsync</code>) — <code>dir/</code> vs <code>dir</code> changes whether the directory itself or its contents are the target."]}]}]},{"id":"log-management","title":"Log Management — syslog vs journald, logrotate & Where Logs Actually Live","icon":"file","category":"logging","preview":"","source":"Log Management.md","words":1320,"parts":[{"id":"introduction","title":"Introduction","blocks":[{"t":"text","html":"<p>Two logging systems coexist on most modern Linux distros, often confusingly overlapping. This is what each one actually does, how they hand off to each other, how rotation keeps them from filling your disk, and where to actually look for any given service's output.</p>"}]},{"id":"the-core-confusion-syslog-vs-journald","title":"The Core Confusion: syslog vs journald","blocks":[{"t":"table","head":["","syslog (rsyslog/syslog-ng)","journald (systemd)"],"rows":[["What it is","The traditional Unix logging daemon/protocol","systemd's own logging component"],["Storage format","Plain text files","Binary, indexed format"],["Location","<code>/var/log/*.log</code> (readable with <code>cat</code>, <code>tail</code>, <code>grep</code>)","<code>/var/log/journal/</code> (only readable through <code>journalctl</code>)"],["Structure","Just text lines, minimal built-in structure","Rich metadata per entry: PID, UID, unit name, boot ID, etc."],["Persistence","Always persistent (it's just files)","Persistent OR volatile depending on config (see below)"],["Query power","<code>grep</code>/<code>awk</code> on plain text","Native filtering — by service, time range, priority, boot"]]},{"t":"callout","kind":"tip","html":"<strong>Why both exist on the same system:</strong> journald is what actually captures logs first on any systemd-based distro (which is nearly everything now — Ubuntu, Debian, Fedora, RHEL, Arch). rsyslog then either reads from journald and writes out the traditional <code>/var/log/*.log</code> files, or runs independently for anything not going through systemd. On most modern distros, journald is the source of truth and the classic <code>/var/log</code> files are a compatibility layer built on top of it."},{"t":"callout","kind":"tip","html":"<strong>Practical implication:</strong> for any service managed by systemd, <code>journalctl -u &lt;service&gt;</code> is more complete and more precise than grepping <code>/var/log/syslog</code> — you get structured filtering (by exact service, exact boot, exact priority) that plain text grepping can only approximate."}]},{"id":"journald-configuration-persistence","title":"journald — Configuration & Persistence","blocks":[{"t":"text","html":"<h6>Is journald even keeping logs across reboots?</h6>"},{"t":"code","lang":"bash","code":"journalctl --disk-usage         # shows how much space the journal is currently using\nls /var/log/journal/               # if this directory exists and has content, logs are persistent"},{"t":"text","html":"<p>By default on many distros, journald logs are <strong>volatile</strong> — kept only in <code>/run/log/journal</code> (memory-backed, wiped on reboot) unless persistent storage is explicitly enabled.</p>"},{"t":"text","html":"<h6>Enabling persistent journal storage</h6>"},{"t":"code","lang":"bash","code":"sudo mkdir -p /var/log/journal\nsudo systemd-tmpfiles --create --prefix /var/log/journal\nsudo systemctl restart systemd-journald"},{"t":"text","html":"<p>After this, <code>journalctl -b -1</code> (previous boot's logs) actually works — without it, a reboot wipes your only crash evidence.</p>"},{"t":"text","html":"<h6>Key config: `/etc/systemd/journald.conf`</h6>"},{"t":"code","lang":"ini","code":"[Journal]\nStorage=persistent          # persistent | volatile | auto\nSystemMaxUse=500M            # cap total disk space the journal can consume\nSystemMaxFileSize=50M         # size of each individual journal file before rotating\nMaxRetentionSec=30day          # delete entries older than this, regardless of size"},{"t":"text","html":"<p>Apply changes with:</p>"},{"t":"code","lang":"bash","code":"sudo systemctl restart systemd-journald"},{"t":"callout","kind":"tip","html":"<strong>This matters more than it looks:</strong> without <code>SystemMaxUse</code>, an unexpectedly chatty service (a crash-looping process logging constantly) can fill <code>/var/log/journal</code> and, by extension, your root filesystem — see the disk-full failure scenarios from your earlier guide. Always cap it explicitly."},{"t":"text","html":"<h6>Manually cleaning the journal</h6>"},{"t":"code","lang":"bash","code":"sudo journalctl --vacuum-size=200M     # shrink the journal down to 200MB\nsudo journalctl --vacuum-time=7d         # delete anything older than 7 days"}]},{"id":"where-every-service-actually-writes-its-logs","title":"Where Every Service Actually Writes Its Logs","blocks":[{"t":"text","html":"<p>This is the part most guides skip — a real map of what's where.</p>"},{"t":"text","html":"<h6>systemd-managed services (the majority on a modern distro)</h6>"},{"t":"code","lang":"bash","code":"journalctl -u <service_name>"},{"t":"text","html":"<p>This is the authoritative source. No separate log file exists unless the service also writes its own (many do, for app-specific reasons — see below).</p>"},{"t":"text","html":"<h6>Classic system-wide log files (`/var/log/`)</h6>"},{"t":"table","head":["File","Contents"],"rows":[["<code>/var/log/syslog</code> (Debian/Ubuntu) or <code>/var/log/messages</code> (RHEL/Fedora)","General system messages, the traditional catch-all"],["<code>/var/log/auth.log</code> (Debian/Ubuntu) or <code>/var/log/secure</code> (RHEL/Fedora)","Authentication events — logins, <code>sudo</code> usage, SSH attempts"],["<code>/var/log/kern.log</code>","Kernel messages (also viewable live via <code>dmesg</code> or <code>journalctl -k</code>)"],["<code>/var/log/dpkg.log</code>","Package install/remove/upgrade history (Debian/Ubuntu)"],["<code>/var/log/boot.log</code>","Messages from the boot process"],["<code>/var/log/faillog</code> / <code>/var/log/lastlog</code>","Failed login attempts / last login per user"]]},{"t":"text","html":"<h6>Application-specific logs (each has its own convention — worth knowing the common ones)</h6>"},{"t":"table","head":["Service","Log location"],"rows":[["nginx","<code>/var/log/nginx/access.log</code>, <code>/var/log/nginx/error.log</code>"],["Apache","<code>/var/log/apache2/access.log</code>, <code>/var/log/apache2/error.log</code> (Debian) or <code>/var/log/httpd/</code> (RHEL)"],["MySQL/MariaDB","<code>/var/log/mysql/error.log</code>"],["PostgreSQL","<code>/var/log/postgresql/postgresql-&lt;version&gt;-main.log</code>"],["Docker containers","<code>docker logs &lt;container&gt;</code> (reads the container's own log driver output, usually JSON files under <code>/var/lib/docker/containers/&lt;id&gt;/</code>)"],["cron jobs","<code>/var/log/cron.log</code>, or wherever the job's own script redirects output (cron itself only logs that it ran, not the job's stdout, unless you explicitly redirect it)"],["Fail2ban","<code>/var/log/fail2ban.log</code>"],["UFW","<code>/var/log/ufw.log</code>"]]},{"t":"text","html":"<h6>Finding a log location you don't already know</h6>"},{"t":"code","lang":"bash","code":"sudo find /var/log -name \"*<servicename>*\"       # search by name pattern\nsudo lsof | grep -i \"\\.log$\" | grep <process_name>  # find open log files for a running process, by name\ncat /etc/<servicename>/*.conf | grep -i log            # check the service's own config for a configured log path"},{"t":"callout","kind":"tip","html":"<strong>A genuinely useful habit:</strong> when in doubt for a systemd-managed service, start with <code>journalctl -u &lt;service&gt;</code> regardless of whether it also has its own log file — it captures stdout/stderr from the very moment the process starts, before the application has even opened its own log file, which makes it the best source for startup failures specifically."}]},{"id":"logrotate-keeping-log-files-from-growing-forever","title":"`logrotate` — Keeping Log Files From Growing Forever","blocks":[{"t":"text","html":"<p><code>logrotate</code> handles the traditional <code>/var/log/*.log</code> files — journald manages its own size internally (via <code>SystemMaxUse</code>, above) and does <strong>not</strong> use logrotate.</p>"},{"t":"text","html":"<h6>How it works, conceptually</h6>"},{"t":"text","html":"<p>On a schedule (typically daily, via a cron job or systemd timer), <code>logrotate</code> checks each configured log file against rules: if it's grown too large or too old, it gets renamed (<code>access.log</code> → <code>access.log.1</code>), optionally compressed, and a fresh empty log file is started — with old rotations eventually deleted once a configured count is exceeded.</p>"},{"t":"text","html":"<h6>Where the config lives</h6>"},{"t":"code","lang":"bash","code":"/etc/logrotate.conf              # global defaults\n/etc/logrotate.d/                # per-service config files — this is where most real rules live"},{"t":"code","lang":"bash","code":"ls /etc/logrotate.d/     # nginx, apache2, mysql-server, etc — most packages install their own rule here automatically"},{"t":"text","html":"<h6>Anatomy of a logrotate config</h6>"},{"t":"code","lang":"bash","code":"/var/log/nginx/*.log {\n    daily\n    missingok\n    rotate 14\n    compress\n    delaycompress\n    notifempty\n    create 0640 www-data adm\n    sharedscripts\n    postrotate\n        systemctl reload nginx > /dev/null 2>&1 || true\n    endscript\n}"},{"t":"table","head":["Directive","Meaning"],"rows":[["<code>daily</code> / <code>weekly</code> / <code>monthly</code>","how often to rotate (can also be size-based, see below)"],["<code>size 100M</code>","rotate once the file exceeds this size, instead of/in addition to time-based"],["<code>rotate 14</code>","keep 14 old rotations before deleting the oldest"],["<code>compress</code>","gzip old rotations to save space"],["<code>delaycompress</code>","delay compressing the most recent rotation by one cycle — some apps still have it open briefly after rotation, this avoids a race"],["<code>missingok</code>","don't error if the log file doesn't exist"],["<code>notifempty</code>","don't rotate an empty file — no point"],["<code>create 0640 www-data adm</code>","after rotating, create a fresh file with these permissions/owner, so the service doesn't need to be restarted to start writing again"],["<code>postrotate</code> / <code>endscript</code>","shell commands to run after rotation — commonly used to signal the service to reopen its log file handle"]]},{"t":"callout","kind":"tip","html":"<strong>Why <code>postrotate</code> matters more than it looks:</strong> many services keep a log file open by file descriptor, not by name. If you rotate the file (rename it) without telling the service, it keeps writing into the now-renamed old file — the new <code>access.log</code> stays empty forever, and you silently lose all future logging until the service is restarted. The <code>postrotate</code> hook (commonly <code>systemctl reload</code> or a <code>kill -HUP</code>) tells the service to close and reopen its log handle by name, picking up the fresh file."},{"t":"text","html":"<h6>Testing a logrotate config without waiting for the schedule</h6>"},{"t":"code","lang":"bash","code":"sudo logrotate -d /etc/logrotate.d/nginx     # dry run — shows what WOULD happen, changes nothing\nsudo logrotate -f /etc/logrotate.d/nginx      # force it to actually rotate right now"},{"t":"text","html":"<h6>Writing your own rule for a custom app</h6>"},{"t":"code","lang":"bash","code":"/var/log/myapp/*.log {\n    weekly\n    rotate 8\n    compress\n    missingok\n    notifempty\n    create 0644 myappuser myappuser\n}"},{"t":"text","html":"<p>Save this as <code>/etc/logrotate.d/myapp</code> — no restart of <code>logrotate</code> itself needed, it's read fresh on every scheduled run.</p>"}]},{"id":"practical-cheat-sheet","title":"Practical Cheat Sheet","blocks":[{"t":"code","lang":"bash","code":"VIEW A SERVICE'S LOGS     journalctl -u <service> -f\nVIEW SYSTEM-WIDE LOGS      tail -f /var/log/syslog        (or /var/log/messages on RHEL-family)\nCHECK JOURNAL DISK USAGE   journalctl --disk-usage\nSHRINK THE JOURNAL          journalctl --vacuum-size=200M\nFIND A LOG FILE              sudo find /var/log -name \"*<name>*\"\nLIST LOGROTATE RULES         ls /etc/logrotate.d/\nTEST A LOGROTATE RULE         sudo logrotate -d /etc/logrotate.d/<name>\nFORCE ROTATION NOW            sudo logrotate -f /etc/logrotate.d/<name>"},{"t":"callout","kind":"tip","html":"<strong>One-line mental model to keep:</strong> journald captures everything systemd starts, in a queryable binary format that self-manages its size; logrotate manages everything that writes plain text files to <code>/var/log</code>, on a schedule you configure per-service. Most real systems run both side by side, and knowing which one owns a given log is the fastest way to stop searching in the wrong place."}]}]},{"id":"network-troubleshooting","title":"Networking Troubleshooting Toolkit — \"Why Can't This Reach That?\"","icon":"zap","category":"networking","preview":"","source":"Networking Troubleshooting Toolkit .md","words":1622,"parts":[{"id":"introduction","title":"Introduction","blocks":[{"t":"text","html":"<p>The tools for isolating exactly where a connection breaks: DNS, routing, a blocked port, or the application itself. Each tool below answers a different link in that chain.</p>"}]},{"id":"the-mental-model-where-connections-actually-brea","title":"The Mental Model — Where Connections Actually Break","blocks":[{"t":"code","lang":"bash","code":"1. DNS         →  can the name even resolve to an IP?\n2. Reachability →  can a packet get to that IP at all?\n3. Routing       →  what path is it taking, and where does it stop?\n4. Port/Service   →  is the specific port open and listening?\n5. Application     →  is the service responding correctly at the protocol level?"},{"t":"text","html":"<p>Every \"can't connect\" problem lives at exactly one of these layers — the tools below map directly onto them, in the order you should actually check them.</p>"}]},{"id":"ping-is-it-reachable-at-all","title":"`ping` — Is It Reachable At All?","blocks":[{"t":"code","lang":"bash","code":"ping google.com\nping -c 4 google.com        # send exactly 4 packets, then stop (default is infinite until Ctrl+C)\nping -i 0.5 google.com        # interval between packets, in seconds\nping -s 1000 google.com        # custom packet size (bytes) — useful for testing MTU issues\nping -W 2 google.com            # timeout per packet, in seconds"},{"t":"text","html":"<h6>Reading the output</h6>"},{"t":"code","lang":"bash","code":"64 bytes from 142.250.80.14: icmp_seq=1 ttl=118 time=14.2 ms"},{"t":"table","head":["Field","Meaning"],"rows":[["<code>icmp_seq</code>","sequence number — gaps in this sequence mean dropped packets"],["<code>ttl</code>","Time To Live remaining when it arrived — roughly indicates how many hops away the source is (starting TTL varies by OS, typically 64/128/255)"],["<code>time</code>","round-trip latency in milliseconds"]]},{"t":"code","lang":"bash","code":"4 packets transmitted, 4 received, 0% packet loss, time 3004ms"},{"t":"text","html":"<p>Any non-zero packet loss here is worth investigating further — even 1-2% loss can cause real application-level flakiness.</p>"},{"t":"text","html":"<h6>What ping tells you — and what it doesn't</h6>"},{"t":"list","items":["<strong>Tells you:</strong> whether the host responds to ICMP at all, and rough latency/loss.","<strong>Doesn't tell you:</strong> whether the actual service you care about (a web server, a database, SSH) is reachable — many firewalls block ICMP specifically while still allowing real traffic through, so <strong>\"ping fails\" does not always mean \"the service is down\"</strong>, and <strong>\"ping succeeds\" does not mean the service is up</strong>. Treat ping as a reachability hint, not a service check."]}]},{"id":"traceroute-where-does-the-path-actually-break","title":"`traceroute` — Where Does the Path Actually Break?","blocks":[{"t":"text","html":"<h6>How it works, briefly</h6>"},{"t":"text","html":"<p>It sends packets with progressively increasing TTL values (1, 2, 3...). Each router along the path decrements TTL by 1; when a packet's TTL hits 0, that router sends back an error instead of forwarding it — which is how traceroute discovers each hop, one at a time, without ever needing cooperation from the destination itself.</p>"},{"t":"code","lang":"bash","code":"sudo apt install traceroute -y     # often not installed by default\ntraceroute google.com\ntraceroute -n google.com             # skip reverse-DNS lookups per hop — much faster, IPs only"},{"t":"text","html":"<h6>Reading the output</h6>"},{"t":"code","lang":"bash","code":" 1  192.168.1.1  1.203 ms  1.150 ms  1.098 ms\n 2  10.10.0.1     8.552 ms  8.402 ms  8.310 ms\n 3  * * *\n 4  203.0.113.1  15.221 ms  14.998 ms  15.102 ms"},{"t":"list","items":["Three times per hop = three separate probe packets, for consistency.","<code>* * *</code> means that hop didn't respond — <strong>this is often normal</strong>, not necessarily a failure. Many routers are configured to not respond to traceroute probes at all while still forwarding traffic perfectly fine. Only treat this as a real problem if the trace <strong>never recovers</strong> past that point (every subsequent hop also times out) or never reaches the destination.","<strong>Where the trace actually stops (and never resumes) is your strongest clue</strong> for where the real problem is — a firewall, a dead link, or a misconfigured route right at that hop."]},{"t":"text","html":"<h6>`mtr` — the better version for ongoing diagnosis</h6>"},{"t":"code","lang":"bash","code":"sudo apt install mtr -y\nmtr google.com"},{"t":"text","html":"<p>Combines ping and traceroute into one continuously-updating view — instead of a single snapshot, you see live loss percentage and latency <strong>per hop</strong>, which makes intermittent problems (a flaky hop that only drops packets sometimes) far easier to spot than a one-shot <code>traceroute</code>.</p>"}]},{"id":"dig-nslookup-is-dns-the-problem","title":"`dig` / `nslookup` — Is DNS the Problem?","blocks":[{"t":"text","html":"<p>DNS issues are one of the most common causes of \"can't reach X\" — and the easiest to misdiagnose as a routing/firewall problem if you don't check it first.</p>"},{"t":"text","html":"<h6>`dig` — the more detailed, modern tool</h6>"},{"t":"code","lang":"bash","code":"dig example.com                  # full detailed query\ndig +short example.com             # just the resolved IP — the fast version for quick checks\ndig example.com MX                   # mail server records\ndig example.com NS                    # nameservers for the domain\ndig example.com TXT                    # TXT records (SPF, verification records, etc)\ndig -x 8.8.8.8                           # reverse lookup — IP to hostname\ndig @1.1.1.1 example.com                  # query a SPECIFIC DNS server directly, bypassing your configured resolver"},{"t":"callout","kind":"tip","html":"<strong>Why querying a specific server (<code>@1.1.1.1</code>) matters for troubleshooting:</strong> it isolates whether the problem is your local/configured DNS resolver specifically, or the domain's DNS records themselves. If <code>dig @1.1.1.1 example.com</code> resolves fine but plain <code>dig example.com</code> doesn't, your configured resolver (often in <code>/etc/resolv.conf</code>) is the actual problem, not the domain."},{"t":"text","html":"<h6>Reading `dig`'s output</h6>"},{"t":"code","lang":"bash","code":";; QUESTION SECTION:\n;example.com.          IN  A\n\n;; ANSWER SECTION:\nexample.com.    299  IN  A  93.184.216.34\n\n;; Query time: 24 msec\n;; SERVER: 127.0.0.53#53(127.0.0.53)"},{"t":"list","items":["<strong>ANSWER SECTION empty</strong> → the domain doesn't resolve at all, or you queried the wrong record type","<strong>SERVER line</strong> → confirms exactly which DNS server actually answered — critical for the <code>@</code> isolation trick above","<strong>Query time</strong> → high values (hundreds of ms+) can indicate a slow/distant/overloaded resolver"]},{"t":"text","html":"<h6>`nslookup` — older, still common, simpler output</h6>"},{"t":"code","lang":"bash","code":"nslookup example.com\nnslookup example.com 1.1.1.1     # query a specific server, same idea as dig's @ syntax"},{"t":"text","html":"<h6>Checking your actual configured resolver</h6>"},{"t":"code","lang":"bash","code":"cat /etc/resolv.conf\nresolvectl status         # on systemd-resolved systems — shows the real active resolver, which can differ from resolv.conf"}]},{"id":"checking-a-specific-port-is-the-service-actually","title":"Checking a Specific Port — Is the Service Actually Listening?","blocks":[{"t":"text","html":"<p>DNS resolving and the host being pingable doesn't mean the specific port/service you care about is open.</p>"},{"t":"code","lang":"bash","code":"nc -zv example.com 443        # -z = scan mode (no data sent), -v = verbose — tells you open/closed instantly\ntelnet example.com 443           # older alternative, connects and leaves you in an interactive session if it succeeds"},{"t":"callout","kind":"tip","html":"<strong>On the local machine, check what's actually listening:</strong> "},{"t":"code","lang":"bash","code":"ss -tulnp\n# -t tcp  -u udp  -l listening only  -n numeric ports  -p show the owning process"},{"t":"text","html":"<p>If a service isn't in this list at all, it's not the network's fault — the service itself isn't running or isn't bound to the port/interface you expect.</p>"}]},{"id":"tcpdump-see-the-actual-packets","title":"`tcpdump` — See the Actual Packets","blocks":[{"t":"text","html":"<p>When ping/traceroute/dig/port-checks all look fine but something's still wrong, <code>tcpdump</code> shows you the raw truth of what's actually going out and coming back.</p>"},{"t":"code","lang":"bash","code":"sudo tcpdump -i eth0                    # capture on a specific interface (find names with ip a)\nsudo tcpdump -i any                       # capture on all interfaces\nsudo tcpdump -i eth0 host 203.0.113.5      # filter to one specific IP\nsudo tcpdump -i eth0 port 443                # filter to one specific port\nsudo tcpdump -i eth0 host 203.0.113.5 and port 443    # combine filters\nsudo tcpdump -i eth0 -n                      # skip DNS resolution on captured IPs — faster, cleaner output\nsudo tcpdump -i eth0 -w capture.pcap           # save raw capture to a file (open later in Wireshark for deep analysis)\nsudo tcpdump -r capture.pcap                    # read back a saved capture"},{"t":"text","html":"<h6>A genuinely common diagnostic pattern</h6>"},{"t":"code","lang":"bash","code":"# On the SERVER, check if a client's connection attempt is even arriving:\nsudo tcpdump -i eth0 port 22\n# then attempt to SSH in from the client"},{"t":"text","html":"<p><strong>If you see the SYN packet arrive but no response goes back</strong> → the OS-level firewall (ufw/iptables) is silently dropping it — the packet reaches the box, the service just never gets a chance to answer. <strong>If you see nothing arrive at all</strong> → the problem is upstream — router port forwarding, an ISP-level block, or the packet never left the client's own network correctly.</p>"},{"t":"text","html":"<p>This single check is often the fastest way to definitively answer \"is it a firewall problem or a routing problem\" — something ping/traceroute alone can't always distinguish.</p>"},{"t":"text","html":"<h6>Reading basic tcpdump output</h6>"},{"t":"code","lang":"bash","code":"14:32:01.123456 IP 203.0.113.5.54321 > 10.0.0.5.22: Flags [S], seq 123456, win 64240"},{"t":"list","items":["<code>Flags [S]</code> = SYN (connection attempt)","<code>Flags [S.]</code> = SYN-ACK (server accepting)","<code>Flags [.]</code> = ACK","<code>Flags [R]</code> = RST (connection actively refused/reset — different from a silent drop)","A <code>[S]</code> with no <code>[S.]</code> reply within the capture = the target isn't responding, consistent with either a firewall drop or the service not listening"]}]},{"id":"curl-v-when-it-s-an-application-layer-problem-no","title":"`curl -v` — When It's an Application-Layer Problem, Not a Network One","blocks":[{"t":"text","html":"<p>Once you've confirmed the port is open and packets are flowing, but something's still wrong (wrong response, redirect loop, cert issue), drop to the application layer:</p>"},{"t":"code","lang":"bash","code":"curl -v https://example.com"},{"t":"text","html":"<p>Shows the full handshake: DNS resolution, TCP connect, TLS handshake details, request headers sent, response headers received — the layer above what tcpdump shows you, and often exactly where an \"it connects but doesn't work right\" problem actually lives (expired cert, wrong Host header, unexpected redirect).</p>"}]},{"id":"the-full-diagnostic-workflow","title":"The Full Diagnostic Workflow","blocks":[{"t":"text","html":"<p><strong>\"I can't reach <code>service.example.com</code> on port 443\"</strong></p>"},{"t":"code","lang":"bash","code":"1. dig service.example.com                 → does the name even resolve? If not, stop here — it's DNS.\n\n2. ping service.example.com                 → is the host reachable at all? (remember: failure here isn't\n                                                 definitive if ICMP might be blocked — treat as a hint)\n\n3. nc -zv service.example.com 443             → is the SPECIFIC port open? This is often more reliable\n                                                 than ping for a real answer.\n\n4. traceroute / mtr service.example.com        → if unreachable, WHERE does the path actually stop?\n\n5. sudo tcpdump -i eth0 port 443                → (from the server side, if you control it) does the\n                                                 connection attempt even arrive? Does it get a response?\n\n6. curl -v https://service.example.com           → if the port IS open but something's still wrong,\n                                                 check the application-layer exchange"},{"t":"text","html":"<p>Run these roughly in order — each one either confirms that layer is fine (move to the next) or points you straight at the actual problem, without guessing.</p>"}]},{"id":"quick-reference","title":"Quick Reference","blocks":[{"t":"code","lang":"bash","code":"REACHABILITY      ping -c 4 <host>\nPATH/ROUTING       traceroute -n <host>    or    mtr <host>\nDNS                 dig +short <host>       dig @<server> <host>   (isolate resolver vs domain)\nPORT CHECK           nc -zv <host> <port>\nLOCAL LISTENERS       ss -tulnp\nPACKET CAPTURE          sudo tcpdump -i <iface> host <ip> and port <port>\nAPPLICATION LAYER        curl -v https://<host>\n\nFASTEST FIREWALL-VS-ROUTING TEST: tcpdump on the server while connecting from the client —\n  packet arrives + no response = firewall drop.  packet never arrives = routing/upstream problem."}]}]},{"id":"data-engineers","title":"📖 التفريغ الشامل والمفصل: Linux for Data Engineers","icon":"book","category":"overview","preview":"","source":"overview_Linux_for_Data_Engineers.md","words":777,"parts":[{"id":"introduction","title":"Introduction","blocks":[{"t":"text","html":"<p>هذا الدليل هو تفريغ مفصل وشامل لمحتوى فيديو <strong>\"Linux for Data Engineers | البطريق العضاض يعظ\"</strong>، حيث تم استخراج كافة التفاصيل، القصص التاريخية، والنصائح التقنية والفلسفية التي ذكرها المحاضر في الفيديو دون اختصار مخل.</p>"}]},{"id":"1","title":"1️⃣ مقدمة المحاضر وأسباب الدورة","blocks":[{"t":"list","items":["<strong>الشكر والاعتذار:</strong> بدأ المحاضر بشكر المتابعين على رسائل الدعم والتشجيع التي تُعد حافزاً للاستمرار. واعتذر عن فترات الانقطاع الطويلة مبرراً ذلك بضغوط العمل (الرأسمالية) وانتقاله من منزل إلى آخر مؤخراً.","<strong>الهدف من شرح لينكس لمهندسي البيانات:</strong> أشار المحاضر إلى أنه لم يكن يتخيل الحاجة لعمل فيديو مخصص عن \"لينكس\" ضمن مسار هندسة البيانات، لكنه تراجع عن ذلك لعدة أسباب؛ أهمها كثرة الأسئلة والرسائل التي وصلته.","<strong>فك عقدة المبتدئين:</strong> يهدف الشرح إلى الإجابة عن تساؤلات القادمين من خلفيات (Windows أو Mac) مثل: \"لماذا يبدو لينكس بدائياً ومعقداً؟\"، \"لماذا لا توجد واجهات Point-and-Click سهلة ومباشرة؟\"، و\"لماذا يحتاج تنفيذ أمر واحد إلى عشرات الخطوات التحضيرية؟\". الإجابة على هذه الأسئلة تكمن في فهم الخلفية التاريخية لتطور هذا النظام."]}]},{"id":"2","title":"2️⃣ القصة التاريخية: من ألكسندر غراهام بيل إلى نواة لينكس","blocks":[{"t":"text","html":"<h6>أ. جائزة فولتا وتأسيس \"معامل بيل\" (Bell Labs)</h6>"},{"t":"list","items":["في عام <strong>1880</strong>، منحت الحكومة الفرنسية العالم الاسكتلندي <strong>ألكسندر غراهام بيل</strong> (مخترع التليفون) جائزة \"فولتا\" (Volta Prize) والتي كانت قيمتها تعادل تقريباً 100,000 دولار.","بدلاً من إنفاق الأموال على نفسه أو عائلته، سافر بيل إلى أمريكا وأسس معملاً بحثياً ضخماً.","تغير اسم المعمل عدة مرات حتى استقر عام <strong>1925</strong> على اسم <strong>\"Bell Labs\"</strong> تخليداً لذكراه.","<strong>إنجازات المعمل العظيمة:</strong> تركزت أبحاث المعمل على الإلكترونيات، موجات الراديو، اختراع الترانزستور، الليزر، والخلايا الضوئية (حيث صُنع أول Solar Cell حديث في الخمسينيات).","<strong>نظرية المعلومات:</strong> في الأربعينيات، ظهر مجال دراسة جديد في المعمل وهو \"النظرية الرياضية للاتصالات\" (Mathematical Theory of Communication)، والتي أسست لمجال Information Theory (الذي يدرسه طلاب حاسبات ومعلومات).","<strong>الجانب العسكري:</strong> خلال الحرب العالمية الثانية (الثلاثينيات والأربعينيات)، كان للمعمل إنجازات عسكرية مثل تطوير حواسيب ميكانيكية وإلكترونية لحل معادلات المقذوفات الحربية."]},{"t":"text","html":"<h6>ب. الملكية الفكرية وظهور البدائل</h6>"},{"t":"list","items":["واجهت الشركات (مثل AT&amp;T) تحديات في توصيف \"السوفتوير\" لحمايته قانونياً، فاستخدموا قوانين حقوق الملكية الخاصة بالاختراعات. (عقدت AT&amp;T اتفاقية مع الحكومة الفيدرالية الأمريكية في هذا السياق).","في جامعة هولندية (Vrije Universiteit Amsterdam)، قام عالم حاسوب هولندي (أندرو تانينباوم) ببناء نظام تشغيل جديد كلياً مقتبس من (UNIX 7) ومبني عليه ليُستخدم في الأغراض التعليمية."]},{"t":"text","html":"<h6>ج. نواة لينكس (Linux Kernel)</h6>"},{"t":"list","items":["ظهر لاحقاً <strong>لينوس تورفالدس</strong> (Linus Torvalds) الذي قام ببرمجة نواة نظام التشغيل (Kernel).","<strong>دور النواة (Kernel):</strong> هي الجزء البرمجي الذي يتحدث مباشرة مع عتاد الجهاز (Hardware) مثل المعالج (CPU)، الذاكرة العشوائية (RAM)، أقراص التخزين (Disk)، وبطاقات الشبكة (Network).","أصبح هذا الجزء مفتوح المصدر (Open Source) ليتمكن الجميع من استخدامه."]}]},{"id":"3-red-hat","title":"3️⃣ البرمجيات المفتوحة مقابل التجارية (Red Hat كمثال)","blocks":[{"t":"list","items":["يشرح المحاضر كيف يمكن لشركات مثل <strong>Red Hat</strong> أن تربح من نظام مفتوح المصدر ومجاني بالكامل.","تقوم هذه الشركات بتطوير ميزات تجارية إضافية موجهة للمؤسسات الكبرى (Enterprise-grade features).","من أمثلة هذه الإضافات: توفير طبقات حماية أمنية إضافية للشبكات (Security Layers)، تقديم دعم فني مستمر (Support)، وتوفير تحديثات دورية (Updates).","بالتالي، العميل يدفع المال لشراء \"هذا السوفتوير الإضافي وخدمات الدعم\"، وليس لشراء نظام لينكس نفسه."]}]},{"id":"4-terminal","title":"4️⃣ التعامل مع واجهة سطر الأوامر (Terminal)","blocks":[{"t":"list","items":["<strong>إعدادات الواجهة (Profiles):</strong> عند تخصيص واجهة سطر الأوامر (Terminal) - مثل تغيير حجم الخط - فإن فتح نافذة جديدة (New Tab) سيقوم باستدعاء \"الإعدادات الافتراضية\" (Default Profile) ولن يحتفظ بتعديلاتك. ولحل ذلك، يجب حفظ إعداداتك المفضلة كـ Profile جديد لتطبيقها دائماً.","<strong>إظهار الملفات المخفية:</strong> في نظام لينكس، الملفات والمجلدات المخفية (Hidden Files/Directories) هي التي يبدأ اسمها بنقطة (<code>.</code>).","لرؤية هذه الملفات، يتم استخدام الأمر <code>ls</code> مضافاً إليه الخيار <code>-a</code> (أو <code>--a</code>)، والذي يقوم بتغيير مخرجات الأمر ليعرض كافة الملفات بما فيها المخفية، تماماً كما في نظام ويندوز."]}]},{"id":"5","title":"5️⃣ الخاتمة: فلسفة التعلم والمشاركة (نصائح ذهبية)","blocks":[{"t":"text","html":"<p>ختم المحاضر الفيديو برسالة تحفيزية عميقة للمتعلمين:</p>"},{"t":"list","items":["<strong>شارك ما تتعلمه:</strong> لا تتوقف عند معرفة المعلومة وتطبيقها، بل يجب عليك كتابتها ومشاركتها مع الآخرين (عبر مدونة Blog، أو فيديو Vlog، أو حتى على TikTok و YouTube).","<strong>فخ المثالية (Perfectionism):</strong> حذر المحاضر من انتظار الكمال قبل النشر. لا يوجد إنسان يعرف كل شيء، وحتى لو أخطأت في الشرح، يمكنك التصحيح لاحقاً والاعتراف بالخطأ.","<strong>ابدأ صغيراً:</strong> شارك أي معلومة مهما كانت بسيطة (ولو كان أمراً برمجياً واحداً، أو ميزة واحدة في منتج). لا تنتظر أشهراً لتخرج بمشروع ضخم.","<strong>فائدة المشاركة:</strong> عندما تشارك معلوماتك، ستُضطر للمذاكرة وتطوير نفسك، وستتعرض لأسئلة ونقد بنّاء يفتح عينيك على جوانب لم تكن تدركها، مما يجعلك أقوى وأفضل في مجالك.","<strong>تراكمية العلم:</strong> العلم البشري بجميع مجالاته (طب، هندسة، فيزياء، الخ) بُني على التراكم. كل عالم يبدأ من حيث انتهى السابقون، وهذا لا يتحقق إلا بـ \"المشاركة\".","<strong>لا تحتقر عملك:</strong> تيقن أنه مهما كانت المعلومة التي تشاركها بسيطة، فهناك شخص آخر لا يعرفها وسيستفيد منها ويبني عليها."]},{"t":"text","html":"<h6>💡 مفهوم \"الأوبونتو\" (Ubuntu)</h6>"},{"t":"text","html":"<p>اُختتم التفريغ باقتباس للزعيم نيلسون مانديلا يشرح فيه الفلسفة الأفريقية <strong>\"أوبونتو\" (Ubuntu)</strong>:</p>"},{"t":"list","items":["في الماضي، كان المسافر إذا مر بقرية ولم يطلب طعاماً أو ماءً، فإن أهل القرية يقدمون له الطعام تلقائياً.","\"أوبونتو\" لا تعني ألا يُثري الإنسان نفسه، بل السؤال هو: <strong>هل ستقوم بإثراء نفسك من أجل تمكين المجتمع من حولك للارتقاء والتحسن؟</strong> هذه هي الأشياء المهمة في الحياة، والتي ستكون دائماً موضع تقدير."]}]}]},{"id":"process-monitoring","title":"Process & Performance Monitoring — Diagnosing Slow or Crashing Services","icon":"activity","category":"monitoring","preview":"","source":"process-performance-monitoring.md","words":1844,"parts":[{"id":"introduction","title":"Introduction","blocks":[{"t":"text","html":"<p>The toolkit for answering two questions that come up constantly: <strong>\"why is this slow?\"</strong> and <strong>\"why did this crash?\"</strong> — each tool below answers a different slice of that, and the real skill is knowing which one to reach for first.</p>"}]},{"id":"the-mental-model","title":"The Mental Model","blocks":[{"t":"table","head":["Symptom","Tool to reach for first"],"rows":[["System feels sluggish overall","<code>top</code> / <code>htop</code> — get the big picture fast"],["Suspect memory pressure/swapping","<code>vmstat</code>"],["Suspect disk is the bottleneck","<code>iostat</code>"],["Need to see exactly what a process is doing right now","<code>strace</code>"],["Service crashed or won't start","<code>journalctl -u &lt;service&gt;</code>"]]},{"t":"text","html":"<p>They're not competing tools — a real investigation usually chains 2–3 of these together.</p>"}]},{"id":"top-the-universal-starting-point","title":"`top` — The Universal Starting Point","blocks":[{"t":"code","lang":"bash","code":"top"},{"t":"text","html":"<h6>Reading the header (first 5 lines)</h6>"},{"t":"code","lang":"bash","code":"top - 14:32:01 up 3 days,  4:12,  2 users,  load average: 1.85, 2.10, 1.95\nTasks: 210 total,   2 running, 208 sleeping,   0 stopped,   0 zombie\n%Cpu(s): 12.3 us,  3.1 sy,  0.0 ni, 83.9 id,  0.5 wa,  0.0 hi,  0.2 si,  0.0 st\nMiB Mem :  15872 total,   2103 free,   9821 used,   3948 buff/cache\nMiB Swap:   2048 total,   1200 free,    848 used.   4501 avail Mem"},{"t":"text","html":"<p><strong>Load average</strong> (<code>1.85, 2.10, 1.95</code>) — the 1/5/15-minute average of how many processes were runnable (running or waiting for CPU). <strong>This number is meaningless without knowing your core count.</strong> Check cores with <code>nproc</code>. A load of <code>4.0</code> is fine on an 8-core machine (half-utilized) and a serious problem on a 2-core machine (2x oversubscribed).</p>"},{"t":"callout","kind":"tip","html":"<strong><code>%Cpu(s)</code> breakdown:</strong> "},{"t":"table","head":["Field","Meaning"],"rows":[["<code>us</code>","user-space CPU time (your applications)"],["<code>sy</code>","kernel/system CPU time"],["<code>id</code>","idle"],["<code>wa</code>","<strong>iowait</strong> — CPU sitting idle waiting on disk I/O. High <code>wa</code> = disk is the bottleneck, not CPU"],["<code>si</code>/<code>hi</code>","soft/hard interrupt handling"],["<code>st</code>","stolen time — a VM waiting on its hypervisor (relevant on cloud instances)"]]},{"t":"text","html":"<h6>Reading the process table columns</h6>"},{"t":"table","head":["Column","Meaning"],"rows":[["<code>PID</code>","process ID"],["<code>USER</code>","owning user"],["<code>PR</code> / <code>NI</code>","priority / niceness (lower NI = higher priority, range -20 to 19)"],["<code>VIRT</code>","total virtual memory the process has mapped (often much larger than actual usage — not a red flag by itself)"],["<code>RES</code>","resident memory — actual physical RAM in use, the number that usually matters"],["<code>S</code>","state: <code>R</code> running, <code>S</code> sleeping, <code>D</code> uninterruptible sleep (usually waiting on I/O — worth noting), <code>Z</code> zombie"],["<code>%CPU</code> / <code>%MEM</code>","current usage share"],["<code>TIME+</code>","total accumulated CPU time since the process started"]]},{"t":"text","html":"<h6>Interactive commands (press while `top` is running)</h6>"},{"t":"table","head":["Key","Effect"],"rows":[["<code>P</code>","sort by %CPU (default)"],["<code>M</code>","sort by %MEM"],["<code>T</code>","sort by running time"],["<code>k</code>","kill a process (prompts for PID, then signal)"],["<code>r</code>","renice a process (change its priority)"],["<code>1</code>","toggle per-core CPU breakdown instead of the aggregate"],["<code>c</code>","toggle showing the full command path/args"],["<code>q</code>","quit"]]},{"t":"callout","kind":"tip","html":"<strong><code>D</code> state is worth specifically knowing:</strong> a process stuck in <code>D</code> (uninterruptible sleep) can't even be killed with <code>-9</code> until whatever I/O it's blocked on resolves — a strong signal of a disk or NFS problem, not an application bug."}]},{"id":"htop-same-data-much-easier-to-read","title":"`htop` — Same Data, Much Easier to Read","blocks":[{"t":"code","lang":"bash","code":"sudo apt install htop -y\nhtop"},{"t":"callout","kind":"tip","html":"<strong>What htop adds over top:</strong> "},{"t":"list","items":["Color-coded, per-core CPU and memory meters at the top — no mental math needed","<strong>Tree view</strong> (<code>F5</code>) — shows parent/child process relationships visually, immediately clarifies \"what spawned what\"","<strong>Search</strong> (<code>F3</code>) and <strong>filter</strong> (<code>F4</code>) by process name","Mouse support — click a process, click a column header to sort","<code>F9</code> to kill (lets you pick the signal from a menu, not just guess <code>-9</code>)","<code>F2</code> for setup — customize which columns/meters are shown"]},{"t":"callout","kind":"tip","html":"<strong>Practical habit:</strong> use <code>F5</code> (tree view) whenever you suspect a runaway process is spawning children — it's far faster to spot in the tree than by scanning a flat PID list."}]},{"id":"vmstat-memory-swap-cpu-in-one-glance","title":"`vmstat` — Memory, Swap & CPU in One Glance","blocks":[{"t":"code","lang":"bash","code":"vmstat 1 5      # sample every 1 second, 5 times total"},{"t":"code","lang":"bash","code":"procs -----------memory---------- ---swap-- -----io---- -system-- ------cpu-----\n r  b   swpd   free   buff  cache   si   so    bi    bo   in   cs us sy id wa st\n 2  0  86000 210400  98200 3800000    0    0    45   120  850  1200 12  3 84  1  0"},{"t":"table","head":["Column","Meaning"],"rows":[["<code>r</code>","processes waiting for CPU time right now — sustained high values mean CPU is genuinely the bottleneck"],["<code>b</code>","processes blocked, waiting on I/O"],["<code>swpd</code>","amount of memory swapped to disk"],["<code>free</code>","free memory"],["<code>buff</code> / <code>cache</code>","memory used for buffers/page cache — this is <strong>not</strong> wasted memory, the kernel reclaims it instantly when needed"],["<code>si</code> / <code>so</code>","swap in / swap out (per second) — <strong>any sustained non-zero value here is a real problem</strong>, it means the system is actively thrashing to disk"],["<code>bi</code> / <code>bo</code>","blocks in / out from block devices — raw disk I/O activity"],["<code>in</code>","interrupts per second"],["<code>cs</code>","context switches per second — very high values can indicate excessive process/thread switching overhead"],["<code>us/sy/id/wa/st</code>","same meaning as top's CPU breakdown"]]},{"t":"callout","kind":"tip","html":"<strong>Diagnostic pattern to remember:</strong> <code>si</code>/<code>so</code> staying above zero across multiple samples = the system doesn't have enough RAM for its workload and is actively swapping — this alone can explain \"everything feels slow\" better than any CPU metric will."}]},{"id":"iostat-disk-i-o-specifically","title":"`iostat` — Disk I/O Specifically","blocks":[{"t":"code","lang":"bash","code":"sudo apt install sysstat -y     # provides iostat\niostat -x 1 5                     # extended stats, every 1 second, 5 times"},{"t":"code","lang":"bash","code":"Device    r/s   w/s   rkB/s   wkB/s  avgqu-sz  await  %util\nsda       2.00  45.00  128.00  5400.00     0.85   12.30   38.5"},{"t":"table","head":["Column","Meaning"],"rows":[["<code>r/s</code> / <code>w/s</code>","reads/writes per second"],["<code>rkB/s</code> / <code>wkB/s</code>","throughput"],["<code>avgqu-sz</code>","average queue length — I/O requests waiting their turn. Consistently above ~1 means the disk can't keep up with demand"],["<code>await</code>","average time (ms) an I/O request waits, including queue time — the number that best reflects what an application actually experiences"],["<code>%util</code>","percentage of time the device was busy servicing requests — <strong>not</strong> the same as \"percentage of capacity used\"; a single-queue device can hit 100% util while still having room, but sustained high util alongside rising <code>await</code> is a genuine bottleneck"]]},{"t":"callout","kind":"tip","html":"<strong>Diagnostic pattern:</strong> if <code>top</code>/<code>vmstat</code> shows high <code>wa</code> (iowait), <code>iostat -x</code> is the next stop — it tells you which device and how badly."}]},{"id":"strace-seeing-exactly-what-a-process-is-doing","title":"`strace` — Seeing Exactly What a Process Is Doing","blocks":[{"t":"text","html":"<p><code>strace</code> traces every system call a process makes — the actual requests it sends to the kernel (open a file, read, write, connect a socket, etc). This is the tool for \"why is this hanging\" or \"why is this failing\" when the application's own error message isn't enough.</p>"},{"t":"code","lang":"bash","code":"sudo apt install strace -y"},{"t":"text","html":"<h6>Attach to an already-running process</h6>"},{"t":"code","lang":"bash","code":"sudo strace -p <PID>"},{"t":"text","html":"<p>Watch what it's doing live — if it's stuck, the <strong>last line printed</strong> is almost always the syscall it's blocked on (commonly <code>read()</code>, <code>connect()</code>, or <code>futex()</code> for a lock).</p>"},{"t":"text","html":"<h6>Trace a command from the start</h6>"},{"t":"code","lang":"bash","code":"strace ./myprogram\nstrace -f ./myprogram       # -f follows child processes too — essential for multi-process programs"},{"t":"text","html":"<h6>Filter to a specific category of syscalls</h6>"},{"t":"code","lang":"bash","code":"strace -e trace=network ./myprogram      # only network-related syscalls (connect, send, recv...)\nstrace -e trace=file ./myprogram           # only file-related syscalls (open, read, write, close...)\nstrace -e trace=open,openat ./myprogram      # just file-open attempts — great for \"why can't it find this file\""},{"t":"text","html":"<h6>Summary mode — which syscalls are eating the most time</h6>"},{"t":"code","lang":"bash","code":"strace -c ./myprogram"},{"t":"code","lang":"bash","code":"% time     seconds  usecs/call     calls    syscall\n------ ----------- ----------- --------- ----------------\n 62.15    0.004821         120        40 read\n 21.30    0.001652          82        20 write"},{"t":"text","html":"<p>This immediately tells you whether a slow program is spending its time on file I/O, network calls, or something else entirely — without guessing.</p>"},{"t":"text","html":"<h6>The single most common real-world use</h6>"},{"t":"code","lang":"bash","code":"sudo strace -f -e trace=open,openat -p <PID> 2>&1 | grep ENOENT"},{"t":"text","html":"<p>Catches \"file not found\" errors live — invaluable for chasing down a service that's failing because it can't find a config file or dependency, when the application's own error message is too vague to say which file.</p>"},{"t":"callout","kind":"tip","html":"<strong>Note:</strong> attaching <code>strace</code> to a live process does add real overhead — it can noticeably slow the process down. Fine for debugging, not something to leave running on a production service under load."}]},{"id":"journalctl-actually-diagnosing-a-service","title":"`journalctl` — Actually Diagnosing a Service","blocks":[{"t":"text","html":"<p>Every systemd-managed service's output goes into the journal — this is where you go once <code>top</code>/<code>vmstat</code>/<code>iostat</code> have told you something's wrong and you need to know specifically what a service is doing.</p>"},{"t":"text","html":"<h6>The essentials</h6>"},{"t":"code","lang":"bash","code":"journalctl -u nginx                 # all logs for the nginx service, oldest first\njournalctl -u nginx -f                # live tail, like tail -f\njournalctl -u nginx --since \"10 min ago\"\njournalctl -u nginx --since \"2026-08-20 09:00\" --until \"2026-08-20 10:00\"\njournalctl -u nginx -n 50              # just the last 50 lines\njournalctl -u nginx -r                  # reverse order, newest first — good for \"what just happened\""},{"t":"text","html":"<h6>Filtering by severity</h6>"},{"t":"code","lang":"bash","code":"journalctl -u nginx -p err              # only error-level and worse\njournalctl -u nginx -p warning          # warning and worse"},{"t":"text","html":"<p>Priority levels, worst to least severe: <code>emerg</code>, <code>alert</code>, <code>crit</code>, <code>err</code>, <code>warning</code>, <code>notice</code>, <code>info</code>, <code>debug</code>.</p>"},{"t":"text","html":"<h6>System-wide, not just one service</h6>"},{"t":"code","lang":"bash","code":"journalctl -b                # everything since the current boot\njournalctl -b -1               # everything from the PREVIOUS boot — crucial after an unexpected reboot/crash\njournalctl -k                 # kernel messages only (equivalent to dmesg, but persistent and filterable)\njournalctl -x                  # adds extra explanatory context to messages that support it"},{"t":"text","html":"<h6>Diagnosing a crashed service — the actual workflow</h6>"},{"t":"callout","kind":"tip","html":"<strong>Step 1 — Check current status first, it often tells you the exit code directly:</strong> "},{"t":"code","lang":"bash","code":"systemctl status nginx"},{"t":"code","lang":"bash","code":"Active: failed (Result: exit-code) since ...\nProcess: 1234 ExecStart=/usr/sbin/nginx (code=exited, status=1/FAILURE)"},{"t":"callout","kind":"tip","html":"<strong>Step 2 — Pull the logs right around the crash:</strong> "},{"t":"code","lang":"bash","code":"journalctl -u nginx --since \"5 min ago\" -r"},{"t":"callout","kind":"tip","html":"<strong>Step 3 — Check if the kernel killed it (Out-Of-Memory killer is a very common silent cause):</strong> "},{"t":"code","lang":"bash","code":"journalctl -k | grep -i \"killed process\"\n# or\ndmesg | grep -i oom"},{"t":"text","html":"<p>An OOM kill often shows up as the service just \"disappearing\" with no application-level error at all — the kernel terminated it to save the system, and the only trace is in the kernel log, not the service's own log.</p>"},{"t":"callout","kind":"tip","html":"<strong>Step 4 — If it's a crash loop (keeps restarting), check the restart history:</strong> "},{"t":"code","lang":"bash","code":"systemctl status nginx     # look at \"Main PID\" changing between checks, and restart count\njournalctl -u nginx | grep -i \"start\\|stop\\|fail\""},{"t":"callout","kind":"tip","html":"<strong>Step 5 — If logs alone aren't enough, reproduce it under strace:</strong> "},{"t":"code","lang":"bash","code":"sudo strace -f -o trace.log /usr/sbin/nginx -g \"daemon off;\""},{"t":"text","html":"<p>Running the service in the foreground under <code>strace</code> (instead of through systemd) captures the exact syscall it dies on — the highest-resolution view available short of attaching a debugger.</p>"}]},{"id":"putting-it-together-two-common-investigations","title":"Putting It Together — Two Common Investigations","blocks":[{"t":"text","html":"<h6>\"The server feels slow\"</h6>"},{"t":"code","lang":"bash","code":"1. top / htop           → is it CPU-bound, memory-bound, or mostly idle-but-slow?\n2. vmstat 1 5             → check `wa` (iowait) and `si`/`so` (swapping)\n3. iostat -x 1 5            → if wa is high, confirm which device and how saturated\n4. strace -c -p <PID>        → if one process is the culprit, see what it's actually spending time on"},{"t":"text","html":"<h6>\"A service crashed or won't start\"</h6>"},{"t":"code","lang":"bash","code":"1. systemctl status <service>          → immediate exit code / failure reason\n2. journalctl -u <service> --since ... → logs right before the failure\n3. journalctl -k | grep -i killed        → rule out OOM kill\n4. strace -f <the command it runs>         → if still unclear, watch it fail live"}]},{"id":"quick-reference","title":"Quick Reference","blocks":[{"t":"code","lang":"bash","code":"BIG PICTURE    top   /   htop\nMEMORY/SWAP    vmstat 1 5        → watch si/so and wa\nDISK I/O       iostat -x 1 5      → watch await and %util\nSYSCALL TRACE  strace -p <PID>   or   strace -f -c <command>\nSERVICE LOGS   journalctl -u <service> -f\nCRASH HISTORY  journalctl -u <service> --since \"10 min ago\" -r\nOOM CHECK      journalctl -k | grep -i \"killed process\""}]}]},{"id":"ssh-guide","title":"SSH Remote Access From Outside Your Network — Complete Guide","icon":"terminal","category":"networking","preview":"","source":"ssh-remote-access-guide.md","words":1705,"parts":[{"id":"introduction","title":"Introduction","blocks":[{"t":"text","html":"<p>How to reach a Linux machine over SSH from anywhere on the internet, not just your local network — plus the hardening steps that matter once that machine is actually exposed.</p>"}]},{"id":"two-ways-to-do-this","title":"Two Ways to Do This","blocks":[{"t":"table","head":["Approach","How it works","Best for"],"rows":[["<strong>Port forwarding</strong>","Open a port on your router, forward it to the machine's local IP","Full control, no third party, but exposes your home IP directly to the internet"],["<strong>Tunneling service</strong> (Tailscale, Cloudflare Tunnel, reverse SSH via VPS)","No port forwarding at all — an outbound connection from your machine creates the path in","Far safer, easier, works behind CGNAT/no router access — <strong>recommended for most personal setups</strong>"]]},{"t":"text","html":"<p>This guide covers the direct port-forwarding method in full (since that's what you asked for), then the safer alternative at the end — genuinely worth reading before you commit to opening a port.</p>"}]},{"id":"install-enable-the-ssh-server","title":"Install & Enable the SSH Server","blocks":[{"t":"text","html":"<p>On the machine you want to connect into (the \"server\"):</p>"},{"t":"code","lang":"bash","code":"sudo apt update\nsudo apt install openssh-server -y\nsudo systemctl enable ssh --now     # start now, and on every boot\nsudo systemctl status ssh            # confirm it's active (running)"}]},{"id":"find-your-ips","title":"Find Your IPs","blocks":[{"t":"text","html":"<p>You need two different IPs — don't confuse them.</p>"},{"t":"text","html":"<p><strong>Local (internal) IP</strong> — how devices on your own network see this machine:</p>"},{"t":"code","lang":"bash","code":"ip a                 # look under your active interface (eth0/wlan0), the inet line\nhostname -I           # quicker, just prints the IP(s)"},{"t":"text","html":"<p><strong>Public IP</strong> — how the internet sees your entire network (this is what you'll actually connect to from outside):</p>"},{"t":"code","lang":"bash","code":"curl ifconfig.me\n# or open https://whatismyip.com in a browser"},{"t":"text","html":"<p><strong>Give the server machine a fixed local IP.</strong> If it's on DHCP, its local IP can change after a reboot, breaking your port forward. Either:</p>"},{"t":"list","items":["Set a <strong>static IP</strong> on the machine itself, or","Set a <strong>DHCP reservation</strong> in your router (binds a specific local IP to this machine's MAC address permanently) — this is the cleaner option since the machine's config stays untouched."]}]},{"id":"forward-the-port-on-your-router","title":"Forward the Port on Your Router","blocks":[{"t":"list","items":["Log into your router's admin panel — usually <code>192.168.1.1</code> or <code>192.168.0.1</code> in a browser (check the router's label, or run <code>ip route | grep default</code> to find your gateway IP).","Find <strong>Port Forwarding</strong> (sometimes under \"NAT,\" \"Virtual Server,\" or \"Firewall\").","Create a rule:","<strong>External port</strong>: e.g. <code>2222</code> (see the security note below on why not <code>22</code>)","<strong>Internal port</strong>: <code>22</code>","<strong>Internal IP</strong>: the server's local IP from Step 2","<strong>Protocol</strong>: TCP","Save and apply — most routers apply this instantly, some need a reboot."]}]},{"id":"open-the-port-on-the-server-s-own-firewall","title":"Open the Port on the Server's Own Firewall","blocks":[{"t":"text","html":"<p>Port forwarding at the router is useless if the machine's local firewall still blocks the connection.</p>"},{"t":"code","lang":"bash","code":"sudo ufw allow 22/tcp        # or your custom port, e.g. sudo ufw allow 2222/tcp\nsudo ufw enable\nsudo ufw status"}]},{"id":"connect-from-outside","title":"Connect From Outside","blocks":[{"t":"text","html":"<p>From another network entirely (mobile data is a good real test — your own network won't prove it works from outside):</p>"},{"t":"code","lang":"bash","code":"ssh -p 2222 solo@<your_public_ip>"},{"t":"text","html":"<p>If you forwarded external <code>2222</code> → internal <code>22</code>, you must specify <code>-p 2222</code> on the client side — the external and internal ports don't have to match, and here they intentionally don't.</p>"}]},{"id":"connecting-as-root-vs-as-a-regular-user-two-ways","title":"Connecting as Root vs. as a Regular User — Two Ways In","blocks":[{"t":"text","html":"<p>Once your port forward and firewall are set up, who you log in as matters a lot for security. Here's both approaches, step by step.</p>"},{"t":"text","html":"<h6>6.1 Method 1 — Connect as a Regular User, Then Elevate (Recommended)</h6>"},{"t":"text","html":"<p>This is the standard, safe pattern: SSH in as an unprivileged user, then become root only for the specific commands that need it.</p>"},{"t":"callout","kind":"tip","html":"<strong>Step 1 — SSH in as your normal user:</strong> "},{"t":"code","lang":"bash","code":"ssh -p 2222 solo@<public_ip_or_ddns_hostname>"},{"t":"callout","kind":"tip","html":"<strong>Step 2 — Confirm who you are once connected:</strong> "},{"t":"code","lang":"bash","code":"whoami    # prints your regular username, e.g. \"solo\""},{"t":"callout","kind":"tip","html":"<strong>Step 3 — Run an individual admin command with <code>sudo</code>:</strong> "},{"t":"code","lang":"bash","code":"sudo apt update"},{"t":"text","html":"<p>You're prompted for <strong>your own</strong> password (the account you SSH'd in as), not root's.</p>"},{"t":"callout","kind":"tip","html":"<strong>Step 4 — If you need several root commands in a row, get a full root shell:</strong> "},{"t":"code","lang":"bash","code":"sudo -i\nwhoami    # now prints \"root\""},{"t":"callout","kind":"tip","html":"<strong>Step 5 — Exit root, then exit the SSH session entirely when done:</strong> "},{"t":"code","lang":"bash","code":"exit      # drops out of the root shell, back to your normal user\nexit      # closes the SSH connection"},{"t":"text","html":"<h6>6.2 Method 2 — Connect Directly as Root</h6>"},{"t":"text","html":"<p>Technically possible, but disabled by default on most distros, and actively discouraged for anything internet-facing — every login attempt against a machine's SSH port is now guessing the known username \"root\" instead of also having to guess a username. Shown here for completeness and for local/lab use.</p>"},{"t":"text","html":"<p><strong>Step 1 — Give root a password</strong> (it has none set by default on Ubuntu/Debian):</p>"},{"t":"code","lang":"bash","code":"sudo passwd root"},{"t":"text","html":"<p><strong>Step 2 — Temporarily allow root login over SSH</strong> — edit <code>/etc/ssh/sshd_config</code> on the server:</p>"},{"t":"code","lang":"bash","code":"PermitRootLogin yes"},{"t":"callout","kind":"tip","html":"<strong>Step 3 — Restart the SSH service to apply it:</strong> "},{"t":"code","lang":"bash","code":"sudo systemctl restart ssh"},{"t":"callout","kind":"tip","html":"<strong>Step 4 — Connect directly as root from the client:</strong> "},{"t":"code","lang":"bash","code":"ssh -p 2222 root@<public_ip_or_ddns_hostname>"},{"t":"text","html":"<p><strong>Step 5 — Revert it once you're done</strong> (this is the important part — don't leave this open):</p>"},{"t":"code","lang":"bash","code":"# back to /etc/ssh/sshd_config\nPermitRootLogin no"},{"t":"code","lang":"bash","code":"sudo systemctl restart ssh"},{"t":"text","html":"<h6>6.3 Which One Should You Actually Use?</h6>"},{"t":"table","head":["Situation","Use"],"rows":[["Any machine reachable from the internet (your port-forwarded setup)","<strong>Method 1</strong> — <code>PermitRootLogin no</code>, connect as a regular user, <code>sudo</code> when needed"],["Local-only lab machine, never exposed outside your LAN","Either is fine, Method 1 is still better practice"],["You just need to run one root-level command remotely","<code>ssh -p 2222 solo@host \"sudo &lt;command&gt;\"</code> — skips a full interactive login entirely"]]},{"t":"callout","kind":"tip","html":"<strong>Bottom line:</strong> treat direct root login the same way you'd treat leaving your front door key under the mat — it works, but it's the first thing anyone probing your server will try. Method 1 with <code>sudo</code> gives you the exact same power with a username an attacker actually has to guess first, plus a clean audit trail of every elevated command in <code>/var/log/auth.log</code>."}]},{"id":"your-public-ip-keeps-changing-fix-it-with-dynami","title":"Your Public IP Keeps Changing — Fix It With Dynamic DNS","blocks":[{"t":"text","html":"<p>Most home internet connections have a <strong>dynamic</strong> public IP — it changes periodically, breaking anything hardcoded to today's address. Dynamic DNS (DDNS) gives you a stable hostname that always points at your current IP.</p>"},{"t":"callout","kind":"tip","html":"<strong>Free options:</strong> DuckDNS, No-IP, Cloudflare (if you own a domain)."},{"t":"callout","kind":"tip","html":"<strong>DuckDNS example:</strong> "},{"t":"list","items":["Create a free subdomain at duckdns.org, e.g. <code>solo-home.duckdns.org</code>.","Install their update script (cron job or systemd timer) on the server — it pings DuckDNS every few minutes with your current IP.","From then on, connect with the hostname instead of a raw IP:"]},{"t":"code","lang":"bash","code":"ssh -p 2222 solo@solo-home.duckdns.org"}]},{"id":"security-hardening-don-t-skip-this","title":"Security Hardening — Don't Skip This","blocks":[{"t":"text","html":"<p>The moment you forward SSH to the internet, automated bots <strong>will</strong> find and hammer it within hours — this isn't hypothetical, it's guaranteed. These steps aren't optional polish, they're the difference between \"exposed but safe\" and \"compromised.\"</p>"},{"t":"text","html":"<h6>Switch to key-based authentication, then disable passwords entirely</h6>"},{"t":"code","lang":"bash","code":"# on your CLIENT machine (not the server):\nssh-keygen -t ed25519\nssh-copy-id -p 2222 solo@<server_ip>     # copies your public key to the server"},{"t":"text","html":"<p>Then on the <strong>server</strong>, edit <code>/etc/ssh/sshd_config</code>:</p>"},{"t":"code","lang":"bash","code":"PasswordAuthentication no\nPubkeyAuthentication yes"},{"t":"code","lang":"bash","code":"sudo systemctl restart ssh"},{"t":"text","html":"<p>This alone eliminates the entire brute-force-password attack surface — a key can't be guessed the way a password can.</p>"},{"t":"text","html":"<h6>Disable root login</h6>"},{"t":"code","lang":"bash","code":"# /etc/ssh/sshd_config\nPermitRootLogin no"},{"t":"text","html":"<h6>Change the default port</h6>"},{"t":"text","html":"<p>Set <code>Port 2222</code> (or any non-standard number) in <code>/etc/ssh/sshd_config</code>. This doesn't add real cryptographic security, but it silences the vast majority of dumb automated scanners that only ever check port 22 — your logs get dramatically quieter and easier to actually monitor.</p>"},{"t":"text","html":"<h6>Restrict which users can SSH in at all</h6>"},{"t":"code","lang":"bash","code":"# /etc/ssh/sshd_config\nAllowUsers solo"},{"t":"text","html":"<h6>Install fail2ban</h6>"},{"t":"text","html":"<p>Automatically bans IPs that fail login too many times:</p>"},{"t":"code","lang":"bash","code":"sudo apt install fail2ban -y\nsudo systemctl enable fail2ban --now"},{"t":"text","html":"<h6>Rate-limit connections at the firewall too</h6>"},{"t":"code","lang":"bash","code":"sudo ufw limit 2222/tcp     # throttles repeated connection attempts from the same IP"},{"t":"text","html":"<h6>Keep the system patched</h6>"},{"t":"code","lang":"bash","code":"sudo apt update && sudo apt upgrade -y     # do this regularly — SSH/OpenSSH CVEs do happen"},{"t":"text","html":"<p><strong>After all of the above</strong>, re-check <code>sudo systemctl restart ssh</code> and re-test your connection before closing your current session — if <code>sshd_config</code> has a typo, you don't want to be locked out with no way back in.</p>"}]},{"id":"the-safer-alternative-skip-port-forwarding-entir","title":"The Safer Alternative: Skip Port Forwarding Entirely","blocks":[{"t":"text","html":"<p>Worth strong consideration, especially for a personal/home setup:</p>"},{"t":"text","html":"<h6>Tailscale (recommended)</h6>"},{"t":"text","html":"<p>Creates a private mesh VPN between your devices — no router config, no open ports, works even behind CGNAT (which port forwarding can't solve at all).</p>"},{"t":"code","lang":"bash","code":"curl -fsSL https://tailscale.com/install.sh | sh\nsudo tailscale up"},{"t":"text","html":"<p>Every device you install it on gets a stable private IP (<code>100.x.x.x</code>) that only your devices can reach — then just <code>ssh solo@&lt;tailscale-ip&gt;</code> from anywhere, with zero exposure to the public internet.</p>"},{"t":"text","html":"<h6>Cloudflare Tunnel</h6>"},{"t":"text","html":"<p>Similar idea — an outbound-only tunnel from your server to Cloudflare, no inbound port ever opened.</p>"},{"t":"text","html":"<h6>Reverse SSH tunnel via a cheap VPS</h6>"},{"t":"text","html":"<p>If you already have a VPS, the server can dial out to it and hold a tunnel open, letting you reach it through the VPS without ever forwarding a port at home:</p>"},{"t":"code","lang":"bash","code":"ssh -R 2222:localhost:22 you@your-vps-ip"},{"t":"callout","kind":"tip","html":"<strong>Why this matters:</strong> port forwarding exposes your home router directly to internet-wide scanning. A mesh VPN like Tailscale gets you the exact same remote-access outcome with essentially none of that exposure — for a personal setup it's very hard to justify skipping it."}]},{"id":"troubleshooting","title":"Troubleshooting","blocks":[{"t":"table","head":["Symptom","Likely cause"],"rows":[["<code>Connection timed out</code>","Port forward isn't actually applied, or your ISP uses CGNAT (your \"public\" IP isn't really public — common on mobile/some ISPs)"],["<code>Connection refused</code>","SSH service isn't running, or local firewall (<code>ufw</code>) is blocking the port"],["Works on local network, fails from outside","Router port-forward rule is wrong, or pointing at the wrong internal IP"],["Prompted for password even after key setup","<code>PasswordAuthentication</code> wasn't actually set to <code>no</code>, or the public key wasn't copied to the right user's <code>~/.ssh/authorized_keys</code>"],["Locked out after editing <code>sshd_config</code>","Keep your current session open while testing a second connection in a new terminal — never close your only working session until the new config is confirmed working"]]},{"t":"text","html":"<p>Check live logs while debugging:</p>"},{"t":"code","lang":"bash","code":"sudo journalctl -u ssh -f"}]},{"id":"quick-setup-checklist","title":"Quick Setup Checklist","blocks":[{"t":"list","items":["[ ] <code>openssh-server</code> installed and running","[ ] Static local IP or DHCP reservation on the server","[ ] Router port forward: external port → server's local IP:22","[ ] <code>ufw allow &lt;port&gt;/tcp</code> on the server itself","[ ] Tested from an actual outside network (mobile data)","[ ] Dynamic DNS set up if your public IP isn't static","[ ] SSH key auth working, then <code>PasswordAuthentication no</code>","[ ] <code>PermitRootLogin no</code>","[ ] Non-default port set","[ ] <code>fail2ban</code> installed and running","[ ] Considered Tailscale instead of all of the above"]}]}]},{"id":"vim-nano","title":"Vim / Vi & Nano — The Complete Guide","icon":"edit","category":"editing","preview":"","source":"vim-nano-complete-guide.md","words":2151,"parts":[{"id":"the-core-idea-modal-editing","title":"The Core Idea: Modal Editing","blocks":[{"t":"text","html":"<p>Vim is not like other editors — it has <strong>modes</strong>, and the same key does completely different things depending on which mode you're in. This is the single most important concept to internalize before anything else makes sense.</p>"},{"t":"table","head":["Mode","Purpose","How to enter"],"rows":[["<strong>Normal</strong>","Navigate, delete, copy, run commands (default mode)","<code>Esc</code> from any other mode"],["<strong>Insert</strong>","Type text like a normal editor","<code>i</code>, <code>a</code>, <code>o</code>, etc. from Normal"],["<strong>Visual</strong>","Select text (char/line/block)","<code>v</code>, <code>V</code>, <code>Ctrl+v</code> from Normal"],["<strong>Command-line</strong>","Run <code>:</code> commands (save, quit, search/replace)","<code>:</code> from Normal"],["<strong>Replace</strong>","Overtype existing text","<code>R</code> from Normal"]]},{"t":"callout","kind":"tip","html":"<strong>Golden rule:</strong> <code>Esc</code> always brings you back to Normal mode. When lost, hit <code>Esc</code>."}]},{"id":"starting-exiting","title":"Starting & Exiting","blocks":[{"t":"code","lang":"bash","code":"vim file.txt          # open (or create) a file\nvim +42 file.txt       # open at line 42\nvim +/pattern file.txt # open and jump to first match of pattern\nvimdiff file1 file2    # open two files side-by-side, highlighting differences"},{"t":"callout","kind":"tip","html":"<strong>Exiting (all typed in Normal mode, starting with <code>:</code>):</strong> "},{"t":"table","head":["Command","Effect"],"rows":[["<code>:w</code>","Save (write)"],["<code>:w newname.txt</code>","Save as a new file"],["<code>:q</code>","Quit (fails if unsaved changes)"],["<code>:q!</code>","Quit, discard changes"],["<code>:wq</code> or <code>:x</code>","Save and quit"],["<code>ZZ</code>","Save and quit (Normal mode shortcut, no <code>:</code>)"],["<code>ZQ</code>","Quit without saving"],["<code>:wqa</code>","Save and quit all open buffers/windows"]]}]},{"id":"normal-mode-navigation","title":"Normal Mode — Navigation","blocks":[{"t":"text","html":"<h6>Basic movement</h6>"},{"t":"table","head":["Key","Moves"],"rows":[["<code>h</code> <code>j</code> <code>k</code> <code>l</code>","left / down / up / right"],["<code>0</code>","start of line (column 0, ignores indentation)"],["<code>^</code>","first non-blank character of line"],["<code>$</code>","end of line"],["<code>gg</code>","first line of file"],["<code>G</code>","last line of file"],["<code>42G</code> or <code>:42</code>","go to line 42"]]},{"t":"text","html":"<h6>Word-wise movement</h6>"},{"t":"table","head":["Key","Moves"],"rows":[["<code>w</code>","start of next word"],["<code>W</code>","start of next WORD (whitespace-delimited, ignores punctuation splits)"],["<code>b</code>","back to start of previous word"],["<code>B</code>","back to start of previous WORD"],["<code>e</code>","end of current/next word"],["<code>E</code>","end of current/next WORD"]]},{"t":"text","html":"<h6>Screen movement</h6>"},{"t":"table","head":["Key","Moves"],"rows":[["<code>Ctrl+f</code>","page forward"],["<code>Ctrl+b</code>","page backward"],["<code>Ctrl+d</code>","half page down"],["<code>Ctrl+u</code>","half page up"],["<code>H</code>","top of visible screen"],["<code>M</code>","middle of visible screen"],["<code>L</code>","bottom of visible screen"],["<code>zz</code>","center screen on cursor line"]]},{"t":"text","html":"<h6>Character search on current line</h6>"},{"t":"table","head":["Key","Effect"],"rows":[["<code>f x</code>","jump to next <code>x</code> on this line"],["<code>F x</code>","jump to previous <code>x</code> on this line"],["<code>t x</code>","jump to just before next <code>x</code>"],["<code>T x</code>","jump to just after previous <code>x</code>"],["<code>;</code>","repeat last f/F/t/T"],["<code>,</code>","repeat last f/F/t/T reversed"]]},{"t":"callout","kind":"tip","html":"<strong>Count prefix rule:</strong> almost any movement can be prefixed with a number to repeat it — <code>5j</code> moves down 5 lines, <code>3w</code> moves 3 words forward."}]},{"id":"insert-mode-entering-it","title":"Insert Mode — Entering It","blocks":[{"t":"table","head":["Key","Effect"],"rows":[["<code>i</code>","insert before cursor"],["<code>a</code>","insert after cursor (append)"],["<code>I</code>","insert at start of line"],["<code>A</code>","insert at end of line"],["<code>o</code>","open new line below, enter insert mode"],["<code>O</code>","open new line above, enter insert mode"],["<code>Esc</code>","return to Normal mode"]]}]},{"id":"editing-commands-normal-mode","title":"Editing Commands (Normal Mode)","blocks":[{"t":"text","html":"<p>Vim editing commands follow a grammar: <strong><code>[count] operator [count] motion</code></strong>. Once you know the operators and motions, they combine freely.</p>"},{"t":"text","html":"<h6>Core operators</h6>"},{"t":"table","head":["Operator","Meaning"],"rows":[["<code>d</code>","delete"],["<code>c</code>","change (delete + enter insert mode)"],["<code>y</code>","yank (copy)"],["<code>&gt;</code> / <code>&lt;</code>","indent / un-indent"]]},{"t":"text","html":"<h6>Combine with a motion</h6>"},{"t":"code","lang":"bash","code":"dw   → delete to next word\nd$   → delete to end of line\nd0   → delete to start of line\ndd   → delete whole line (doubling the operator = whole line)\ncw   → change to next word (delete + insert)\ncc   → change whole line\nyy   → yank whole line\ny$   → yank to end of line\n3dd  → delete 3 lines"},{"t":"text","html":"<h6>Single-key shortcuts (no motion needed)</h6>"},{"t":"table","head":["Key","Effect"],"rows":[["<code>x</code>","delete character under cursor"],["<code>X</code>","delete character before cursor"],["<code>D</code>","delete to end of line (= <code>d$</code>)"],["<code>C</code>","change to end of line (= <code>c$</code>)"],["<code>Y</code>","yank whole line (= <code>yy</code>)"],["<code>s</code>","delete char, enter insert (substitute)"],["<code>S</code>","delete line, enter insert"],["<code>r x</code>","replace single char under cursor with <code>x</code>"],["<code>R</code>","enter Replace mode (overtype until Esc)"],["<code>J</code>","join current line with next"],["<code>~</code>","toggle case of character under cursor"]]},{"t":"text","html":"<h6>Paste</h6>"},{"t":"table","head":["Key","Effect"],"rows":[["<code>p</code>","paste after cursor / below line"],["<code>P</code>","paste before cursor / above line"]]},{"t":"text","html":"<h6>Undo / redo</h6>"},{"t":"table","head":["Key","Effect"],"rows":[["<code>u</code>","undo"],["<code>Ctrl+r</code>","redo"],["<code>.</code>","repeat last change — extremely powerful, use it constantly"]]}]},{"id":"text-objects","title":"Text Objects","blocks":[{"t":"text","html":"<p>Text objects let operators target a logical unit rather than a raw motion — this is what separates fluent Vim use from beginner Vim use.</p>"},{"t":"text","html":"<p>Pattern: <strong><code>operator + i/a + object</code></strong></p>"},{"t":"list","items":["<code>i</code> = \"inner\" (just the content)","<code>a</code> = \"around\" (content + surrounding delimiter/whitespace)"]},{"t":"table","head":["Example","Effect"],"rows":[["<code>diw</code>","delete inner word (word only)"],["<code>daw</code>","delete a word (word + trailing space)"],["<code>ci\"</code>","change inside double quotes"],["<code>ca(</code>","change including the parentheses"],["<code>di{</code>","delete inside <code>{ }</code>"],["<code>dip</code>","delete inner paragraph"],["<code>dap</code>","delete a paragraph (incl. trailing blank line)"],["<code>dit</code>","delete inside an HTML/XML tag"]]}]},{"id":"visual-mode","title":"Visual Mode","blocks":[{"t":"table","head":["Key","Enters"],"rows":[["<code>v</code>","character-wise visual"],["<code>V</code>","line-wise visual"],["<code>Ctrl+v</code>","block-wise visual (select a rectangular column)"]]},{"t":"text","html":"<p>Once in visual mode, move the cursor to extend the selection, then apply an operator:</p>"},{"t":"code","lang":"bash","code":"v3w d     → select 3 words, delete them\nV j j d   → select 3 lines, delete them\nCtrl+v, move down, I, type text, Esc  → insert text at same column on multiple lines"},{"t":"text","html":"<p><code>gv</code> reselects the last visual selection.</p>"}]},{"id":"search-replace","title":"Search & Replace","blocks":[{"t":"text","html":"<h6>Searching</h6>"},{"t":"table","head":["Command","Effect"],"rows":[["<code>/pattern</code>","search forward"],["<code>?pattern</code>","search backward"],["<code>n</code>","repeat search, same direction"],["<code>N</code>","repeat search, opposite direction"],["<code>*</code>","search forward for word under cursor"],["<code>#</code>","search backward for word under cursor"]]},{"t":"text","html":"<h6>Find &amp; replace (Ex command)</h6>"},{"t":"code","lang":"bash","code":":s/old/new/         → replace first match on current line\n:s/old/new/g        → replace all matches on current line\n:%s/old/new/g       → replace all matches in entire file\n:%s/old/new/gc      → same, but confirm each replacement\n:5,10s/old/new/g    → replace only within lines 5–10\n:%s/\\<foo\\>/bar/g   → replace whole word \"foo\" only (word boundaries)"},{"t":"text","html":"<p>Vim search patterns support regex — <code>.</code> any char, <code>*</code> zero-or-more, <code>\\d</code> digit, <code>^</code>/<code>$</code> line anchors, <code>\\(...\\)</code> grouping.</p>"}]},{"id":"registers-clipboard-system","title":"Registers (Clipboard System)","blocks":[{"t":"text","html":"<p>Vim has multiple named \"clipboards\" called registers.</p>"},{"t":"table","head":["Register","Contents"],"rows":[["<code>\"\"</code>","default/unnamed register — used automatically by <code>y</code>/<code>d</code>/<code>p</code>"],["<code>\"0</code>","last yank (specifically — not overwritten by delete)"],["<code>\"1</code>–<code>\"9</code>","rolling history of deletes"],["<code>\"a</code>–<code>\"z</code>","manually named registers you control"],["<code>\"+</code>","system clipboard (cross-application copy/paste)"]]},{"t":"code","lang":"bash","code":"\"ayy    → yank current line into register a\n\"ap     → paste from register a\n\"+y     → yank into system clipboard\n\"+p     → paste from system clipboard"}]},{"id":"marks","title":"Marks","blocks":[{"t":"text","html":"<p>Marks let you bookmark a position and jump back to it.</p>"},{"t":"code","lang":"bash","code":"ma      → set mark \"a\" at cursor position\n`a      → jump to exact position of mark a\n'a      → jump to start of line containing mark a\n``      → jump to position before last jump (great for \"go back\")"}]},{"id":"macros","title":"Macros","blocks":[{"t":"text","html":"<p>Record a sequence of keystrokes and replay it — ideal for repetitive edits across many lines.</p>"},{"t":"code","lang":"bash","code":"qa          → start recording into register a\n...         → do your edits\nq           → stop recording\n@a          → replay the macro once\n5@a         → replay it 5 more times\n@@          → repeat the last macro played"}]},{"id":"buffers-windows-tabs","title":"Buffers, Windows & Tabs","blocks":[{"t":"text","html":"<p>These are three different concepts in Vim and are often confused:</p>"},{"t":"list","items":["<strong>Buffer</strong> = a file loaded in memory","<strong>Window</strong> = a viewport showing a buffer (you can have several windows showing different — or the same — buffers)","<strong>Tab</strong> = a collection of windows"]},{"t":"table","head":["Command","Effect"],"rows":[["<code>:e file.txt</code>","open file into a new buffer"],["<code>:ls</code> or <code>:buffers</code>","list open buffers"],["<code>:bn</code> / <code>:bp</code>","next / previous buffer"],["<code>:b 3</code>","switch to buffer number 3"],["<code>:split</code> or <code>:sp</code>","horizontal window split"],["<code>:vsplit</code> or <code>:vsp</code>","vertical window split"],["<code>Ctrl+w</code> then <code>h/j/k/l</code>","move between windows"],["<code>Ctrl+w</code> then <code>q</code>","close current window"],["<code>:tabnew file.txt</code>","open file in a new tab"],["<code>gt</code> / <code>gT</code>","next / previous tab"]]}]},{"id":"ex-command-line-commands-ranges","title":"Ex (Command-Line) Commands & Ranges","blocks":[{"t":"text","html":"<p>Any <code>:</code> command can be prefixed with a <strong>range</strong> telling it which lines to act on:</p>"},{"t":"table","head":["Range","Meaning"],"rows":[["<code>:5</code>","line 5"],["<code>:5,10</code>","lines 5 through 10"],["<code>:.,$</code>","current line to end of file"],["<code>:%</code>","whole file (shorthand for <code>1,$</code>)"],["<code>:'&lt;,'&gt;</code>","the last visual selection (auto-filled after selecting in Visual mode, then <code>:</code>)"]]},{"t":"text","html":"<p>Common Ex commands:</p>"},{"t":"code","lang":"bash","code":":set number         → show line numbers\n:set nonumber       → hide them\n:noh                → clear search highlighting\n:!ls                → run a shell command without leaving vim\n:r !date             → insert output of a shell command into the buffer"}]},{"id":"folding","title":"Folding","blocks":[{"t":"code","lang":"bash","code":"zf a{     → create a fold over \"a{\" text object (e.g. a code block)\nzo        → open fold under cursor\nzc        → close fold under cursor\nza        → toggle fold\nzR        → open all folds\nzM        → close all folds"}]},{"id":"configuration-vimrc","title":"Configuration — `~/.vimrc`","blocks":[{"t":"text","html":"<p>Vim reads <code>~/.vimrc</code> on startup. A solid practical starting config:</p>"},{"t":"code","lang":"vim","code":"set number              \" show line numbers\nset relativenumber      \" line numbers relative to cursor — makes counts easy\nset expandtab           \" use spaces instead of tabs\nset tabstop=4            \" a tab is 4 spaces wide\nset shiftwidth=4         \" indent width\nset autoindent           \" keep indentation on new lines\nset incsearch            \" search as you type\nset hlsearch             \" highlight all matches\nset ignorecase           \" case-insensitive search...\nset smartcase             \" ...unless the pattern has a capital letter\nset clipboard=unnamedplus \" use system clipboard by default\nsyntax on                 \" syntax highlighting"}]},{"id":"vim-quick-cheat-sheet","title":"Vim Quick Cheat Sheet","blocks":[{"t":"code","lang":"bash","code":"NAVIGATE      h j k l    0 ^ $    gg G    w b e    f{char}\nINSERT        i a I A o O\nEDIT          x dd dw d$   cc cw c$   yy yw   p P   u Ctrl+r   .\nVISUAL        v V Ctrl+v\nSEARCH        /pat  ?pat  n N  :%s/old/new/g\nSAVE/QUIT     :w  :q  :wq  ZZ  :q!"}]},{"id":"philosophy","title":"Philosophy","blocks":[{"t":"text","html":"<p>Nano is a straightforward, modeless text editor — what you see is what you get, no Normal/Insert distinction. Every shortcut is shown at the bottom of the screen, which makes it the default choice when you just need to edit a file right now without a learning curve.</p>"},{"t":"callout","kind":"tip","html":"<strong>Notation used everywhere in Nano's own docs:</strong> "},{"t":"list","items":["<code>^</code> means <strong>Ctrl</strong> — <code>^X</code> = <code>Ctrl+X</code>","<code>M-</code> means <strong>Alt/Meta</strong> — <code>M-U</code> = <code>Alt+U</code>"]}]},{"id":"starting-nano","title":"Starting Nano","blocks":[{"t":"code","lang":"bash","code":"nano file.txt          # open (or create) a file\nnano +42 file.txt        # open at line 42\nnano -l file.txt         # force line numbers on\nsudo nano /etc/hosts      # edit a root-owned file"}]},{"id":"file-operations","title":"File Operations","blocks":[{"t":"table","head":["Shortcut","Effect"],"rows":[["<code>Ctrl+O</code>","Write out (save) — you'll be prompted to confirm the filename"],["<code>Ctrl+X</code>","Exit (prompts to save if there are unsaved changes)"],["<code>Ctrl+R</code>","Read/insert another file's contents at the cursor"],["<code>Ctrl+S</code>","Save (in newer nano versions), without the write-prompt"]]}]},{"id":"navigation","title":"Navigation","blocks":[{"t":"table","head":["Shortcut","Effect"],"rows":[["Arrow keys","Move cursor"],["<code>Ctrl+F</code> / <code>Ctrl+B</code>","Forward / back one character"],["<code>Ctrl+P</code> / <code>Ctrl+N</code>","Previous / next line"],["<code>Ctrl+A</code>","Go to start of line"],["<code>Ctrl+E</code>","Go to end of line"],["<code>Ctrl+Y</code>","Page up"],["<code>Ctrl+V</code>","Page down"],["<code>Ctrl+_</code> then a number","Go to a specific line (and column)"],["<code>M-\\\\</code>","Go to first line of file"],["<code>M-/</code>","Go to last line of file"]]}]},{"id":"editing","title":"Editing","blocks":[{"t":"table","head":["Shortcut","Effect"],"rows":[["<code>Ctrl+K</code>","Cut current line (or selected region) into the clipboard"],["<code>Ctrl+U</code>","Paste (uncut) whatever was last cut"],["<code>M-6</code>","Copy current line (or selection) without cutting it"],["<code>Ctrl+Shift+6</code> or start selection with <code>M-A</code>","Begin a text selection (then move cursor to extend it)"],["<code>Ctrl+D</code>","Delete character under cursor"],["<code>Backspace</code>","Delete character before cursor"],["<code>M-U</code>","Undo"],["<code>M-E</code>","Redo"],["<code>Ctrl+T</code>","Run the spell-checker (if installed)"],["<code>M-J</code>","Justify the current paragraph (wrap text neatly)"]]},{"t":"callout","kind":"tip","html":"<strong>Selecting and cutting a block:</strong> move to the start, <code>Ctrl+^</code> (or <code>M-A</code>) to mark the start, move the cursor to the end of the region, then <code>Ctrl+K</code> cuts the whole selection at once (instead of line by line)."}]},{"id":"search-replace","title":"Search & Replace","blocks":[{"t":"table","head":["Shortcut","Effect"],"rows":[["<code>Ctrl+W</code>","Search forward"],["<code>Ctrl+W</code> then <code>Ctrl+R</code>, or <code>Ctrl+\\\\</code>","Search and replace"],["Inside a search prompt, <code>Alt+C</code>","Toggle case sensitivity"],["Inside a search prompt, <code>Alt+R</code>","Toggle regular-expression mode"],["<code>Alt+W</code>","Repeat the last search"]]},{"t":"callout","kind":"tip","html":"<strong>Replace workflow:</strong> "},{"t":"code","lang":"bash","code":"Ctrl+\\      → opens \"Search (to replace):\" prompt\ntype pattern, Enter\ntype replacement, Enter\n→ Nano asks Yes/No/All/Cancel for each match"}]},{"id":"multiple-buffers-files","title":"Multiple Buffers (Files)","blocks":[{"t":"table","head":["Shortcut","Effect"],"rows":[["<code>Ctrl+R</code> then a filename","Insert another file into the current buffer"],["<code>M-&lt;</code> / <code>M-&gt;</code>","Switch to previous / next open buffer (if nano was started with multiple files or <code>-F</code>/multibuffer mode enabled)"],["<code>nano -F file1 file2</code>","Open multiple files as separate buffers in one session"]]}]},{"id":"display-options","title":"Display Options","blocks":[{"t":"table","head":["Shortcut","Effect"],"rows":[["<code>Ctrl+C</code>","Show current cursor line/column position"],["<code>M-N</code>","Toggle line numbers"],["<code>M-P</code>","Toggle display of whitespace characters"],["<code>M-$</code>","Toggle \"soft wrap\" of long lines"],["<code>M-Y</code>","Toggle syntax highlighting on/off"]]}]},{"id":"configuration-nanorc","title":"Configuration — `~/.nanorc`","blocks":[{"t":"code","lang":"bash","code":"set linenumbers          # always show line numbers\nset tabsize 4              # tab width\nset tabstospaces           # convert tabs to spaces\nset autoindent             # keep indentation on new lines\nset mouse                   # enable mouse support\ninclude \"/usr/share/nano/*.nanorc\"   # enable syntax highlighting for common languages"}]},{"id":"nano-quick-cheat-sheet","title":"Nano Quick Cheat Sheet","blocks":[{"t":"code","lang":"bash","code":"SAVE/EXIT   ^O (write out)   ^X (exit)\nNAVIGATE    arrows   ^A (line start)   ^E (line end)   ^Y/^V (page up/down)\nCUT/PASTE   ^K (cut line)   ^U (paste)   M-6 (copy)\nSEARCH      ^W (search)   ^\\ (replace)   M-W (repeat search)\nUNDO/REDO   M-U / M-E"}]},{"id":"part-3-which-one-should-you-use","title":"PART 3: Which One Should You Use?","blocks":[{"t":"table","head":["Situation","Use"],"rows":[["Quick edit of a config file over SSH","<strong>Nano</strong> — zero learning curve, shortcuts on-screen"],["You edit code/config for hours daily","<strong>Vim</strong> — the modal grammar pays for itself fast at that volume"],["Editing on a minimal/embedded system","Whichever is installed — Vi (the original, always present) is the fallback if neither Vim nor Nano exists"],["Scripted, repetitive text transformations","<strong>Vim</strong> — macros and Ex-command ranges do in seconds what takes minutes by hand"],["You just SSH'd into a server for one line change","<strong>Nano</strong>"]]},{"t":"callout","kind":"tip","html":"<strong>One thing worth knowing:</strong> almost every minimal Linux install ships with <code>vi</code> even when <code>vim</code> isn't installed — so knowing at least <code>i</code> (insert), <code>Esc</code>, and <code>:wq</code> (save+quit) in bare Vi is a genuine survival skill for server work, even if Nano is your daily driver."}]}]}]};
